'use strict';

/* v7 剧本库：六部作品的正文、选项与结局走向。由 content/build_story.py 生成。 */

const STORY6={"穗骨原":{"no":1,"name":"穗骨原","subtitle":"谷子、祖骨、和一块不肯松手的田","through":"父亲想把地赎回来，到死没赎成。你从恨他，到懂他，到发现自己也在做同样的事。","cast":[{"id":"father","name":"穗老六","role":"佃农","tag":"父"},{"id":"mother","name":"棠娘","role":"看水人","tag":"母"},{"id":"sibling","name":"穗禾","role":"拾穗","tag":"姐"}],"main":[{"id":"sui_m01","act":"main","age":[0,0],"mode":"montage","title":"落地","opening":"腊月里，土屋烧着谷草，烟从门缝往外钻。接生婆把你倒提起来，拍了两下，你才哭出声。父亲在门外攥着那把豁口镰刀，刃上的冻泥没擦。母亲在炕上说，轻点。父亲把镰刀搁在门槛外，进来看你一眼：又一个吃饭的。梁上挂着半袋谷，袋口扎得紧。头一年你活在别人背上，姐姐背你去渠边，母亲把米汤嚼细了喂你。你学会听脚步声认人。","ask":"满岁那天，桌上摆了三样东西，你先抓哪样？","days":360,"npc":"","memory":"梁上的半袋谷","choices":[{"title":"抓住镰刀柄","desc":"你把豁口镰刀的木柄抱住，谁抽也不松手。","hint":"母亲看了父亲一眼。","tone":"carry","outcome":"父亲没笑，只把镰刀连着你的手一起提了提，说：沉。母亲把你的手指一根一根掰开，指甲在她手背上划出白印。她把桌上的木梳收进柜里，没说话。那年秋天，父亲给你削了一把小木镰，刃是假的，柄是真的。你走到哪都攥着它，后来丢在渠边，找了三天。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2},"flag":"","thread":"小木镰丢在渠边没找回来"}},{"title":"够那半袋谷","desc":"你越过镰刀和木梳，朝梁下的半袋谷爬。","hint":"母亲抱开你时手在抖。","tone":"seek","outcome":"你抓住袋角，麻布上的谷壳扎进指缝。母亲把你抱起来，袋口松开一道缝，几粒谷落在炕席上。她一粒一粒捡回袋里，捡了很久。父亲说：小人精。那年冬天，她每次舀谷都先看一眼梁上，再低头数一遍。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}},{"title":"攥住母亲衣角","desc":"你攥住她的衣角，她一动你就哭。","hint":"她那天没去看水。","tone":"family","outcome":"母亲只好把你抱起来，一直抱到灶边。那天渠上换了别人看水，咱家的田口被挖窄了一寸。晚上她把你放在炕上，又提着木锹出门，回来时鞋上全是泥。她没跟任何人说这件事。第二天她的手腕肿了，舀水时换了左手。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}}]},{"id":"sui_m02","act":"main","age":[1,3],"mode":"dialogue","title":"渠边","opening":"你三岁那年春上，姐姐背你去渠边找母亲。母亲是看水人，裤腿卷到膝盖，站在渠里，用一把木锹把水往各家的田口分。上游王二家的水口挖得宽，水流到他家地里就慢了，到咱家垄头，只剩一层湿泥。母亲看见了，没说话，先看了一眼王二家的脸。父亲在自家田头磨那把豁口镰刀，锉刀声隔着水一阵一阵。","ask":"渠里的水不够分，你想怎么做？","days":120,"npc":"mother","memory":"母亲划的水线","choices":[{"title":"下渠堵漏","desc":"你下到渠里，用胸口堵住田埂上的漏眼。","hint":"你在炕上烧了三天。","tone":"help","outcome":"水凉得像刀，泥没到你的腰。母亲把你拎起来，骂了一句，声音发抖。漏眼堵住了，水慢慢漫过咱家的垄沟。你当晚发热，母亲守了三夜，第四天你退烧，她靠在门框上睡着了，手里还攥着擦身的布。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":""}},{"title":"告发王二家","desc":"晚饭时你告诉父亲，王二家把水口挖宽了。","hint":"两家从此不搭话。","tone":"tell","outcome":"父亲放下碗，提了镰刀出门。渠边吵了半宿，王二家的狗叫到天亮。第二天，王二娘把借咱家的那半升盐要了回去。母亲没说你，只把你的碗往你面前推了推。那年插秧，咱家最后才放上水，秧苗比别家矮了一截。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"王二娘要回了那半升盐"}},{"title":"学母亲看水","desc":"你蹲在岸上，看母亲怎么量水线，记住每一道口子。","hint":"水不认记性。","tone":"learn","outcome":"母亲用木锹在渠底划了一道印，说：到这儿，就够了。你点头，把印记在心里。姐姐在旁边撇嘴：记这个，能当饭吃？你没理她。第二天你去看，印被水冲平了。母亲重新划，说：水天天变，人得天天来。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":3},"flag":"","thread":""}}]},{"id":"sui_m03","act":"main","age":[4,4],"mode":"dialogue","title":"半袋谷","opening":"开春前，粮缸见了底。母亲用陶碗把缸底最后一点谷刮出来，倒进那条补过三回的麻袋，扎上口，正好半袋。她把袋口解开，用升子一升一升地量：七升倒在左边碗里，留种；两升倒在右边碗里，换盐。剩下的一把，她攥了攥，放进留种那边。盐贩子的车铃在门外响了一下。她抬头，先看你的脸。父亲从田里回来，站在门口看了一眼，说：种。","ask":"盐贩子进了门，你做什么？","days":30,"npc":"mother","memory":"半袋谷分两碗","choices":[{"title":"护住种袋","desc":"你趴到种袋上，把长命锁从脖子上扯下来递过去。","hint":"那把锁再没赎回来。","tone":"protect","outcome":"盐贩子捏着那把锁，掂了掂，留下三块粗盐。母亲没拦，只在灶边站了很久。那年春天你的脖子空着，姐姐说像少了颗牙。后来你长大了，母亲还提过一次：锁是你外婆打的，上头刻了个穗字。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"抓一把谷种","desc":"你从留种碗里抓了一把，塞进嘴里嚼。","hint":"西垄空了一截。","tone":"greed","outcome":"生谷子扎嘴，你嚼了半天咽不下去。母亲看见了，没骂，只把剩下的谷种重新数了一遍。开春播到西头，少了一小把，那一截垄空着，长满了灰灰菜。秋收时父亲从那儿过，用镰刀背敲了敲你的头，很轻。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"哀":1},"flag":"","thread":""}},{"title":"劝母亲多换盐","desc":"你扯着她的袖子说，多换点盐，种少些不打紧。","hint":"借种的字据按了手印。","tone":"practical","outcome":"母亲看了你一眼，从留种碗里又倒了一升给盐贩子。那晚的菜有了咸味，你多吃了半碗。开春家里没够种，父亲去谷债盟借了半斗，按了手印。那张字据后来压在田契下面，边角也粘了米汤。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":"借种的字据压在田契下"}}]},{"id":"sui_m04","act":"main","age":[7,7],"mode":"narration","title":"田埂上的字","opening":"七月里，谷子刚抽穗。你蹲在田埂上拔草，一个过路的老账房停下来问路。他背着一只旧褡裢，鞋面上全是灰。你说不清路，他就在田埂的软土上折了根柳枝，先写了一个穗字，又写了一个生字。他说：这是你的名字。你不信。他说：你叫什么？你说：穗生。他指了指地上：喏。你看了很久，觉得那两个字像两块不认识的田。远处父亲在磨那把豁口镰刀，锉刀声一下一下。","ask":"老账房起身要走，你做什么？","days":15,"npc":"","memory":"树枝写的名字","choices":[{"title":"跟他学写","desc":"你捏着柳枝，跟着他往渡口走，一路学写。","hint":"那天的草没拔完。","tone":"learn","outcome":"他走得不快，走三步写一个字。到村口，你学会了穗、生，还有棠——母亲的名字。他说：字不要钱，闲工夫才要钱。你回家时天黑了，草还剩半垄。父亲没问你去哪，只说：明天早起。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"惧":1},"flag":"learned_name","thread":""}},{"title":"写母亲的名字","desc":"你跑回家，把棠字写给母亲看，柳枝都攥热了。","hint":"老账房在田埂上走远了。","tone":"warm","outcome":"母亲正在淘米，手上都是水。她看了半天，说：这是啥？你说：你的名字。她把手在围裙上擦干，又看了一遍，说：不像。晚上她把这个字描在灶灰上，描了三回，第四回被风吹平了。第二天她没再问，出门前把灶灰扫了。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"母亲在灶灰上描自己的名字"}},{"title":"抹掉那个字","desc":"你用鞋底把字抹平，说这不是我的名字。","hint":"你一直写不好那个穗字。","tone":"rebel","outcome":"老账房看了你一眼，没笑，也没生气，把柳枝插在田埂上就走了。你回到家，晚上睡不着，用指头在肚皮上画那个字，画到一半忘了。第二天你去看，柳枝还在，字被牛踩没了。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"sui_m05","act":"main","age":[11,11],"mode":"dialogue","title":"鞋底的票","opening":"入冬前，姐姐从穗仓城帮工回来，给你带了一块麦芽糖。糖粘在牙上，你含了半宿。半夜你起来解手，看见她蹲在灶前烤鞋，鞋底冒出个纸角。她抽出来看了一眼，又塞回去。你认得那两个字——穗仓，田埂上老账房写过。她回头看见你，说：敢说出去，我把你扔渠里。","ask":"姐姐要去城里，你怎么做？","days":20,"npc":"sibling","memory":"鞋底下的船票","choices":[{"title":"塞给她两升穗","desc":"你把藏在墙洞里的两升穗子倒进她的包袱。","hint":"那个冬天你总在灶边站着。","tone":"help","outcome":"姐姐掂了掂包袱，没看你，说：谁要你的。第二天她把穗子背到鱼尾泽卖了，票还在鞋底。船期在腊月，她没走，因为母亲咳了半冬。你饿得夜里啃灶灰里的红薯皮，她看见了，把自己的半碗粥倒给你，说：别跟娘说。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"告诉母亲船票","desc":"你把鞋底的事告诉母亲，母亲正在补父亲的裤脚。","hint":"她一年没叫过你的名字。","tone":"tell","outcome":"母亲没抬头，针在布上停了一下。第二天，姐姐的鞋被拆了，鞋底换成新的，纸票不见了。姐姐没哭，也没闹，只是从那天起叫你喂。过了一年，她才重新叫你的名字，像从牙缝里抠出来的。","eff":{"bond":-5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_sister_ticket","thread":"她一年没叫你的名字"}},{"title":"求她带上你","desc":"你抱住她的腿，说走的时候带上我，我不吃闲饭。","hint":"她把票撕了，扔进渠里。","tone":"family","outcome":"姐姐愣了一下，抬脚想甩开你，没甩掉。她蹲下来，把鞋脱了，抽出那张票，当着你的面撕成四片，扔进渠里。纸片在水上转了两圈，沉了。她说：行了吧。那年腊月船开的时候，她在家剁猪菜，刀落得很重。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"","thread":""}}]},{"id":"sui_m06","act":"main","age":[13,13],"mode":"dialogue","title":"蝗","opening":"蝗虫是午后到的。先是远处一层黄雾，后来听见响，像下雨，可天是晴的。晒场上有人敲锣，一声接一声，全村的人都往田里跑。父亲手里攥着那把豁口镰刀，把一把扫帚塞给你，又夺回去，说：回屋。母亲从渠那边跑过来，头发散了，抓住你的胳膊说：留下，敲盆。父亲说：回去。母亲说：留下。两个人都没看你，眼睛盯着各自的手。","ask":"父亲和母亲都看着田，你呢？","days":10,"npc":"father","memory":"锣声响了一夜","choices":[{"title":"跟父亲回家","desc":"你低下头，跟着父亲往家走，门闩在你身后插上。","hint":"母亲半夜才回来。","tone":"obey","outcome":"你坐在门槛上，隔着门板听锣声，一声比一声远。梁上的半袋谷在黑暗里晃。母亲后半夜才回来，头发上挂着死蝗虫，手指被铜盆沿磨破了。她看见你，说：没睡？就再没别的话。西垄的谷子那夜吃光了。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"惧":3,"哀":4},"flag":"","thread":"西垄的谷子那夜吃光了"}},{"title":"留下来敲盆","desc":"你抓起铜盆，站到母亲身边，敲到天亮。","hint":"父亲三天没跟你说话。","tone":"stay","outcome":"铜盆敲裂了一道口，你的虎口也裂了。蝗虫撞在脸上，像热沙子。天快亮时，父亲从西头回来，看见你，站了一下，把身上的袄脱下来扔给你，说：回。那件袄上有蝗虫的汁，洗了三遍还有味。东垄保住了半截。父亲三天没跟你说话。","eff":{"bond":4,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}},{"title":"先藏好种袋","desc":"你跑回家，把半袋谷塞进祖骨罐边的土洞里。","hint":"你两边都没站。","tone":"sneak","outcome":"你把袋口扎紧，塞进村后祖骨罐旁的土洞，用碎瓦盖住。回到田里时，锣已经哑了，蝗虫落了一地，像一层会动的壳。母亲看见你，问：去哪了？你说：解手。第二年开春，那半袋谷还在，没有发霉。你一直没告诉他们。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":1},"flag":"hid_seed_sack","thread":""}}]},{"id":"sui_m07","act":"main","age":[17,17],"mode":"dialogue","title":"田契","opening":"冬至那晚，父亲把灶膛封了，从炕席底下摸出一个竹筒。筒口塞着布，布上有一股陈米味。他倒出田契，铺在磨盘上，四角用碗压住。纸边有一块用米汤粘过，母亲的手艺。他让你把灯端近，指头从东边数过去：一垄，两垄，三垄。他说：你爷的骨埋在这垄，靠槐树那头。记住。筒底还有一截麻绳，绳上磨出一道深痕，他说：罐上的，换过三回，就这截没舍得。","ask":"灯在你手里，你要问什么？","days":10,"npc":"father","memory":"第三垄的祖骨","choices":[{"title":"按手在田契上","desc":"你跪下，把手按在田契上，跟着他念祖骨的位置。","hint":"你的膝盖记住了那块砖。","tone":"obey","outcome":"父亲的手压在你的手背上，很粗，很热。他说：地没了，骨不能没。你念了三遍，第三遍他跟着你念。那晚你梦见一垄一垄的土在自己身下翻身。第二年有人来提亲，你没应，你说家里有地要种。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"accepted_land_burden","thread":"你答应过父亲守住第三垄"}},{"title":"问地是谁的","desc":"你指着契上的红印，问这地如今还算不算咱的。","hint":"他把赎字咽了回去。","tone":"ask","outcome":"父亲的手停在红印上，停了很久。他说：契是咱的，地不是。说完把契折起来，折得很慢，像怕折断了什么。他出去修犁，锉刀响到半夜。母亲在灶边坐着，没点灯。你第一次知道，他每年秋后去穗仓城，不是去卖谷。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"knows_land_not_ours","thread":""}},{"title":"替他收好田契","desc":"你把契纸按原样折好，塞回筒里，说先吃饭。","hint":"你没问赎地要多少年。","tone":"dodge","outcome":"父亲看了你一会儿，把筒子塞回炕席底下。那晚的粥很稀，谁都没说话。后来你想起这件事，最清楚的是他指甲缝里的黑泥，不是那个赎字。开春他照旧去穗仓城，你没问，他也没说。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4},"flag":"","thread":""}}]},{"id":"sui_m08","act":"main","age":[25,25],"mode":"dialogue","title":"渠口的夜","opening":"春灌的水下来时，上游王家把水口往自家田里挪了半尺。水到咱家垄头，只剩一层湿泥。你扛着锹去渠边，父亲已经在那儿了，手里还是那把豁口镰刀，刃口在月光下缺了一块。王二家的儿子坐在水口上，说：水往低处走，天定的。父亲没说话。你把锹插进泥里，站住了。","ask":"水口这一夜，你打算怎么站？","days":10,"npc":"father","memory":"渠口站了一夜","choices":[{"title":"横锹守水口","desc":"你把锹横在水口上，谁来也不让，站到天亮。","hint":"你眉上后来留了道疤。","tone":"defy","outcome":"后半夜王二家的儿子来扒水口，你拿锹柄挡，他捡石头砸，石头划过你眉骨，血糊了半只眼。你没退。天亮水漫进咱家垄沟，父亲在渠对面看着，一句话没说。回家他从灶膛下摸出酒坛，倒满一碗推过来：喝。坛口麻绳的旧痕，和祖骨罐上那道一样。他第一次给你倒酒。","eff":{"bond":4,"health":-3,"reputation":3,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"爱":2},"flag":"stood_at_canal","thread":""}},{"title":"去请谷债盟","desc":"你连夜走七里地去敲谷债盟的门，请人带水册来。","hint":"村里给你起了个外号。","tone":"rule","outcome":"盟老天亮才来，拿着水册一尺一尺量，把水口判回原处，还罚了王家两斗谷。水是有了，可王家从此见了咱家的人就啐一口。父亲在渠边听判，手一直攥着镰刀柄，没松开。回家他倒酒，倒到一半停了停，说：下回，先跟我说。那是他第一次给你倒酒。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}},{"title":"回家取袄","desc":"你看父亲只穿单衣，跑回家取袄，再回渠边。","hint":"他那年咳了一冬。","tone":"family","outcome":"你跑回家，母亲没睡，把袄递给你，又塞了个烤红薯。回到渠边，水口已被扒开，父亲一个人用身子堵着，水从他裤腿两边淌。你把袄披上，他骂：回去。你没回，站到他旁边。天亮水回来了。到家他摸出酒坛，第一碗推给你，手一直在抖。他这辈子第一次给你倒酒。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"惧":2},"flag":"","thread":"他那年咳了一冬"}}]},{"id":"sui_m09","act":"main","age":[26,28],"mode":"dialogue","title":"一垄聘礼","opening":"二十六岁那年，母亲托人去下湾说亲。女方叫杏，家里没有田，租着别人一垄水田，娘眼不好，缺劳力。她娘回了两个说法：要么你过去入赘三年，把她家的田种完，再带杏回骨沟村；要么拿一垄田的价做聘，人直接领走。咱家只有租来的三垄。母亲把柜底翻了一遍，翻出两块布、一对银耳环——是她出嫁时戴的。父亲坐在门槛上磨那把豁口镰刀，磨到天黑，说：入赘，户册上就不是穗家的人。","ask":"一垄田拿不出，这门亲怎么定？","days":90,"npc":"mother","memory":"一垄田的聘礼","choices":[{"title":"去鱼尾泽扛包","desc":"你去鱼尾泽盐行扛了三个月麻包，把一垄田的价挣回来。","hint":"插秧那半月你不在家。","tone":"grind","outcome":"回来时你把钱交到杏的娘手里，人瘦了一圈。她摸了摸你的手，说：手是粗的，心是实的。成亲那天父亲没来吃席，他在田里补埂，补到月亮出来。你端酒去，他接了，说：肩上有伤，少喝。那年插秧晚了半月，咱家的秧比别家矮一截。","eff":{"bond":3,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":1},"flag":"","thread":""}},{"title":"入赘三年","desc":"你答应去下湾入赘三年，种她家的田，三年后带杏回来。","hint":"这三年父亲的腰弯下去了。","tone":"obey","outcome":"户册上你改姓杏，谱上还是穗。你在下湾种了三年田，渠是杏家的，埂是杏家的，连锄头都是她家的。第三年秋后你带杏回骨沟村，父亲到村口接，腰比走时弯了一截。他把豁口镰刀塞给你，说：你家的地，你自己看。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"uxorilocal_three_years","thread":"父亲这三年弯了腰"}},{"title":"去下湾说亲","desc":"你空着手去下湾，把家里的底一五一十说给杏的娘听。","hint":"杏自己提着包袱跟了你。","tone":"honest","outcome":"杏的娘听完，把茶碗推远了些，说：我闺女不是去受苦的。杏从里屋出来，把一只包袱放在桌上，说：我跟他走。她娘没拦，也没送。成亲那天下雨，杏的鞋陷在泥里，你背她过的渠。她娘到死没再进过咱家的门。","eff":{"bond":2,"health":-1,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"杏的娘到死没进过咱家门"}}]},{"id":"sui_m10","act":"main","age":[30,30],"mode":"dialogue","title":"鞋底的城","opening":"穗禾那年终于要走。她把那张船票从鞋底抽出来，纸边磨得像布。她说穗仓城的米行招缝袋的女工，管饭。母亲在灶边没回头，说：家里不缺你一口。穗禾说：我缺。她把床底下的旧木箱拖出来，箱底压着这些年拾穗攒的谷子，装了半袋。父亲在院里磨镰刀，锉刀声停了。","ask":"船在鱼尾泽等，你送不送她？","days":20,"npc":"sibling","memory":"鞋底那张船票","choices":[{"title":"当簪给她盘缠","desc":"你把杏的陪嫁银簪当了，把钱塞进穗禾箱底，不让她知道。","hint":"杏找了那簪子半年。","tone":"help","outcome":"船开时穗禾没回头，只把箱子举了举。半年后她托人带回一块洋布、一包城里的糖。杏把布裁了件袄，穿了三年，袖口磨破才知道当簪的事。她没闹，只把袄叠好放进箱底，说：留着。此后她梳头都用手拢，再没戴过簪子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"交出船票","desc":"你连夜把船票的事告诉母亲，母亲把她的鞋锁进柜里。","hint":"她三年没叫你名字。","tone":"report","outcome":"穗禾走不成，在村里又待了三年。她每天去渠边拾穗，回来把穗子摔在灶台上。三年后母亲自己把鞋还给她，说：走吧。她走那天没跟任何人说，只在你门槛上放了一双补好的鞋。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"stopped_sister","thread":"她三年没叫你名字"}},{"title":"送到鱼尾泽","desc":"你替她背箱子到鱼尾泽，回来只说没追上。","hint":"母亲在门口等了三个晚上。","tone":"sneak","outcome":"船离岸时穗禾把头上的木梳扔给你，说：给娘。你回到家，母亲坐在门槛上纳鞋底，没抬头，问：追上了？你说：没有。她把手里的针别在布上，说：你鞋底的泥是鱼尾泽的。之后她再没问过。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"lied_about_sister","thread":"母亲知道你说谎，没拆穿"}}]},{"id":"sui_m11","act":"main","age":[33,33],"mode":"dialogue","title":"门帘","opening":"杏从后半夜疼到晌午，还没生。接生婆把门帘放下，只让母亲进出。灶上烧着一锅水，梁上的半袋谷解开了口。父亲蹲在院角，用那把豁口镰刀削一根木棍，削一截，看一眼门口。母亲出来说：去祖骨罐前烧三张纸。又说：别进屋。","ask":"门帘里又传来一声，你往哪走？","days":10,"npc":"mother","memory":"门帘里的一声","choices":[{"title":"去祖骨罐前烧纸","desc":"你按母亲说的，去村后烧了三张纸，磕了三个头。","hint":"你回来时孩子已经哭了。","tone":"pray","outcome":"纸灰被风吹到罐身上，那道绳痕里落了一层。你磕完头往回跑，进门时孩子已经裹在旧袄里，杏躺着，头发全湿。她看了你一眼，问：外头冷不冷。你说不冷。她说：哦。母亲给孩子起名穗宁。后来杏跟邻居说，生穗宁那晌午，你在外头烧纸。她说的时候在择菜，没抬头。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":2,"惧":2},"flag":"","thread":""}},{"title":"掀帘进屋","desc":"你不顾母亲拦，掀帘进去，握住杏的手。","hint":"接生婆说血污冲了田气。","tone":"brave","outcome":"接生婆骂了一句，没赶你。杏的手像铁钳，掐得你手背出血。孩子落地时你看见一团紫红，接生婆把她倒提起来，你听见第一声哭。母亲在门外站着，没进来。那年秋天咱家田里生了虫，母亲说是产房的血气冲了田。你没接话。","eff":{"bond":5,"health":-2,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"惧":2},"flag":"","thread":""}},{"title":"去下湾请大夫","desc":"你转身往村口跑，去下湾请大夫，鞋跑掉了一只。","hint":"你回来时门帘已经挂起。","tone":"risk","outcome":"大夫赶到时孩子已经生了，脐带都剪了。他在门外收了手，说：来晚了。你进屋，杏看着你脚上的泥，说：你跑啥，我又不是头一回生。她说完自己笑了，笑到一半停住。后来她再没提过那天。母亲给孩子起名穗宁。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}}]},{"id":"sui_m12","act":"main","age":[40,40],"mode":"narration","title":"他留下的","opening":"父亲是秋后走的。头天他还在院里磨那把豁口镰刀，说：开春把西头那道埂补补。早上母亲叫他吃饭，他没应。你进去，他手搭在炕沿上。柴房里母亲搬开柴垛，露出祖骨罐，说：你爹怕人收走，三年前挪的，第三垄是空的。回屋她倒出竹筒：田契、麻绳、二十六张收条，从你十五岁排到今年；筒底有一小包谷种，每年留一把，一把没动。少，装不满一只竹筒。多，你数到半夜。","ask":"丧事要办，父亲留下的东西，你先动哪样？","days":30,"npc":"","memory":"二十六张收条","choices":[{"title":"卖掉半袋谷","desc":"你把梁上留种的半袋谷背到鱼尾泽卖了，先办丧事。","hint":"开春没有种，你按了手印。","tone":"sell","outcome":"丧事办得体面，棺木是松木的，没裂。开春没有种，你去谷债盟借了半斗，按了手印。母亲问起梁上那只袋，你说吃了。她看着空梁看了很久，说：他要是知道拿种换棺材，得骂人。她没骂你。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"sold_seed_for_funeral","thread":"梁上空了"}},{"title":"押田契办丧事","desc":"你把田契押给谷债盟，换丧事和过冬的粮。","hint":"母亲半年没提赎字。","tone":"deal","outcome":"谷债盟的人把契纸卷走，说三年为期。母亲坐在炕上，看着竹筒里剩下的收条，说：你爹攒了二十六年。你说：人得先埋。她点头，点得很慢。第三年你凑够了去赎，契纸边角已经磨毛。赎回来那天，母亲把它压回炕席底下。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"pawned_land_deed","thread":""}},{"title":"烧在他灵前","desc":"你把田契放进火盆，烧在父亲灵前。","hint":"母亲伸手拦，又缩回去。","tone":"quit","outcome":"火苗舔上契纸，红印先黑，字一个一个卷起来。母亲伸出手，停在半空，又缩回去。她说：也好，他到死都攥着这张纸。谷债盟的人来问契呢，你说烧了。他看了你半天，说：你比你爹狠。那年冬天你们没粮，杏回下湾借了一斗。","eff":{"bond":-2,"health":-2,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"burned_land_deed","thread":"你比你爹狠"}}]},{"id":"sui_m13","act":"main","age":[46,47],"mode":"dialogue","title":"丰年","opening":"那年的谷子压弯了秆，是二十年来最好的一季。晒场上铺满了，连祖骨罐边都摊了谷。村里杀了一口猪，秋祭的锣敲到半夜。人人都在笑，咱家没人笑。母亲盛了一碗新米饭放在灶头，摆到凉。父亲没等到这样的年成。杏怀着第二胎，闻不得肉味，坐在灶边烧火。也就是那天，穗禾从穗仓城回来——她在米行缝了十几年麻袋，肺缝坏了。她瘦得只剩一把骨头，提着一只樟木箱，站在场边，没人认出来。","ask":"晒场上都是人，她站在场边，你怎么接她？","days":40,"npc":"sibling","memory":"丰年里的咳嗽","choices":[{"title":"接她坐头席","desc":"你拨开人群走过去，接过箱子，让她坐头席。","hint":"杏的脸白了一下。","tone":"warm","outcome":"穗禾坐在头席上，捧着那碗新米饭，没动筷子。村里人问她城里的事，她只说：仓城的米比咱的白。说完低头扒了一口，嚼了很久。杏在灶边忙，没过来，半个月没跟你同桌吃饭。夜里穗禾咳了半宿，杏起来熬了一碗姜汤，放在她门口，没进门。她住了下来。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"杏把姜汤放在门口"}},{"title":"问她住几天","desc":"你接过箱子，低声问她这次住几天，城里还有没有活。","hint":"她把手从箱柄上松开。","tone":"ask","outcome":"穗禾看了你一眼，说：住几天再说。她没坐席，把箱子提到灶房，自己盛了半碗剩饭。母亲拉她，她说路上吃过了。第二天她把箱子打开，里面是给母亲的一双棉鞋、给杏的一块布、给孩子的一把木梳，没有她自己的东西。她把棉鞋放在母亲脚边，住下了。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"","thread":""}},{"title":"先领她去罐前","desc":"你接过箱子，先领她到柴房祖骨罐前，说：回来了。","hint":"席上少了你，杏一个人张罗。","tone":"family","outcome":"穗禾在罐前站了很久，伸手摸那圈绳痕，说：爹，我回来了。她没哭，只把箱子放在罐边，从里头取出一双棉鞋，说是给爹做的，做了三年。鞋底纳得密，你替她烧在罐前。晒场上锣还在响，杏一个人在席上添酒，后来她说那天她像个寡妇。","eff":{"bond":3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":"她给爹做了三年棉鞋"}}]},{"id":"sui_m14","act":"main","age":[55,56],"mode":"dialogue","title":"洗骨","opening":"母亲走那年，眼睛已经看不清了。她每天坐在灶边，把同一块布叠了又叠，叠一炷香的工夫。入冬后她不肯上炕，说炕上有人。你问是谁，她说：你爹。腊月里她开始认错人，把杏叫成穗禾，把穗禾叫成自己的娘。只有叫你的名字时是清的。小满八岁，在院里踢毽子，踢到灶房门口，被穗禾撵出去。","ask":"她想摸摸祖骨罐，你怎么应？","days":60,"npc":"mother","memory":"她摸那圈绳痕","choices":[{"title":"抬罐到枕边","desc":"你和穗禾把祖骨罐从柴房抬出来，放在她枕边。","hint":"罐底的土撒了一路。","tone":"family","outcome":"罐子沉，你们抬到门口歇了三回。母亲伸手摸那圈绳痕，摸了一遍又一遍，说：你爹的手。她那天夜里睡得很沉，第二天早上没醒。出殡时罐子又搬回柴房，罐底的土扫起来，撒在了她坟头。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":4},"flag":"","thread":""}},{"title":"摇头说罐不离土","desc":"你摇头，说祖骨罐不能离地，搬了要出事。","hint":"她把手缩回被子里。","tone":"rule","outcome":"母亲没再要，只说：也是。她把手缩回被子里，眼睛看着房梁。话出口，你听见的是你爹的声音。穗禾在门外听见了，进来坐了一夜，没跟你说话。母亲走后，你在她枕头下摸到一小块布，包着三粒谷种——是当年那半袋谷里的。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":""}},{"title":"坐在枕边说从前","desc":"你不搬罐，坐在炕沿上跟她说话，说渠、说谷、说穗禾。","hint":"她听着听着就睡着了。","tone":"stay","outcome":"你从渠口的夜说到半袋谷，说到一半忘了词，她替你说下去。她问穗禾来信没有，你说来了。她说：别骗我。天快亮时她睡着了，手还搭在你手背上。出殡那天你才想起来，她到底没再提罐子。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":""}}]},{"id":"sui_m15","act":"main","age":[60,60],"mode":"narration","title":"烟大","opening":"六十岁那年秋后，你带小满去空穗台。他十三岁，走路总踢石子。出门前你到柴房看了一眼祖骨罐，绳痕朝里。台上堆着旧穗，风一过，灰打着旋。火光照着台上的骨纹，一道一道，像田埂。你从怀里摸出一叠旧纸：几张谷债盟的旧契，一卷父亲的收条。火点着了，纸边卷起来，红印先黑。小满蹲在旁边问：爹，你哭啥？你说：烟大。","ask":"小满伸手要添纸，这一把怎么烧？","days":10,"npc":"","memory":"空穗台上的灰","choices":[{"title":"念收条给他听","desc":"你展开一张收条，念上面的年份和数，让他跟着念。","hint":"他念到第三张就打哈欠。","tone":"teach","outcome":"小满念了两张就不耐烦，跑去踢石子。你一个人把二十六张念完，念到今年开春那张，声音停了一下。夜里你咳了半宿，杏端水来，没问。第二天小满问你那些纸是谁的，你说：你爷爷的。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"","thread":"他没听完二十六张"}},{"title":"把收条抽回来","desc":"你把父亲的收条从火边抽回来，只烧那些债契。","hint":"小满问你留着做什么。","tone":"keep","outcome":"债契烧成灰，收条你一张张叠好塞回怀里。小满问：这个不烧？你说：这不是债。回到家你把收条放进竹筒，和那截麻绳搁在一处。那年冬天小满翻箱子找见它们，你没解释，他也没问。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"kept_receipts","thread":"收条和麻绳收在一处"}},{"title":"让他点火","desc":"你把火折子递给小满，让他把最后一张契纸点着。","hint":"他的手抖了一下。","tone":"carry","outcome":"小满点着了，火从纸角爬上去，他吓得松手，纸落在台上。你用脚把它拨回火里。他问：爹，烧这个干啥？你说：烧了就不欠了。他点点头，把火折子还给你，手心里全是汗。后来他再没见过那些纸。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"哀":3},"flag":"","thread":""}}]},{"id":"sui_m16","act":"main","age":[76,78],"mode":"narration","title":"像他","opening":"七十六岁以后，你的腿不行了，走到田头要歇两回。穗禾埋在祖骨罐边，已经七年。穗宁嫁到鱼尾泽，一年回来一趟。小满接了你手里的锹，不让你下渠。他说话短，像你，也像你爹。你坐在门槛上看他拍水口，杏耳朵背了，扫谷扫两下歇一歇。日头走得慢。地还是租的。你想起四岁那年，母亲把半袋谷分成两碗。小满直起腰问：西头那道埂还补不补？你说：补。话出口你愣住，这个字跟你爹当年一样。","ask":"小满说想去穗仓城，你怎么答？","days":400,"npc":"","memory":"门槛上的日头","choices":[{"title":"给他豁口镰刀","desc":"你把墙上的豁口镰刀取下来，塞进他的包袱。","hint":"他只带走了镰刀柄。","tone":"leave","outcome":"小满走那天，你送到渠口。他把镰刀背上，走了几步又回来，把刀刃卸下来，只留下木柄，说：这个沉，我拿柄就行。你站在渠口，看他走远。回家你把刃挂回墙上，柄没了，墙上空了一截。夜里你去柴房摸罐子，绳痕上落了一层灰。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"","thread":"墙上空了一截"}},{"title":"让他种完这季","desc":"你把镰刀压在桌上，说种完这季，我不拦你。","hint":"他种完了，也走了。","tone":"keep","outcome":"小满没说话，第二天照常下田。那季谷子他种得比往年都好，秋收后他把谷子装进半袋，扎紧口，放在梁下。走的时候他没带你，也没带那把镰刀。你站在门口，看他过了渠，没回头。夜里你把半袋谷挂回梁上，罐子在柴房里，绳痕朝里。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"","thread":"半袋谷又挂在梁下"}},{"title":"陪他去穗仓城","desc":"你说我跟你去，我还没见过仓城。","hint":"你走到半路就走不动了。","tone":"seek","outcome":"你们走到鱼尾泽，你的腿肿了，在渡口的草棚下歇了两天。小满说：爹，回吧。你说：再走一天。第三天他一个人上了船，你坐在草棚里看船走远。船工问你等谁，你说：不等谁。回家那截路，你走了三天。到家先去柴房看罐子，绳痕上落了灰，你用袖子擦了擦。","eff":{"bond":4,"health":-4,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":""}}]}],"side":[{"id":"sui_s01","act":"side","age":[6,6],"mode":"narration","title":"拾穗会的木棍","opening":"秋收后第三天，拾穗会在田头插下一根枣木棍，棍上刻着九道刀痕，一道是一年。柳婆把手在围裙上擦了两遍，才把棍递给你：替我攥着。你攥到手掌发红，木刺扎进指腹。棍这边是割剩的落穗，那边是田主家还没收完的谷。远处父亲蹲在田埂上磨那把豁口镰刀，锉刀声一下一下。田主家的儿子从晒场那头过来，靴底踩着谷茬，咯吱响。","ask":"他伸手来拔这根棍，你怎么办？","days":25,"npc":"","memory":"九道痕的木棍","choices":[{"title":"把棍按回土里","desc":"你两只手压住棍顶，把被拔出的半截重新按进泥里。","hint":"他踢了你一脚。","tone":"protect","outcome":"他抬脚踢在你肋上，你倒了，手还攥着棍。柳婆过来，没扶你，先把棍扶正，用脚把土踩实，说：棍是死的，界是活的。晚上她拿烧酒给你揉肋，手劲很重，一句话没说。那半个秋天，田主家的人从你家门口过，都不往院里看。你后来才知道，那天她替你家说了话。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":2,"爱":1},"flag":"","thread":"肋上那块青了半个月"}},{"title":"把穗子倒给她","desc":"你把兜在衣襟里的穗子全倒进柳婆的布袋，一粒没留。","hint":"晚饭时你的碗是空的。","tone":"warm","outcome":"柳婆掂了掂袋子，倒回一半给你。你说不要，她就把那一半分给旁边更小的孩子。回家母亲问捡的穗呢，你说掉了。姐姐拿筷子敲你的碗沿：傻子。夜里柳婆从窗缝塞进来两个烤穗子，皮焦了，瓤还硬。你啃到半夜，把穗子皮吐在手心里，没舍得扔。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"跟他去晒场","desc":"你放下木棍，跟着田主家的儿子去他家晒场捡谷。","hint":"柳婆没回头看你。","tone":"practical","outcome":"他家晒场边确实撒得多，你捡了满满一衣襟。廊下有人看着，没赶你。傍晚你从田头过，木棍还插在那儿，柳婆已经走了。之后半个月，你绕着她走；她照旧在田头分穗，没叫过你。那年的落穗你捡得比谁都多，姐姐夸了你一回。你把最饱的几穗藏在墙洞里，谁也没给。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3},"flag":"","thread":""}}]},{"id":"sui_s10","act":"side","age":[9,9],"mode":"narration","title":"雨里的种摊","opening":"雨下了九天，去鱼尾泽的路泡成了河。爹撑船，你蹲在船头压着那半袋谷，袋口用麻绳扎了三道。水上集市搭在船与船之间，木板一踩就晃，缝里冒水。鱼腥、湿草绳、烂菜叶的味混在一处。卖种的摊子排在最后一条巷，一个外乡人蹲在船板上，手边两只口袋，一袋黄亮，一袋发暗。他抓一把给你看，掌心底下有半把是绿的，带白毛。","ask":"他抓起一把要倒进你家袋里，你怎么办？","days":12,"npc":"","memory":"船巷里的霉种","choices":[{"title":"攥住他的手腕","desc":"你抓住他手腕，把那把霉种举起来，给整条船巷的人看。","hint":"他船里钻出个小孩。","tone":"brave","outcome":"人群围上来，有人掀了他的口袋，绿毛谷撒了一船板。他被推下水，爬起来时嘴角破了，蹲在船尾抱着那个小孩。散集时他的船还在，两只空袋泡在水里。你家没换成种，爹一路没说话，到家把那半袋谷重新吊回梁上。","eff":{"bond":0,"health":0,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"怒":2,"哀":2},"flag":"","thread":""}},{"title":"用自家谷换霉种","desc":"你把半袋谷倒给他，换下那袋霉种，扛到船尾倒进水里。","hint":"回家时梁上空了。","tone":"warm","outcome":"他愣了愣，接过袋子掂了掂，没说话。你一趟一趟把霉种捧到船尾，倒进浑水，绿毛浮了一层，被雨点打散。回家路上爹问种呢，你说换了。他把篙插进泥里，看了你很久，说：今年种什么。你没答。开春，你家是全村唯一没下种的。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"爱":2},"flag":"traded_seed_for_mold","thread":"你家那年没有下种"}},{"title":"拉娘往鱼摊走","desc":"你拽娘往旁边鱼摊走，说那袋种不好，别买。","hint":"同村的人还在挑。","tone":"dodge","outcome":"娘信你，跟着走了，在鱼摊买了两条小鲫。回村后你听说上村的周三买了那袋种，出苗时一垄一垄地秃。周三蹲在田头拔苗，拔一把扔一把。你从渠边走，他抬头看你，你低下头。那年你家的秧出得齐，你一直记得他拔苗的那双手。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":""}}]},{"id":"sui_s02","act":"side","age":[10,10],"mode":"montage","title":"雨帖没应验","opening":"开春，看天的韩老头在晒场墙上贴了雨帖。他写的是三日有雨，宜先浸种。你在田埂上替人念，念到第三行卡住了，只认得日、有雨，就说：明日有雨。第二天下种，全村把种撒进干土。那半袋谷倒出去的时候，母亲的手在袋口停了一下。结果三日无雨，十日无雨，种子在土里发了霉，扒出来一股酸味。韩老头被围在晒场中间，旧褡裢踩在脚底下。","ask":"韩老头被围在晒场中间，你做什么？","days":40,"npc":"","memory":"雨帖没应验那年","choices":[{"title":"站出去认错","desc":"你走到人前，说帖上写的是三日，是你念错了。","hint":"父亲没抬头。","tone":"honest","outcome":"人群静了一下，随后有人说：小孩懂什么。你爹把你拽到身后，手掐得很紧。韩老头看了你一眼，把踩扁的褡裢捡起来，拍了拍土，谁也没看就走了。那年的种没了，村里人照旧骂他。你爹回家的路上没说话，进门才说：往后认不全的字，别念。你记了一辈子。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"confessed_misread","thread":""}},{"title":"撕下雨帖","desc":"你趁人挤，把墙上那张雨帖揭下来塞进怀里。","hint":"韩老头还是走了。","tone":"hide","outcome":"纸上的糨糊没干，粘了你一手。人群找不到帖，就说他根本没收过帖，全是嘴说的。韩老头没辩解，天黑前背着褡裢出了村。你把那张纸塞进村后祖骨罐棚的砖缝里，罐口那圈绳痕磨得发亮。每年返潮你拿出来晾一晾，再塞回去。字一年淡一年，你从没再读完过。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"hid_rain_poster","thread":"雨帖藏在祖骨罐棚的砖缝里"}},{"title":"跟着喊赶他走","desc":"你挤在人堆里，跟着他们喊：赶他走，赶他走。","hint":"你的嗓子哑了三天。","tone":"repeat","outcome":"有人把他的墨盒摔在地上，墨溅了一片，像一摊黑泥。韩老头蹲下去捡碎片，手指被划出血。你喊到嗓子哑，回家喝了半碗凉水。第二天他走了，村里没人送。后来每年开春，晒场墙上没再贴过雨帖，大家看天色下种。你也学会了说：那年雨帖不准。说得跟别人一模一样。","eff":{"bond":0,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":""}}]},{"id":"sui_s03","act":"side","age":[12,12],"mode":"montage","title":"村里办丧事的三天","opening":"守祖骨罐的万爷死在夜里，村里办三天丧事。第一天报丧，第二天守灵，第三天出殡。你被派去添灯油，一夜添三回。堂屋停着门板，万爷躺在上面，脚头一盏灯。他常用的粗碗还摆在灶间，儿媳妇顺手拿去盛了待客的菜。他的狗钻在桌底下，谁踢也不走。你爹把那把豁口镰刀借给丧家削引魂幡的竹竿，还回来时刃上沾着青竹皮。","ask":"出殡前那晚，你打算做什么？","days":10,"npc":"","memory":"万爷的那副碗","choices":[{"title":"收起那只粗碗","desc":"你把万爷的粗碗从灶间收进柜子，不让人再盛菜。","hint":"他儿媳妇找了一下午。","tone":"keep","outcome":"出殡那晚，他儿媳妇打开柜找盆，看见了那只碗。她拿出来，用袖子擦了半天，没放回柜里，倒扣在灶台上。后来那只碗一直倒扣在那儿，裂了也不扔，谁也没再拿它盛过东西。她没问是谁收的。你也没说。多年后你路过那家，灶台上还扣着一只碗，蒙着灰。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}},{"title":"把狗领回家","desc":"散席后你把万爷的狗牵回自家院里，给它半碗粥。","hint":"它夜里叫了一整宿。","tone":"protect","outcome":"狗不吃，趴在门槛上，鼻子朝着万爷家的方向。你蹲在它旁边，蹲到腿麻。第三天它开始吃，吃完就睡在你鞋边。开春它跑回那间空屋，蹲在门口，怎么叫也不走。你每天给它送一次食，送了两年，直到它没再来。你一直没给它起名字。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"跟吹鼓手学调","desc":"出殡那天你跟在吹鼓手后头，把送葬的调子一句句记住。","hint":"你记了三十年。","tone":"learn","outcome":"吹鼓手是个瘦老头，见你跟着，捏着你的喉咙教你换气。你学不像，他也不急，说：记在耳朵里，比记在嘴上强。出殡回来，那支调子在你脑子里响了三天。往后村里每办丧事，你都去听。二十八年后你爹走，你想把那支调子吹给他听，端起唢呐，一个音也出不来。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":"那支送葬调子你一直吹不响"}}]},{"id":"sui_s04","act":"side","age":[15,15],"mode":"narration","title":"嫁到鱼尾泽","opening":"邻家菱儿要嫁到鱼尾泽，聘礼是一垄种田，田契上的名字要换。出嫁前一天，她把嫁妆摊在晒场上晾：一口红漆箱，两床被子，一面铜镜。她坐在箱子上绞脸，脸上扑着粉，嘴唇咬得发红。鱼尾泽来的船停在河口，船头挂一盏没点的灯。她看见你，招手：过来，帮我拎箱子。箱角沉，你一提，底下掉出几粒谷壳。","ask":"跳板搭好了，菱儿站在船头看你，你做什么？","days":15,"npc":"","memory":"菱儿的红箱子","choices":[{"title":"塞一把谷进箱","desc":"你从梁上那半袋谷里抓一把，塞进她箱角的布缝。","hint":"她婆家拆洗时掉了满床。","tone":"warm","outcome":"她没看见，船开了才觉得箱子底下沙沙响。开春她托人捎回话，说拆被子时掉了一床谷壳，婆婆骂了三天，说不吉利。她把谷壳扫起来，没扔，装在一个小布袋里。捎话的人说，她问你好。你想不起她问的是哪一句好。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"她带走了一把谷壳"}},{"title":"把船家的话说给她","desc":"你告诉她，船家说鱼尾泽的媳妇头三年不许回娘家。","hint":"她脸上的粉白了一层。","tone":"honest","outcome":"她听完笑了一下，说你早知道了，是媒婆说的。她又说：不许回就不回，鱼比人好养。船上的人催她坐稳，她把裙子拢了拢。船开出去一丈，她忽然回头喊：我娘要是问，就说我笑了。你点头。后来她娘来问，你说她笑了。她娘哭了一夜。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":""}},{"title":"接着唱完嫁歌","desc":"她唱了半句就哑了，你接着把下半句唱完。","hint":"满船的人都回头看你。","tone":"brave","outcome":"调子是你听她哼过许多回的，词不全，你把半句翻来覆去。船家敲着船帮跟着哼，船尾的橹声慢下来。菱儿低着头，肩膀抖了几下，再抬起来时脸上又是粉。到鱼尾泽的河口，她踩着跳板下船，没回头。你看见她红鞋底沾了水，一步一个湿印，走到岸上就没了。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}}]},{"id":"sui_s09","act":"side","age":[19,19],"mode":"dialogue","title":"她从城里回来","opening":"穗禾走了两年，秋分那天回来。她穿一件靛蓝褂子，袖口收得窄，脚上是胶底鞋，站在晒场边上不敢下脚，怕踩着摊开的谷。她带回一包桂花糖、一双给娘的胶鞋、一顶给爹的毡帽。爹把帽子翻过来看里子，放回桌上，说城里东西不结实。晚饭她吃得少，筷子在碗沿上磕出响。夜里她跟你挤一铺炕，身上有煤烟和皂角的味，翻来覆去到半夜。","ask":"她说能带你进仓城，你怎么答？","days":20,"npc":"sibling","memory":"她带回的胶底鞋","choices":[{"title":"划自己那垄给她","desc":"你翻出田契，在灯下把名下那半垄指给她，让她折成谷带走。","hint":"爹三个月没跟你说话。","tone":"warm","outcome":"她盯着契纸看了很久，指着边角那块米汤粘过的地方问是谁粘的。第二天她把契拿到河口给船家看，折了八斗谷，没跟你道谢。爹知道后把碗摔在门槛上，三个月没跟你说话。开春插秧，爹从东头插到西头，中间空出一条，谁也没提补上。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":3},"flag":"gave_sister_land","thread":"田契上少了半垄"}},{"title":"把田契锁回柜里","desc":"你把契纸折好锁进柜子，说祖骨埋在这垄，谁也不能动。","hint":"她第二天一早就走。","tone":"rule","outcome":"她起早收拾箱子，没吃早饭。娘追到河口，塞给她半袋谷，她没要，只把毡帽从箱里拿出来，放在门槛上。此后两年她没回来，也没有信。爹有时把帽子拿起来弹灰，弹完挂回墙上，不说给谁留的。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}},{"title":"半夜送她到河口","desc":"你什么也不说，替她拎箱子摸黑走到河口，塞给她半袋谷。","hint":"她在船上没回头。","tone":"escort","outcome":"到河口天没亮，船家蹲在船头啃饼。她把箱子递上去，忽然说：你要想来，仓城东门问筛谷的刘婆。船开出去，橹声一下一下。你抱着空谷袋往回走，走到晒场天亮了，谷上全是露水，你一垄一垄替爹翻了一遍。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui_s05","act":"side","age":[24,24],"mode":"narration","title":"村口的账房","opening":"秋分前，村口看场屋住进一个外乡账房，姓陈，背着麻绳和木匣。白天他量地，晚上点一盏豆油灯。你替他挑水，他给你一把炒黄豆。第七天他让你攥住绳头，从东垄走到西垄，麻绳勒进手心。走到第三垄，他翻你家田契，指腹在边角那块米汤粘过的地方蹭了蹭，问：谁粘的？你说：我娘。他嗯一声，把契纸照原样折好。有一晚下雨，你们并排坐在门槛上，他把伞往你这边偏了偏，谁也没说话。","ask":"他天亮就走，小鞋忘在窗台上，你怎么办？","days":20,"npc":"","memory":"窗台上的小鞋","choices":[{"title":"追到渡口还鞋","desc":"你抓起小鞋，沿河追了二里地，把鞋塞进他包袱。","hint":"他走得比来时快。","tone":"escort","outcome":"他没回头，只把包袱往肩上提了提。你看见他抬手在脸上抹了一下，像赶蚊子。船离岸时，他把那只鞋摆在船头的木板上，摆得很正。后来你才想起，他从没说过家里有孩子。你也没问。那年秋后，你晚饭后总去村口站一会儿，站到看场屋塌了半边。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把鞋收进箱底","desc":"你用布把鞋包好，压在自己箱底，谁也没告诉。","hint":"你自己的孩子穿不进去。","tone":"keep","outcome":"第二年你娶亲，箱子抬进新房，鞋还在底下。你媳妇翻出来问是谁的，你说路上捡的。她看了你一眼，没再问。后来孩子出生，脚长得快，你几次想把鞋拿出来比一比，手伸到箱底又停住。鞋压了二十多年，皮子硬得像块瓦，鞋尖上还留着他缝的线。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"kept_accountant_shoe","thread":"箱底压着一只小鞋"}},{"title":"交给仓兵挂树上","desc":"你把鞋交给仓兵，说是看场屋里捡的，让他挂在村口。","hint":"没人来认。","tone":"rule","outcome":"仓兵在本子上记了一笔，用麻绳把鞋挂在村口槐树上，说有人认就领走。鞋挂了两个月，先落灰，后发黑，最后只剩一根鞋带。过路的人问是谁的，你说不知道。第二年修枝，鞋带也剪掉了。看场屋后来住过两茬人，你都没去挑过水。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"reported_shoe","thread":""}}]},{"id":"sui_s11","act":"side","age":[28,28],"mode":"narration","title":"住半月的房客","opening":"谷雨前，村里来了个外乡女人，三十来岁，说做半个月针线活，租你家西屋。她给的谷铢压手，说话轻，吃饭前先洗手，水泼在院里墙角。白天她不出门，晚上出去，回来时鞋底带泥。第五天夜里你起来添料，看见她蹲在村东老周家的田埂上，从怀里摸出一只白瓷瓶，瓶口贴着地。第二天那一片谷叶就卷了，你摸土，土是凉的。你手里还攥着爹那把豁口镰刀，刃上沾了湿泥，缺口里嵌着一线草屑。","ask":"她把瓷瓶收进袖子，你怎么办？","days":20,"npc":"","memory":"她夜里的白瓷瓶","choices":[{"title":"把自家那垄指给她","desc":"第二天你告诉她，村东地薄，要取就取你家南头那半垄。","hint":"她看了你很久。","tone":"carry","outcome":"她没答应，也没拒绝。当夜她去了南头，蹲在你家田里，白瓷瓶贴地，蹲了半个时辰。走时她把瓶塞好，说：你家的地力本来就不厚。半月后她走了，西屋炕席扫得干净，枕下压着几枚谷铢。第二年南头那半垄出苗稀，爹蹲在地头捏土，捏碎了吹掉，说这地老了。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"let_tenant_take_own_field","thread":"南头那半垄地力薄了"}},{"title":"去晒场敲铜锣","desc":"你摸黑跑到晒场，敲响那面铜锣，把半村人喊到田头。","hint":"她的鞋跑丢了一只。","tone":"report","outcome":"人举着火把围住西屋，从她箱底翻出三只瓷瓶，瓶里是浑水，晃一晃有白丝。天亮仓兵来把人带走，她赤着一只脚走在泥路上，回头看了你一眼。村里把西屋的炕拆了，说晦气。你娘把那几枚谷铢扔进灶膛，火苗绿了一下。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"恶":2},"flag":"reported_field_drainer","thread":""}},{"title":"照旧给她端水","desc":"你什么也不说，第二天照旧给她端洗脸水，看她收拾针线。","hint":"她多住了三天。","tone":"ignore","outcome":"她多住三天，每晚照旧出去，你每晚照旧给她留门。走那天她把一件补好的褂子叠在炕上，袖口针脚很密。半月后村东三家的谷子黄了一片，老周蹲在地头骂天。你站在渠边摸自己那件褂子的袖口，针脚扎得手心发痒。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"恶":2},"flag":"","thread":""}}]},{"id":"sui_s06","act":"side","age":[34,34],"mode":"narration","title":"一碗热汤","opening":"腊月十六，雪压塌了村东的草垛。你从鱼尾泽回来，半路天黑了，草鞋冻成两块。柳婆家的灯还亮着。她开门看你一眼，侧身说：灶上有汤。锅里是野菜糊糊，飘着几星油花。她给你盛一碗，自己坐回灶前补麻袋，袋底还剩半袋谷。阿绵趴在桌边问你小时候冷不冷。你说起四岁那年娘分半袋谷，七升留种，两升换盐；说到娘攥了攥最后一把谷，你停住了。阿绵问后来呢，你说忘了。","ask":"碗见了底，柳婆又去刮锅，你做什么？","days":10,"npc":"","memory":"灶上的那碗汤","choices":[{"title":"把碗底拨给阿绵","desc":"你用筷子把碗底那几粒米拨进阿绵碗里，说太烫。","hint":"柳婆看见了，没说话。","tone":"warm","outcome":"阿绵先看她奶奶，柳婆点了一下头，她才低头吃。柳婆起身去添柴，背对着你说：她爹娘在鱼尾泽帮工，半年没回来。你没接话。走时你把随身的半袋谷倒在灶边缸里，只留一把路上嚼。雪停了你才发觉，柳婆塞在你怀里的是双旧棉袜，袜底补过三层。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"那双补了三层的棉袜"}},{"title":"说汤糊了去劈柴","desc":"你放下碗说汤有糊味，起身去院里把湿柴劈了。","hint":"她重新尝了一口。","tone":"repair","outcome":"柳婆尝了尝，说没糊。你还是把院里那堆湿柴劈了，码到屋檐下。劈到半夜，手指头冻得握不住斧子。柳婆给你换了盏亮些的灯，阿绵趴在桌边睡着了，嘴角挂着一点糊糊。第二天你走，她把汤又热了一遍，非看着你喝完。那碗比昨晚稠，碗底沉着几粒米。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"喝完就上路","desc":"你把碗一推，说家里等着，披上袄走进雪里。","hint":"身后的门没关。","tone":"leave","outcome":"柳婆追到门口，往你怀里塞了半块糠饼。你没回头，怕一回头就走不成。走到渠边，你听见身后门闩响了一下，很轻。回到家，母亲问路上吃了吗，你说吃了。那晚的饭你吃了两碗。第二年开春，柳婆的腿就下不了炕了。你去看她，她说不记得你来过。","eff":{"bond":0,"health":1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"sui_s12","act":"side","age":[46,46],"mode":"narration","title":"替他守一夜","opening":"阿庚欠了青苗债，仓兵说天亮来抬东西。他连夜去穗仓城求人，临走把钥匙塞给你，说：替我看一夜，别让他们碰我娘的罐。堂屋门槛上点一盏灯，灯芯剪得短，火苗只有豆大。祖骨罐在供桌底下，罐口一圈绳痕，深得能卡住指甲。后半夜起雨，雨点打在瓦上，像有人在上头撒豆子。你听见巷口有铁器碰铁器的声音。","ask":"铁器声到了门口，你怎么办？","days":10,"npc":"","memory":"门槛上的一盏灯","choices":[{"title":"横门闩挡在门口","desc":"你横上门闩，搬条凳坐在门后，手里攥着爹那把豁口镰刀。","hint":"门上被写了你家的姓。","tone":"brave","outcome":"仓兵撞了两下门，门板裂开一道缝，缝里伸进一根铁钩。你用镰刀背敲在那只手上，外面骂了一声。他们没再撞，只在门上用炭写了个字。天亮阿庚回来，看见那字，蹲下去用手指抠，抠不掉。那年秋征，你家多派了两斗。","eff":{"bond":3,"health":-1,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"爱":2},"flag":"","thread":"门板上留着一个炭字"}},{"title":"抽开门闩让开","desc":"你把门闩抽了，退到墙边，说欠债还物，按规矩来。","hint":"阿庚回来没进你家门。","tone":"rule","outcome":"他们进来四个人，两个抬罐，两个翻箱。罐出门时在门槛上磕掉一块陶，你伸手想扶，被挡开。阿庚回来在空了的供桌前坐了一夜，第二天见你，绕到渠那边走。后来他家门槛上再没点过灯。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"let_guards_take_urn","thread":""}},{"title":"抱罐藏进祖骨棚","desc":"你抱起罐冒雨挪进村后自家祖骨棚，塞在最里头那格。","hint":"棚里多一口，账上少一口。","tone":"sneak","outcome":"天亮仓兵来，抬走一口空箱和两床被。阿庚回来，你把钥匙还他，说罐在村后。他去抱回来时，罐底蹭了一身泥，绳痕里嵌着新土。这事后来还是被查出来，罚你家补交两斗谷。你爹的牌位前，你多烧了一回纸。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":2},"flag":"hid_neighbor_urn","thread":""}}]},{"id":"sui_s07","act":"side","age":[52,52],"mode":"narration","title":"替柳婆守灵","opening":"柳婆是立冬夜里走的，九十六岁。灵停在堂屋，两条长凳架着门板，脚头一盏灯。守夜轮到后半夜，人都散了，只剩你。你拿爹那把豁口镰刀削了几根撑灵帐的竹竿，坐在门槛上听风。那根九道痕的木棍靠在棺边，是她自己要放的。灵桌底下是她的祖骨罐，罐口那圈绳痕深得能卡住指甲。阿绵从鱼尾泽赶回来，跪在灵前烧纸，纸灰落在鞋面上，烧到一半问你：奶奶说这棍不能烧，你知道为啥？","ask":"阿绵看着你，等一个说法，你怎么答？","days":10,"npc":"","memory":"灵前的九道痕","choices":[{"title":"把棍藏进袖子","desc":"你把木棍抽出棺边，塞进袖子，说烧不烧都一样。","hint":"阿绵看见了你袖口的木头。","tone":"sneak","outcome":"阿绵没拦，只把纸往火里推了推。天亮出殡，你袖子里硌着一根棍，走一路硌一路。下葬后回家，你把棍立在门后。你媳妇问哪来的，你说是柳婆的。她说留着不吉利。你没扔。那年冬天劈柴，你好几回伸手想拿它引火，摸到那九道痕，又缩回来。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":6},"flag":"","thread":"门后立着一根不能烧的棍"}},{"title":"当众把棍折断","desc":"你举起木棍，在膝盖上一折两段，一段放进棺里。","hint":"满屋的人都静了。","tone":"brave","outcome":"木头断的时候响了一声，像干骨头。阿绵看着你，眼睛红了，没哭。你把另一段递给她，说：一半跟着你奶奶，一半你拿着。她接过去，攥得指节发白。出殡后她把半截棍塞进包袱，回了鱼尾泽。你留下的那半截，后来钉在院里当了豆角架的桩，风吹日晒，痕还在。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把棍交还阿绵","desc":"你把木棍擦干净，双手递给阿绵，说这是你奶奶的界。","hint":"她不知道拿它做什么。","tone":"teach","outcome":"阿绵接过去翻来覆去看了半天，问九道痕是什么。你一道一道讲，讲到你六岁那年攥着它，田主家的儿子来拔，你停了一下，说：记不清了。她把棍靠在灵桌边，出殡时忘了拿。你替她收起来，想等她想起来。她一直没想起来。棍后来一直立在你家门后。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":1},"flag":"","thread":""}}]},{"id":"sui_s13","act":"side","age":[58,58],"mode":"narration","title":"借粮的人","opening":"大旱第二年，谷价一天三涨，村口每天有外村人过。晌午来了一个男人，四十上下，裤脚卷到膝盖，脚上只剩一只草鞋，站在你家篱笆外不进来。他说是上村的，姓吴，家里三个孩子，老幺病着，只借半袋，秋后还一袋半。你炕席底下压着田契，边角那块米汤粘过的地方硌手；灶间梁上吊着那半袋留种的谷，袋口扎了三道麻绳，是你娘在时扎的，绳头还留着她的牙印。","ask":"他站在篱笆外不进来，你怎么说？","days":30,"npc":"","memory":"门外的空口袋","choices":[{"title":"解绳倒半袋给他","desc":"你把梁上的袋解下来，倒出一半，用簸箕撮进他的空袋。","hint":"梁上只剩一把种。","tone":"warm","outcome":"他接袋时手在抖，说了三遍秋后还。你送他到渠口，他走几步回一次头，鞠了三次躬。那年秋后他没来，第二年也没来。开春你家种不够，向拾穗会借了一升，秋后还两升。你娘扎的那个结，你没再打上。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"借出去的半袋没有还"}},{"title":"按住袋口说不借","desc":"你按住袋口，说这是留种的，借出去一家人都得饿死。","hint":"他在篱笆外站了很久。","tone":"refuse","outcome":"他没再说话，把空口袋叠好夹在腋下，走了。走出十几步，他回头看了一眼你家的烟囱。秋后有人从上村来，说他家老幺没熬过八月。你把那半袋谷吊回梁上，绳子勒进手掌。第二年下种，那袋谷一粒没霉，出得比谁家都齐。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":1},"flag":"refused_famine_grain","thread":""}},{"title":"领他去鱼尾泽找活","desc":"你锁上门，领他走两天路到鱼尾泽，找管短工的阿绵。","hint":"你家的地荒了两天。","tone":"help","outcome":"路上他把仅剩的草鞋让给你穿一段，你没要。阿绵看了他半天，让他去码头扛谷包，先支半袋碎米。他扛起包时腰直不起来，回头朝你点头。你走回村已是第三夜，自家田里的草长得比苗高。他后来每年托人捎一句话，话里从不提借粮。","eff":{"bond":1,"health":-2,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui_s14","act":"side","age":[66,66],"mode":"narration","title":"他问那年的事","opening":"穗禾的孙子从穗仓城来，十九岁，穿一件洗得发白的褂子，说话带城里尾音。他在你家住两晚，帮你挑水、劈柴，劈完把斧子擦干净挂回墙上。第三天他要走，蹲在门槛上系鞋，忽然问：我奶奶说，那年她在河口等到天亮，你没来。他抬起头：你为啥没走？供桌底下那只罐罐口有一圈绳痕，深得能卡住指甲。院里晒着新谷，风一过，谷壳往墙根滚。梁上还挂着你爹那把豁口镰刀，缺口磨圆了。","ask":"他系好鞋等着你答，你说什么？","days":15,"npc":"","memory":"河口那年的船","choices":[{"title":"领他看祖骨那垄","desc":"你领他到村后看祖骨埋在哪一垄，回来把梁上那半袋谷给他。","hint":"梁上那根绳空了。","tone":"teach","outcome":"他蹲下去抓了一把土，土从指缝漏回原处。你说这底下埋着太爷爷，东头棚里是太奶奶的罐。他把那把土装进衣兜，拍了拍。走时他没说什么时候再来。第二年清明，那垄上多了一小堆新土，颜色发黑，是从城里带来的。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"把话说明白","desc":"你告诉他，那年你爹把田契塞进你手里，说这地不能断在你这辈。","hint":"他问那我奶奶算什么。","tone":"honest","outcome":"他系鞋带的手停了一下，又系了一遍，问：那我奶奶算什么。你答不上来。他站起来把劈好的柴码齐，说够烧一冬。走到篱笆外他回头，说城里也有地，是水泥的。你回屋把田契从炕席底下摸出来，边角那块米汤粘过的地方又翘了。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":1},"flag":"told_grandson_truth","thread":"他问的那句话你没答上"}},{"title":"送他到河口","desc":"你什么也不答，替他拎着包袱，一直送到河口那棵歪柳下。","hint":"船开了你才回家。","tone":"escort","outcome":"一路上你们没说话。到河口他把包袱接过去，说奶奶讲她那年也是从这儿走的。船离岸，他站在船尾手扶船帮，姿势跟他奶奶当年一样。你回家把院里那堆谷壳扫拢，扫成一堆，没舍得烧。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}}]},{"id":"sui_s08","act":"side","age":[71,71],"mode":"narration","title":"来问旧事的人","opening":"霜降后，村里来了个年轻人，十九岁，穗仓城口音，说是替秋祭收旧事。他坐在你家门槛上，膝上摊着本子，问一句，记一句。你从拾穗会的木棍讲起，讲到十岁那年雨帖没应验，讲到韩老头被围在晒场，忽然停住了。他等着，笔尖悬在纸上。灶上的水开了，咕嘟咕嘟，你起身去添柴，背对着他说：记不清了。梁上还挂着你爹那把豁口镰刀，刃上的缺口磨圆了。","ask":"他问韩老头后来去了哪，你怎么说？","days":20,"npc":"","memory":"他记下的旧事","choices":[{"title":"说出那个字","desc":"你告诉他，帖上写的是三日，是你念错，不怪韩老头。","hint":"他抬头看了你很久。","tone":"honest","outcome":"他写得很慢，写完念给你听。你听见自己的名字和韩老头的名字写在同一行，像两块地终于挨上了界。他说回去要交给主事，能不能改，不知道。你送他到村口，他走远了你还站着。回来你把田契从炕席底下摸出来，边角那块米汤粘过的地方又翘了，你用手按了按。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6},"flag":"told_rain_truth","thread":""}},{"title":"让他照老话写","desc":"你说记不清了，让他照村里传的那套写。","hint":"他写下了赶走韩老头那句。","tone":"dodge","outcome":"他写完念了一遍，问你还有没有要补的。你说没有了。他合上本子，朝你鞠了一躬，说打扰了。你看着他走，想起韩老头当年也是这么走的，背一只旧褡裢，鞋面上全是灰。晚上你把梁上的半袋谷取下来，抓一把又放回去。谷子从指缝漏回袋里，沙沙响。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}},{"title":"领他去看墙","desc":"你带他到晒场，指给他看当年贴雨帖的那块墙皮。","hint":"墙皮已经换了三回。","tone":"witness","outcome":"晒场翻修过，墙是新泥，什么也没有。你站了半天，说：就是这儿。他伸手摸了摸，摸下一层白灰，问还记不记得帖上的字。你说记得几个。他等着，你却没往下说。回去的路上你走得慢，他要扶，你说不用。第二天他走了，本子上那页只写了一行：村人逐雨帖师。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":5},"flag":"","thread":"那页只写了一行"}}]}]},"无昼京":{"no":2,"name":"无昼京","subtitle":"永夜里，一盏灯能照亮几个人","through":"母亲替别人修了一辈子灯，自己家总在省灯芯。后来你才懂，她把光给出去，是因为相信光会回来。","cast":[{"id":"father","name":"亥叔","role":"夜脚夫","tag":"父"},{"id":"mother","name":"灯娘","role":"修灯匠","tag":"母"},{"id":"sibling","name":"小漏","role":"抄漏吏","tag":"妹"}],"main":[{"id":"wu_m01","act":"main","age":[0,0],"mode":"montage","title":"两截灯芯","opening":"你生在修灯铺的里间。接生婆的剪子先在灯上烤过，母亲躺着，手还搭在桌沿，桌上摊着七八盏别人家的坏灯。家里只剩一截灯芯，两指长，她让接生婆剪成两段，一段今晚点，一段包进油纸压在枕下。父亲还没回来，门外是永远的黑。灯点起来只有黄豆大，照得见母亲的下巴，照不见墙。她把你往灯边挪了挪，说：看清了，这是你的手。","ask":"两段灯芯摆在枕边，你伸手抓哪一段？","days":30,"npc":"mother","memory":"两指长的灯芯","choices":[{"title":"攥住长的那段","desc":"你攥住长的一段，油纸被你捏得发响。","hint":"明晚要摸黑。","tone":"greed","outcome":"母亲由着你攥。那晚灯亮到后半夜，她借着光把七盏坏灯一一看过，记下哪盏该换芯。天亮时长的烧完了，短的只剩半寸。第三晚家里没点灯，父亲在门槛上摸黑吃了一碗冷粥。后来母亲跟人说起你，总说：这孩子，抓的是长的。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"喜":2,"哀":1},"flag":"","thread":""}},{"title":"抓短的那段","desc":"你把短的一段攥进手心，长的留给明天。","hint":"母亲把长的收进柜里。","tone":"steady","outcome":"母亲笑了一下，把长的那段用油纸包好，收进柜子最里头。那晚的灯只点了半炷香，她就着光给你缝了一双小鞋，鞋底纳得密。后来你穿到露脚趾，她又补了一层。家里省下的那半截灯芯，她一直没动，逢人就说：留着，等日子好一点。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":1},"flag":"","thread":"柜里留着半截灯芯"}},{"title":"抓住她手指","desc":"你不抓灯芯，抓住母亲搭在枕边的手指。","hint":"她让整截灯芯亮了一夜。","tone":"family","outcome":"母亲没抽手。她把那截灯芯整个点上，说：头一晚，亮一点。灯芯烧到天亮，剩一撮黑灰。第二天她去邻家借了半勺油，回来时在门槛上歇了一会儿才进屋。多年后她跟人说，你满月那晚眼睛亮得像灯，她一辈子就见过那一回。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"whole_night_light","thread":""}}]},{"id":"wu_m02","act":"main","age":[5,5],"mode":"dialogue","title":"日门开的那天","opening":"日门开在十二钟楼底下，一年只开一回，一回只有一刻。那天全城的人都往广场去，人人手里提一盏灯，到门边就收进布套里。母亲把你举到肩上，叫你闭眼。你没闭。门缝先是白的，后来变成一条金线，光涌出来落在脸上，是热的，像灶膛口。你哭了。母亲在底下仰着脸问：怎么了？话没说完，旁边一个老太太被人挤倒，灯罩碎在地上，碎瓷滚到你脚边。","ask":"老太太倒在脚边，母亲抱着你，怎么办？","days":10,"npc":"mother","memory":"日门缝里的光","choices":[{"title":"求母亲扶她","desc":"你拽母亲的袖子，叫她放下你，去扶那个老太太。","hint":"你们退到人群最外圈。","tone":"warm","outcome":"母亲把你放到墙根，叫你抓住她的衣角，自己去扶。老太太的膝盖磕出了血，灯罩碎在脚边。母亲撕了衣角给她扎。等再抬头，日门已经合上，人群正往外散。回家的路上母亲没说话，进门才说：今天你没看清。你说看清了，她脸上有光。母亲低头去烧水，火点着了又灭。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"你没看完那年的日门"}},{"title":"抱紧她往前挤","desc":"你搂住母亲的脖子，叫她再往前一点，别管别人。","hint":"背后有人骂了一句。","tone":"brave","outcome":"母亲把你往上颠了颠，从两个肩膀中间侧过去。有人骂，她没回头，只把布套往你头上按了按。光正好落在你脸上，你伸手去抓，抓了一把热。回家你跟小漏说光能抓，小漏笑得眼睛弯，说你吹牛。母亲在灶边听着，说：能。她说完把灯芯捻小了一截。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"喜":3,"爱":1},"flag":"","thread":""}},{"title":"蹲下看影子","desc":"你从她肩上滑下来，蹲在光的边上，看自己的影子。","hint":"你记住的不是光。","tone":"learn","outcome":"光把你的影子拉得很长，一直铺到钟楼台阶上，头在台阶上，脚在你脚边。你伸手，影子也伸手。母亲把你拉起来时，日门已经合了，人群往外走，鞋底踩得石板响。她说：看什么呢。你说：它在前面。母亲没听懂，牵着你的手往家走，一路没再问。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4},"flag":"saw_shadow_first","thread":"影子先你一步"}}]},{"id":"wu_m03","act":"main","age":[9,9],"mode":"dialogue","title":"影子先走","opening":"九岁那年秋天，你替母亲往暗渠边送一盏修好的灯。灯是给裁缝家的，芯是新换的整根。你提着它，想起自家灶台上那盏，芯是剪剩的，短得够不着油。母亲在后头说：灯送出去，光会回来。巷子窄，墙上的灯罩都熏黑了。走到拐角，你看见自己的影子先一步拐进巷子——它转过去，你还没转。你站住，影子也站住，只露出半个肩。你回头喊母亲。她赶来，在围裙上擦擦手，蹲下看你的影子，说：漏了光。","ask":"母亲说漏了光，能补，要你每晚举灯。","days":30,"npc":"mother","memory":"先走半步的影子","choices":[{"title":"每晚举灯站墙根","desc":"你按母亲说的，每晚举灯站半个时辰，把影子照回脚下。","hint":"你的胳膊比同龄人沉。","tone":"repair","outcome":"举了三年。头一年影子回来，第二年又往前跑。母亲每晚在旁边剥灯芯草，剥一段，看你一眼。你的右胳膊比左边粗，扛东西时稳，只是个子没怎么长，站在小漏旁边矮了半个头。她总拿这个笑你，笑完给你留一块灯油糕。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"爱":3,"哀":1},"flag":"","thread":""}},{"title":"自己改个灯罩","desc":"你拿铁皮敲了个罩子，把光全兜在脚边。","hint":"母亲的一件旧衣烧了个洞。","tone":"niche","outcome":"铁皮是从废灯上剪的，边沿磨手。你把罩子卡在灯口，光聚成一小团，只照脚下，影子果然跟上了。母亲看见了，没夸，只说：这样费油。你没听。后来那盏灯的罩口烧红，把搭在椅背上的旧衣烫了个洞，是母亲出嫁时穿的。她把洞补成了一朵花，补得歪。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5},"flag":"","thread":"你把母亲的旧衣烫了个洞"}},{"title":"随影子去","desc":"你把灯搁下，说随它去，它爱走哪走哪。","hint":"母亲把旧灯收进了柜底。","tone":"defy","outcome":"母亲没再提补的事。第二天她把那盏旧灯擦干净，收进柜底，压在一叠灯罩下面。你从此走路总比旁人快半步，影子也总在前头。巷子里的人说你这人急，像赶着去投胎。母亲听见了，不接话。你十九岁那年才知道，漏光的人，影子在影市上能卖个好价钱。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4},"flag":"kept_leaky_shadow","thread":"你的影子总在前头"}}]},{"id":"wu_m04","act":"main","age":[14,14],"mode":"dialogue","title":"替更牌","opening":"十四岁那年入冬，父亲的腿开始肿。夜里他回来，先在门槛上坐一会儿，靴子脱在门外，袜口勒出一道深沟，按下去一个坑，半天不回。母亲蹲下去看，拿手量了量，没说话，起身去灶上热盐水。父亲从怀里摸出一块木牌，牌上刻着他的更号和一道旧刀痕，搁在桌上，往你这边推了推。他说：替我去两晚。母亲的手停在灯罩上。","ask":"木牌推到你面前，两个晚上，接不接？","days":30,"npc":"father","memory":"刻着更号的木牌","choices":[{"title":"接下木牌","desc":"你把木牌揣进怀里，当夜就去货栈上工。","hint":"你的腿也会记住那重量。","tone":"carry","outcome":"第一夜你扛了十七趟，肩膀磨破，木牌在胸口硌出一道印。第二夜下雨，栈道的灯坏了两盏，你摔了一跤，货主扣了半刻光时。回家父亲看你的走路，看了很久，说：像我了。他说这话时在笑，你没敢看他的腿。那块木牌你一直揣着，揣到边角磨圆。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"爱":3,"惧":1},"flag":"","thread":"木牌边角被你磨圆"}},{"title":"把牌子交回工头","desc":"你去货栈找工头，说父亲走不动了，求换个白班。","hint":"父亲那晚没吃饭。","tone":"rule","outcome":"工头翻了翻册子，说白班没缺，倒有个扫灯楼的活，光时少一半。你替父亲应了，回家一说，父亲把木牌放在桌上，用指头把它转了半圈，说：我还没死。那晚他没在门槛坐，直接进了里间。第二天一早他照样去上夜工，走得很慢，木牌在腰间一下一下地撞。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_father_legs","thread":"父亲说：我还没死"}},{"title":"把木牌藏进砖缝","desc":"你趁父亲睡下，把木牌塞进灶膛后的砖缝。","hint":"他找了一夜。","tone":"sneak","outcome":"父亲把铺盖翻了两遍，把灯举到床底下照，最后什么也没说，半夜照样出门。你跟到巷口，看见他走三步歇一歇。母亲站在门口，手里捏着半截灯芯，轻声说：他这个人，你不让他去，他更难受。第二天你把木牌放回桌上，谁也没提这件事。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_m05","act":"main","age":[19,19],"mode":"dialogue","title":"影市","opening":"十九岁那年，小漏想调去日门当值。她说话快，一句赶一句，说去了能多领半刻光时。母亲在灯下穿线，没抬头，说：那边风大。小漏笑起来眼睛弯：我不怕风。第二天你瞒着家里去了影市。影市开在漏底渠的旧闸口下，灯都蒙着布，只留一条缝。管市的是个瞎了一只眼的女人，面前一排小秤，秤盘里不是油，是各人的时辰。墙角贴着一张熏黄的旧账，最下一行是父亲的名字，后头跟着个陌生的名字。","ask":"黑牌推到手边，按不按手印？","days":10,"npc":"sibling","memory":"蒙着布的影市","choices":[{"title":"按下手印","desc":"你把拇指按在湿泥上，换一小袋光时砂。","hint":"此后半年，你看东西慢半拍。","tone":"trade","outcome":"那一时辰是从你往后十年里扣的，扣得悄没声。回家路上你觉得灯比平时暗，揉了揉眼，还是暗。小漏拿那袋砂去换了调令，走的那天在门口回头，笑起来眼睛弯。你站在门里，觉得她的脸隔着一层布。母亲追出去，往她包袱里塞了半截灯芯，她没要，说日门那边有。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"哀":3},"flag":"sold_first_hour","thread":"你看东西慢了半年"}},{"title":"连影子一起卖","desc":"你在黑牌背面按下第二个手印，把影子也押出去。","hint":"灯下从此少一个人影。","tone":"profit","outcome":"瞎眼女人掀开布，灯照过来，你的影子在墙上挣了一下，像条被拎起来的鱼。她沿墙根一划，影子就下来了，叠好收进匣子。你拿到双份光时砂，给小漏置了调令，给母亲买了一整根新灯芯。那晚她点了灯，看你半天，说：你的影子呢。你说灯太暗。她把灯挪远了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"爱":3,"惧":3},"flag":"sold_shadow","thread":"你在灯下没有影子"}},{"title":"把黑牌推回去","desc":"你说回去再想想，把刻着名字的黑牌推回去。","hint":"小漏再没跟你提过调令。","tone":"refuse","outcome":"瞎眼女人把黑牌收进袖里，说：想好了再来，价钱按天变。你爬出闸口，外面的天黑得和里头一样。小漏在灯下抄漏，抬头问你去哪了，你说走走。她哦了一声，低头继续抄，笔尖在纸上顿了一下，留下一个墨点。那墨点后来越描越大，最后成了一个补不上的洞。","eff":{"bond":-2,"health":1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5},"flag":"","thread":""}}]},{"id":"wu_m06","act":"main","age":[24,24],"mode":"dialogue","title":"门槛上的夜","opening":"二十四岁那年，父亲走完了最后一趟夜路。他回来时天没亮，在门槛上坐下，靴子没脱，背靠着门框。母亲去热盐水，他摆摆手。你在他旁边坐下，门槛只有一条，两个人挨着。他从怀里摸出一张折了四折的纸，纸边发毛，上头是司昼院的朱印，底下两个名字：一个是他的，一个你不认识。他说：那年你出生，家里没光时了。我借了他的名。","ask":"他把纸递过来，说烧了吧。你接不接？","days":10,"npc":"father","memory":"两个名字的旧纸","choices":[{"title":"凑到灯上烧了","desc":"你把纸凑到灯芯上，看它卷起来，烧成灰。","hint":"那个名字从此没人再提。","tone":"secret","outcome":"火苗舔到他的指头，他没缩。纸烧完，他用鞋底把灰蹭进门槛的缝里，说：干净了。那晚他睡得很沉，第二晚也睡，第三晚没醒。母亲给他擦身时，在他贴身的口袋里摸出一小截新灯芯，油纸包着，没舍得用。你把它放回他口袋里，跟他一起下了葬。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"burned_father_ledger","thread":"那截新灯芯跟他下了葬"}},{"title":"把纸送去司昼院","desc":"你揣着纸去司昼院，把那笔旧账报了。","hint":"他走的时候，账是平的。","tone":"report","outcome":"司昼院的人查了三天，判补缴半刻光时，从他灯牌里扣。父亲听完，说：该。他把灯牌解下来放在桌上，牌绳磨得发白。那半刻还没扣完，人就走了。出殡那天，司昼院的一个小吏在门口站了一会儿，没进来，放下了一小罐油。你没要，让他提回去了。","eff":{"bond":-5,"health":0,"reputation":3,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"惧":2},"flag":"reported_father_ledger","thread":"父亲最后说了一个字：该"}},{"title":"把纸塞回他手里","desc":"你折好纸，塞进他手心，说这事你自己拿。","hint":"他到死都攥着那张纸。","tone":"keep","outcome":"父亲看了你很久，把纸攥在手里，攥出了汗印。那晚他跟你说了很多话，说他年轻时也想过跑，说漏底渠的水冬天是温的，说他第一次抱你，手心里全是灯油味。说到一半停住，说：困了。第二天早上他的手还攥着，掰开时纸粘在掌心，得用温水泡。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":4},"flag":"","thread":""}}]},{"id":"wu_m07","act":"main","age":[30,30],"mode":"dialogue","title":"认光","opening":"三十岁那年，母亲的眼睛坏了。先是穿不上线，后来把七号灯芯当成三号，修好一盏灯，点起来满屋子是烟。她把灯罩凑到鼻尖闻了闻，说：油不对。客人走后，她坐在凳子上，手在桌上摸，摸到你的手，捏了捏。第二天她把你叫到灯前，说：从今天起，我教你认光。她闭上眼，让你把灯一盏一盏点起来，说：哪盏先热，哪盏就是好芯。","ask":"铺子往后怎么办，母亲闭着眼等你答。","days":180,"npc":"mother","memory":"母亲教我认光","choices":[{"title":"闭上眼跟她学","desc":"你学她闭上眼，一盏一盏摸灯罩、闻油、听芯。","hint":"你的手会先于眼睛变老。","tone":"learn","outcome":"她教你听灯芯烧到几寸会响，教你看灯罩上的雾往哪边偏。半年后你能闭着眼修好一盏灯。来修灯的人越来越多，有人放下灯就走，灯座里压着一小截灯芯。母亲坐在旁边剥灯芯草，说：你比我强。她说这话时脸朝着墙。后来她的手越来越闲，一上午剥不了一把。","eff":{"bond":5,"health":-1,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"爱":4,"哀":2},"flag":"learned_light","thread":""}},{"title":"去灯油行应差","desc":"你去灯油行应了差，想多领一份光时贴补家里。","hint":"母亲那晚自己修了一盏灯。","tone":"practical","outcome":"行会的人让你先认三十种油，你记了半个月。回家晚，母亲一个人坐在灯前，把一盏坏灯拆了又装，装错了，灯油淌了一桌。她看见你，说：回来了。第二天她把桌子擦了，没提灯的事。你领的光时多了，家里的灯能亮到半夜，她的眼睛却越来越不愿睁，白天也拿布蒙着。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"惧":2},"flag":"","thread":"母亲白天也蒙着眼"}},{"title":"把灯招牌摘了","desc":"你收了门口的灯招牌，说以后不修了，在家陪她。","hint":"巷子里的人提着坏灯站在门口。","tone":"quit","outcome":"招牌摘下来那天，来了三个客人，看见门关着，站了一会儿走了。母亲坐在里间，听见脚步，问：谁啊。你说：走错了。她说：哦。那天下午她摸到柜底，摸出那盏藏了多年的好灯，用袖子擦了很久，又放回去。你看见了，没问。她也没说。","eff":{"bond":4,"health":0,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"柜底那盏好灯"}}]},{"id":"wu_m08","act":"main","age":[45,45],"mode":"dialogue","title":"日门迟开","opening":"四十五岁那年，日门该在午时开。午时过了，门是黑的。广场上的人不肯散，越聚越多，有人搬了凳子，有人抱着孩子。钟楼敲了一刻又一刻，敲到第三回，人群开始往前涌。你听见暗渠那边传来一声闷响，像水从地底翻上来。灯一盏一盏灭。你护着母亲往墙边退——她眼睛看不见，手抓着你的袖子——回头找小漏。她那天在日门当值，穿的是抄漏吏的青褂。","ask":"人往门那边涌，小漏还在里头，你去不去？","days":10,"npc":"sibling","memory":"日门没开的那天","choices":[{"title":"逆着人去找她","desc":"你把母亲按在墙根，自己逆着人流往门那边挤。","hint":"你后来一直记得那只鞋。","tone":"brave","outcome":"你被人撞倒两次，膝盖磕在台阶上。门边的灯全灭了，你摸到一只鞋，青布面，鞋底纳得密，是母亲的手艺。你把它揣进怀里，被人流推了出去。那天夜里小漏没回来。母亲在门口坐了一夜，手里攥着半截灯芯，谁劝也不进屋。天亮时她把灯点上，说：给她照着路。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":6,"爱":3},"flag":"lost_sister","thread":"你只找回她一只鞋"}},{"title":"先背母亲回家","desc":"你背起母亲往巷子里走，一次也没回头。","hint":"那一夜之后，母亲不再提日门。","tone":"protect","outcome":"母亲在你背上很轻，一路问：小漏呢。你说她在后头。进了巷子她才不问了。第二天小漏没回来。第三天钟警从暗渠口抬出七个人，盖着灯布。你没让母亲去看，自己去认的，回来说是别人。母亲点点头，从此再没问过，只是每天傍晚把门开着，留一条缝。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":6,"爱":2},"flag":"lost_sister","thread":"每天傍晚留一条门缝"}},{"title":"冲上钟楼敲钟","desc":"你逆着人流跑上钟楼，抓住那根旧绳敲了三下。","hint":"钟声救了一些人，也引来钟警。","tone":"report","outcome":"钟声压过人群的喊，钟楼的哨子响起来，闸门提前落下，把涌向门的人截成两半。有人骂你，有人跟着你往高处跑。小漏是后来从暗渠里抬出来的，手里还攥着抄漏的笔，笔尖弯了。钟警说：敲钟该有令。给你记了一笔。母亲去领人那天，把你留在家里，门从外面拴上了。","eff":{"bond":-3,"health":-1,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":3},"flag":"lost_sister","thread":""}}]},{"id":"wu_m09","act":"main","age":[60,60],"mode":"montage","title":"半条巷","opening":"六十岁那年冬天，巷子里的灯又坏了三盏。钟楼派下来的光时一年比一年少，家家把灯芯捻得比线还细。母亲是三年前走的，走前把一把小铜钥匙压在枕头下，没说是开哪把锁。你想起柜底那盏好灯——她藏了半辈子，说等好日子再点。钥匙正好开那把锁。你把灯取出来，铁皮上有一道她的指印，擦不掉。灌满油，换上整根灯芯，天黑时划了火，光一下子铺出去，铺到对门，铺到巷口，半条巷子都亮了。","ask":"半条巷亮了，有人端着空灯来借火。","days":60,"npc":"","memory":"照到巷口的光","choices":[{"title":"让灯一盏盏引火","desc":"你把灯挪到门口石墩上，谁来引火都不拒。","hint":"后半夜，你的油下去一半。","tone":"warm","outcome":"那晚来了十几家，有抱孩子的，有端着空灯盏的，有不好意思开口的老头。你坐在门槛上，看他们一个一个走回黑巷，灯一盏一盏亮起来。有个孩子回头喊：爷，明天还点吗。你说点。第二天油只剩个底，你去灯油行门口站了半天，空手回来的。晚上还是点了，短一刻。","eff":{"bond":5,"health":-1,"reputation":3,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"lit_alley","thread":"你答应孩子明天还点"}},{"title":"只借给阿萤","desc":"你招手让隔壁瞎眼的孩子过来，教他认灯芯。","hint":"别家站了一会儿，走了。","tone":"teach","outcome":"阿萤的眼睛看不见，手却稳。你教他用指头量灯芯，教他听油滚的声音。那晚别家没借到火，第二天巷子里有人说你小气，你听见了，没辩解。阿萤每天都来，坐在门槛上帮你绕灯芯。他走的时候总说：我闻得见你家的灯。你说明年让你点。他说好。","eff":{"bond":3,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"met_ayin","thread":"你说明年让阿萤点灯"}},{"title":"提灯回屋关门","desc":"你把灯提回屋里，插上门闩，让它只照一堵墙。","hint":"那晚你睡得很早。","tone":"alone","outcome":"光在墙上，墙上有你一个人影。你坐在灯前，把母亲留下的半截旧灯芯拿出来看，看了很久，没点。后半夜巷子里有孩子在哭，你听见了，没起身。第二天门口石墩上不知谁放了一小把灯芯草，捆得整整齐齐。你收进屋，放在柜底那盏空灯旁边。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":7},"flag":"","thread":""}}]},{"id":"wu_m10","act":"main","age":[70,76],"mode":"narration","title":"最后一次日门","opening":"七十岁以后，日子是按灯芯量的，一根烧完，就算过了一天。你走不快了，从门口到巷口要歇两回。七十六岁这年，钟楼贴出告示：漏壶要停了，日门最后开一次，就在下月十六。全城的人都往十二钟楼去，像你五岁那年一样。你坐在门槛上，把母亲留下的那盏灯擦了一遍。灯罩上有一道裂，是那年日门迟开时磕的。你老了，眼睛还行，看得见灯芯上落了一层薄灰。","ask":"日门最后一次开，这盏灯你留给谁？","days":30,"npc":"","memory":"留给谁的那盏灯","choices":[{"title":"把灯点在巷口","desc":"你把灯搁在巷口石墩上，给去日门的人照路。","hint":"你自己摸黑回来。","tone":"warm","outcome":"天没亮就有人从巷子过，一个接一个，灯在人流里晃。你坐在门槛上，看灯一点一点矮下去，像母亲当年剪的那截灯芯。人走完了，灯也灭了，巷子黑下来。你摸着墙往回走，走一步，停一步，到家门口时天还是黑的，可脸上有一点热。","eff":{"bond":4,"health":-4,"reputation":3,"coins":0,"stats":{"魅力":2},"emotion":{"爱":5,"哀":3},"flag":"gave_light_to_alley","thread":""}},{"title":"把灯交给阿萤","desc":"你把灯和那半截旧灯芯一起交给阿萤，教他护火。","hint":"你没去看最后一眼日门。","tone":"teach","outcome":"阿萤把灯抱在怀里，问你为什么不去。你说走不动了。他走了一段又回头，眼睛看不见，路却走得直。那天日门开时，巷子里只剩你一个。你把手伸出去，没摸着光，只摸到风。晚上阿萤回来说光很热，说门合上时有人哭。他把灯放回你门口，说：还你。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":5,"哀":3},"flag":"gave_lamp_to_ayin","thread":"阿萤把灯还回来了"}},{"title":"提灯自己去","desc":"你提上灯，拄着拐，跟着人流往钟楼走。","hint":"走到半路，灯油见了底。","tone":"seek","outcome":"你走得很慢，人流给你让出一条道。到广场时，日门已经开了，光落在你脸上，还是热的。你举起灯，灯芯借那点光烧得亮了一下。你想起五岁那年哭，觉得那时候的脸真嫩。门合上时你还在笑。回家路上灯灭了，你摔了一跤，是钟警把你搀回来的。","eff":{"bond":0,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":4,"哀":2},"flag":"saw_last_doorgate","thread":""}}]}],"side":[{"id":"wu_s01","act":"side","age":[7,7],"mode":"narration","title":"绳子外头的短芯","opening":"七岁那年，小漏带你去灯蕨坑拾剩料。坑在城西低处，一脚踩下去，泥从鞋帮边上翻上来。割过的畦上铺着一层断茎，晒干能搓最次的灯芯。料棚那头拉着一条麻绳，绳后堆着行会挑剩的短芯，白生生一堆，短，可还软。小漏说绳后不能去，去了要记名。你蹲下捡，看见一个比你矮半头的女孩贴着绳根，用树枝往里勾，勾一下，看一眼棚口那盏灯。她的影子压在绳上，细得像一根芯。","ask":"她回头朝你招手，你过不过去？","days":20,"npc":"","memory":"绳后的短灯芯","choices":[{"title":"蹲在绳外望风","desc":"你蹲到料棚拐角，替她盯着棚口那盏灯。","hint":"看坑人回来得比你想的早。","tone":"sneak","outcome":"她钻进去，把短芯一把一把往篮里捋。棚口那盏灯晃了一下，你咳了一声，她钻出来时篮子满了，你的鞋印却留在绳里。看坑人捏着你的后领问名字，小漏替你说了。回家母亲没骂，第二天一早提着一小包灯芯去行会门口站了半日。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"惧":2,"爱":1},"flag":"","thread":"母亲替你在行会门口站了半日"}},{"title":"把她拽出绳外","desc":"你抓住她手腕，把她从绳根拖出来，说那边不能去。","hint":"她篮子是空的，弟弟在家哭。","tone":"protect","outcome":"她挣了两下，没挣开，回头瞪你。篮子还是空的，她走时把树枝折成两截，扔在泥里。你捡起来，看见断口里有白浆。第二天她在坑口等你，塞给你一根短芯，说：这种带白圈的，烧得最长。她说完就走，没看你。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":1},"flag":"","thread":""}},{"title":"去喊看坑人","desc":"你跑回棚口，把看坑人叫醒，说有人钻绳子。","hint":"她记住了你的脸。","tone":"rule","outcome":"看坑人提着灯过去，把她从绳后拎出来，篮里的短芯倒了一地。她没哭，也没看你。看坑人夸你懂事，让你以后来拾料先挑。你挑了一捧最长的。回家路上小漏走在前头，一句话没说，进门才说：她家有个弟弟，喝米汤的。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s02","act":"side","age":[11,11],"mode":"narration","title":"纸屏上的影子","opening":"十一岁那年，母亲让你把一盏修好的灯送到旧闸口顶上的裁缝家。你放下灯，往下看。闸口底下就是影市，灯都蒙着布，只留一条缝，像一排闭着的眼。台阶上坐着个男人，支一面纸屏，屏后点一盏小灯。有人蹲下说话，他就站起来，让灯光把影子投在屏上，拿湿笔沿边描，揭下来递过去。他坐下，你才看清他身后墙上没有影子。有人叫他段七，问影子卖完了怎么办。他说：卖光正好，走路没人跟。","ask":"他朝灯抬了抬下巴，你站不站过去？","days":10,"npc":"","memory":"纸屏上揭下的影子","choices":[{"title":"站到灯前去","desc":"你走下去，站在灯前，让影子落在纸屏上。","hint":"你的肩头从此缺了一角。","tone":"trade","outcome":"他把你的影子描了一张，卖给一个给孩子做伴的老太太。揭的时候你肩上凉了一下，像有人用指甲轻轻刮过。他分给你一小段灯芯，说：拿回去，别说在我这儿站过。回家你照墙，影子右肩缺了一小块。母亲问是不是灯歪了，你说嗯。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"欲":1},"flag":"shadow_notched","thread":"右肩缺了一小块影子"}},{"title":"去叫看渠人","desc":"你提着灯跑下台阶，把看渠人从棚子里叫出来。","hint":"段七的纸屏被踩破了。","tone":"report","outcome":"看渠人提着灯下来，一脚踩在纸屏上，屏破了一个洞。段七没争，收起屏架就走。他从你身边过，看了你一眼，没说话。母亲知道后说：做得对，那种人少沾。第二天裁缝家的灯罩又熏黑了，抱回来修，你看见屏架的竹条靠在渠边，没人捡。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}},{"title":"绕另一条巷走","desc":"你把灯提好，从闸口后头那条窄巷绕过去。","hint":"你一直没有回头。","tone":"avoid","outcome":"那条巷窄，墙上滴着水，灯罩磕了三回。你把灯送到，裁缝家的女人试了试火，说比先前亮。回去的路上你走得很慢，走到岔口站了一会儿，还是走了大路。后来你每回送灯到闸口，都绕那条窄巷，绕了很多年，始终不知道段七后来去了哪。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s09","act":"side","age":[12,12],"mode":"narration","title":"听灯的老周","opening":"十二岁那年，母亲让我把一篮灯芯送到九坊上头的老周家。老周修了一辈子灯，四十岁那年让灯油熏坏了眼，从此不点灯，只接活。他坐在矮凳上，影子被桌上的灯推到墙上，比人还高。桌上排着七八盏别人的灯，盏盏都亮着，屋里却没有一盏是给他自己点的。他拿一根铜片贴在灯罩上听，听完把灯转半圈，说：这盏芯歪了。他把灯递给我，让我看。我看了半天，什么也没看出来。","ask":"他问我火苗什么样，我照实说吗？","days":10,"npc":"","memory":"铜片贴在灯罩上","choices":[{"title":"坐下说给他听","desc":"你把他的灯全点上，一盏一盏说火苗的形状。","hint":"回家时自家的灯早灭了。","tone":"help","outcome":"你说这盏火苗矮，发蓝，像含着一口水；那盏高，尖上分叉。他听着，手指在桌上跟着比，比你慢半拍。说到天快亮，你嗓子哑了，他的油也见了底。回家母亲站在门口，家里那盏灯早灭了，灶是凉的。第二天他托人送来一小截灯芯，剪得齐。","eff":{"bond":2,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"老周送来的一小截灯芯"}},{"title":"把实话说到底","desc":"你说他上回修的那盏灯，在客人家里冒了烟。","hint":"他把铜片放在了桌上。","tone":"honest","outcome":"他听完，手停在灯罩上，停了很久，说：我知道。第二天他把接的活一盏一盏退回去，铜片搁在桌角，再没碰过。行会来收灯牌，他没争，只问能不能把桌上那几盏修完。来收牌的人说不能。他坐在门口，脸朝着巷子，巷子里有人提灯走过，他也不知道。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"told_zhou_truth","thread":""}},{"title":"收下铜片就走","desc":"你把铜片揣进兜里，说回去想想，再没回去。","hint":"他等到入冬。","tone":"practical","outcome":"铜片贴耳，能听出芯烧到哪一寸，你后来靠它修好了不少灯。老周逢人问起你，就说这孩子耳朵好。入冬后有人来说他屋里冷，你去了一趟，门没锁，人已经硬了，桌上还摆着那七八盏灯，盏盏擦得干净，一盏也没点。铜片还在你兜里。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"欲":1},"flag":"","thread":"铜片还在你兜里"}}]},{"id":"wu_s15","act":"side","age":[15,15],"mode":"narration","title":"摸出来的三分","opening":"十五岁那年，霍伯来铺子里取灯。他在坊墙上修了四十年街灯，一根长竿挑罩，从底巷排到钟楼底下。四十岁那年他欠三刻光时，罚了暗禁，眼睛就是那年坏的。退牌后他把拆下的旧街灯收在屋里，一盏一盏擦。这盏是他头一回交到别人手上。进门不用人扶，先摸门框，再摸桌沿。他把灯捧起来掂了掂，往灯口里探，捏住芯头捏了捏，说：剪短了三分，省油。他的影子被灯推到墙上，那只手一直没动。","ask":"他问：这盏灯还算不算我修的？","days":10,"npc":"","memory":"剪短的三分芯","choices":[{"title":"说算，换整根新芯","desc":"你说算，回柜取出攒的整根芯，当他面换上。","hint":"你家这月的灯要短一截。","tone":"warm","outcome":"换芯时他一直听着，听见你把旧芯丢进废料盒，说：留着，还能点一炷。你没留。他抱着灯走到门口，回头说：省下的三分，客人看不见，天黑的时候他自己知道。那个月你家的灯烧的是剪剩的短芯，蓝了三回，母亲把灯挪得离墙远些。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":3},"flag":"","thread":""}},{"title":"收走他的刻刀","desc":"他要在灯座上刻自己的姓，你按住刀，说退牌的人不许留名。","hint":"他的手在桌沿停了一会儿。","tone":"rule","outcome":"行会的规定写在灯册第一页：退牌的人留名，出了事算铺子的。你把刀收进抽屉，说这盏灯以后署我的名。他点点头，把灯抱起来，抱得很稳。走到门口他停住，问：我修了四十年街灯，一盏都不算？你说：规矩。他哦了一声，鞋底在门槛上蹭了两下，走了。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"took_huo_knife","thread":"他没刻成的那个姓"}},{"title":"留他在铺里听灯","desc":"你请他每日来坐，把修好的灯一盏盏递到他手上过一遍。","hint":"行会迟早会问这个人是谁。","tone":"help","outcome":"他来了一个冬天，每天午后到，先摸门框。你修好的灯先给他过手，他捏芯头，听油滚，说哪盏还差半分。客人的灯经他手，一年没出过事。开春行会来人查铺子，问他是谁，你说是我师傅。他站在旁边，手垂着，没说话，等人走了才说：我担不起这句。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":2},"flag":"called_huo_master","thread":""}}]},{"id":"wu_s03","act":"side","age":[16,16],"mode":"narration","title":"灯罩里的孩子","opening":"十六岁那年冬天，你替母亲去漏底渠边收一盏旧灯。渠水比外头温，冒着一层白气，漂着灯芯草的碎屑。你蹲下够那盏灯，听见水声底下有别的动静，细，断断续续，像猫。渠壁凹进去一个洞，洞里搁着一只破灯罩，罩里裹着一块灯布，布里是个孩子，脸冻得发青，嘴还在动。灯罩边上压着半截灯芯，没点过。你把他抱起来，他轻得像一只空灯罩，渠壁上你的影子被水汽糊成一片。","ask":"孩子在你怀里轻得像空灯罩，抱去哪？","days":15,"npc":"","memory":"灯罩里的孩子","choices":[{"title":"抱回铺子里","desc":"你把孩子裹进怀里，一路小跑回修灯铺。","hint":"家里的灯从此要挪到墙角。","tone":"carry","outcome":"母亲接过孩子，先摸嘴，再摸手脚，叫你去热米汤。父亲回来在门槛上坐了很久，说：又添一张嘴。第二天他去司昼院，把孩子记在一个死了多年的姑婆名下，回来时鞋上全是泥。那盏家里的灯从此挪到墙角，罩子朝外，怕晃孩子的眼。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"took_foundling","thread":"孩子记在一个死人的名下"}},{"title":"抱去钟楼登记","desc":"你抱着孩子走到十二钟楼底下，交给值夜的小吏。","hint":"小吏问了你家的灯牌号。","tone":"rule","outcome":"小吏把孩子放在一张矮桌上，翻册子，问你的名字、住哪条巷、家里几口人、灯牌几号。你一一答了。他说：登记在渠籍，长大了送去灯蕨坑。孩子忽然哭起来，声音在钟楼底下撞来撞去。你走出很远还听见。回家母亲问你的手怎么这么凉，你说水边风大。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"怒":2},"flag":"","thread":""}},{"title":"放在有灯的门槛上","desc":"你抱着孩子绕到亮着灯的巷子，放下一家门槛上，敲了门就走。","hint":"你躲在拐角，看见门开了。","tone":"sneak","outcome":"门开了一条缝，一个女人的影子探出来，先看巷子两头，再低头。她把孩子抱起来，往怀里按了按，回身把门关上，门缝里的光也收进去了。你蹲在拐角等到天快亮，那家的灯一直没灭。后来你每回从那条巷过，都要看一眼门槛。","eff":{"bond":0,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"爱":2},"flag":"","thread":""}}]},{"id":"wu_s16","act":"side","age":[20,20],"mode":"narration","title":"影市里的豆儿","opening":"二十岁那年，你去影市换半勺油。市在旧闸口底下，灯都蒙着布，只留一条缝，人从缝里过，脸被照成一条一条。你蹲在摊前数灯芯，背后有人叫：豆儿。声音不高，像在自家院里喊孩子。你没回头。她又叫一声，添了半句：豆儿，你娘生你那晚让我剪的芯，我还留着半截。你转过身，看见一个卖时辰的老女人，眼睛只剩一层白，秤盘上叠着别人的影子，方方正正。","ask":"她朝你伸出手，叫第三声豆儿。","days":10,"npc":"","memory":"叫出小名的人","choices":[{"title":"应声，替她还光时","desc":"你走过去应了，问清她欠的三刻，拿自己灯牌抵。","hint":"往后半年，你的灯要早灭一刻。","tone":"warm","outcome":"管市的人把灯牌号抄走，说从下月起扣，扣满三刻。她从秤盘底下摸出一小截灯芯，油纸发黄，芯头是个旧剪口。她说你娘那晚手抖，剪了两回才剪齐。你捏着那半截往回走，一路没点灯。那年冬天你家的灯每天早灭一刻，母亲问过一回，你说油不好。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"answered_childhood_name","thread":"她给的半截旧灯芯"}},{"title":"去叫管市的人","desc":"你退到布帘外，把管市的女人叫来，说她欠光时。","hint":"她被架走时没再叫你。","tone":"report","outcome":"管市的女人带着两个提灯的人下来，翻开她的秤，说她欠三刻，欠了两年。她被架着往暗渠那头走，脚在地上拖出两道印。走到帘口她回头，嘴动了一下，没出声。你站在布帘外，听见里头有人接着秤东西，秤砣磕在盘上，一下，一下。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"只认名字不认账","desc":"你说这名字是我娘起的，账我不认，转身往外走。","hint":"她在后头说了半句什么。","tone":"refuse","outcome":"她没拦。你走出三步，她在后头说：你娘那晚……话头被市上的秤声压住，听不真。你回头，她已经坐回摊子，秤盘上换了一叠别人的影子。往后你还去影市换油，从她摊前过，两个人都当不认识。那句没说完的话，你猜了很多年，猜到自己也老了。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s04","act":"side","age":[22,22],"mode":"narration","title":"灭了灯才说话","opening":"二十二岁那年，铺子关到最后一盏灯。有人站在门口，不进，背着光。他说：把灯灭了，我才说。你以为是讨水的，说铺子要关门了。他把一只灯搁在门槛上，灯是好的，罩子擦得干净，里头一滴油也没有。他说：修好它，别点。你说不点怎么修。他往里走了两步，停在灯照不到的角落，说：你修你的，我在暗处说。母亲在里间听见他的声音，把门帘放下了。","ask":"他在暗处坐下，叫了一声阿棠，你应不应？","days":30,"npc":"","memory":"暗处的那一声","choices":[{"title":"应一声，接着修","desc":"你嗯了一声，摸黑拆灯，听他说下去。","hint":"你替一个死人应了声。","tone":"secret","outcome":"他在暗处说话，说这灯是他闺女修的，说她的手一到冬天就裂口子，说灯油味洗不掉。说到一半他叫阿棠，问你手怎么这么凉。你嗯了一声。天亮前他走了。母亲掀帘出来，看见门槛上的灯修好了，问是谁。你说不认识。她摸了摸灯口，说：这灯是阿棠的。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"answered_as_atang","thread":"你替阿棠应了声"}},{"title":"点灯，把话说清","desc":"你划火点灯，照着自己，说我不是阿棠。","hint":"他抬手挡眼，退到门槛外。","tone":"honest","outcome":"光起来的一瞬，他拿手背挡眼，退到门外。你说我不是阿棠，我是修灯的。他站了一会儿，说：我知道。他把灯抱走，走得很慢。母亲掀帘出来，站在门口看他的背影，说：他是阿棠的爹。她说完回屋，半天没点灯。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"把暗铺子留给他","desc":"你披衣出门，把暗铺子和那只坏灯留给他。","hint":"天亮回来，他坐过的地方是凉的。","tone":"alone","outcome":"你在渠边坐到后半夜，水声盖住钟楼的一刻。回来时门开着，人没了，灯修好了，灯口对得很正。案上留着一小截灯芯，剪得齐。母亲坐在里间没睡，问：他走了？你说走了。她说：阿棠修灯，也留这么一截。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_s05","act":"side","age":[27,27],"mode":"narration","title":"守灵的那一夜","opening":"二十七岁那年，楼上陈嫂的男人走了。他在灯蕨坑下头扛料，夜里回来咳，咳了半年，最后一口没上来。陈嫂来敲你的门，围裙还系着，手上沾着面。她说她得去顶他的夜班，不去，灯牌要收，家里两个孩子就得摸黑。她说：你替我守他一夜，灯不能灭，人不能离。你上楼，屋里收拾过了，他躺在两块门板拼的床上，脸上盖着灯布，脚边点一盏小灯，芯剪得很短。灯把他的影子投在门板上，影子比人长。","ask":"陈嫂把门钥匙塞进你手里，这一夜怎么守？","days":10,"npc":"","memory":"门板上的影子","choices":[{"title":"坐到天亮","desc":"你在门板边坐下，守着灯，隔一阵剪一次芯。","hint":"你自己家那盏灯忘了点。","tone":"stay","outcome":"后半夜你跟他说了很多话，说你爹的腿，说你娘补灯罩的手，说铺子里修不完的灯。说到灯芯只剩一指长，窗纸还是黑的。天亮前你听见他咳了一声，抬头才想起他已经不咳了。陈嫂回来时灯还亮着，她站在门口，没进来，先看了一眼灯芯。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"你跟他说的那些话"}},{"title":"替他上夜班","desc":"你揣上他的更牌，下楼，替他扛这一夜料。","hint":"陈嫂守着他，你替他去黑里走。","tone":"carry","outcome":"更牌上的字磨得快看不清。你扛到第二趟，肩膀就破了。老吴问你他是你什么人，你说邻居。他把最轻的一头让给你。天快亮时你想起楼上那盏灯，不知灭没灭，脚步乱了。后来陈嫂说，那夜她一个人对着门板，连个说话的都没有。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":2},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}},{"title":"守到子时就走","desc":"你把灯芯挑亮些，守到子时，锁门下楼。","hint":"那盏灯要烧到天亮，油不够。","tone":"leave","outcome":"你走时灯点得很亮，屋里比平时都亮。第二天早上陈嫂来还钥匙，说灯后半夜就灭了，油见了底。她说没事，人都走了，谁还看得见。她把钥匙放回你手心，指头凉。你后来总想起那盏灯灭下去的时候，屋里大概有多黑。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}}]},{"id":"wu_s17","act":"side","age":[28,28],"mode":"narration","title":"跪在光里的人","opening":"二十八岁那年，日门开在辰时。你挤到第三排，前后都是提灯的人，灯套着布，布底下透出一点红。门缝先白，后金，光斜着扫过来，落在后颈上，像有人把手贴上来。就在这时候，你脚边一个男人跪下去了。他四十来岁，穿灯蕨坑的短褂，两只手把一只空灯盏举过头顶，盏口朝着门。他不出声，只把灯举得更高，胳膊在抖。旁边的人往两边让了半步。","ask":"他跪在光里举着空灯，你怎么办？","days":10,"npc":"","memory":"空盏举过头顶","choices":[{"title":"蹲下替他挡着","desc":"你蹲下，解开外衣罩住他半边，替他把灯举稳。","hint":"钟警会记下你的灯牌号。","tone":"protect","outcome":"光落在两个人身上，他那只空盏里积了一点热，盏底烫手。钟警过来，用棍子挑开你的外衣，记了你的灯牌号，扣半刻。男人抱着灯一路弯腰跑回去，鞋掉了一只也没捡。后来你听说他闺女在黑户的屋里看见小半炷香的光，看见什么，没人问过。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"shielded_kneeler","thread":"记在你灯牌上的半刻"}},{"title":"拉起他罩上灯布","desc":"你抓住他胳膊把他拽起来，把灯布罩上他的灯盏。","hint":"他的手一直没松开。","tone":"rule","outcome":"他跪不住，被拽起来，灯布一罩，盏口那点热就散了。他没争，只说：我闺女十一年没见光。钟警从旁边过去，看了你们一眼，走了。他把空灯抱在胸前，站到日门合上，人群散尽才走。第二年他还在那个位置，还是跪着，你没再过去。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"","thread":""}},{"title":"让出我的位置","desc":"你往旁边退，把他推到自己的位置上，转身出人群。","hint":"这一年你没看见日门开。","tone":"leave","outcome":"他跪在你原来的地方，前头再没人挡。你逆着人流往外走，走到广场边上，听见后头一片抽气声，接着是钟响。你回头看，光是白的，落在别人背上。回家母亲问今年亮不亮，你说亮。她点点头，把灯芯捻小一截。那天你的影子一直落在后头，没跟上来。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"wu_s10","act":"side","age":[31,31],"mode":"narration","title":"渠下的四十盏灯","opening":"三十一岁那年，有人叫我去漏底渠第三道闸下修灯。接活的是个女人，围裙上补了四块布，领我下了十七级台阶，推开一扇包着旧灯布的门。门里是一条长屋，梁上晾着灯芯草，桌上点着四十来盏灯，灯罩都用纸糊过，光不外泄。十几个孩子坐在灯下描字，影子在墙上叠成一片，没有一个交光时。女人说：这里的灯不收光时，谁家孩子要认字，就来。","ask":"她问能不能每月送一桶油来。","days":360,"npc":"","memory":"渠下的四十盏灯","choices":[{"title":"应下每月送油","desc":"你说好，从自家那份油里匀，每月十五送来。","hint":"你家的灯从此短一刻。","tone":"warm","outcome":"你送了三年。头一年用自家的油，第二年掺了灯蕨坑捡的剩料，火发黄。母亲问油怎么少了，你说铺子用。第三年冬天你提桶下台阶，脚下一滑，桶磕在墙上，漏了半桶，你用手把剩下的捧回罐里。孩子们那晚照旧描字，描到很晚，描完把纸压在灯座底下。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":2},"flag":"carried_oil","thread":"你送了三年的油"}},{"title":"去钟楼说一声","desc":"你上到地面，直接去钟楼，说渠下有人私点长明灯。","hint":"四十盏灯，一盏也没留下。","tone":"report","outcome":"钟警下去的时候是亮班。门被撞开，灯布扯下来，光一下子涌到渠壁上，孩子们的手还按在纸上。女人被带走，说是聚众。你站在台阶上头，听见下面有人喊了一声娘。后来那间长屋锁了，锁上生了锈，纸糊的灯罩散在渠边，被水泡烂，没人捡。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"reported_dawn_society","thread":"渠下那一声娘"}},{"title":"抱一盏回铺子","desc":"你挑一盏最亮的抱走，挂在铺子门口当招牌。","hint":"她不问，也不来要。","tone":"greed","outcome":"那盏灯挂在铺子门口，夜里不灭，来修灯的人都说这家有长明灯，靠得住。你的活多了三成。第二年春天你路过第三道闸，台阶上长了一层青苔，门缝里没有光。你想起抱走的那盏灯，灯座底下刻着一个孩子的名字，刻得很浅，被油浸黑了。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"机缘":1},"emotion":{"欲":2,"哀":3},"flag":"","thread":""}}]},{"id":"wu_s06","act":"side","age":[34,34],"mode":"montage","title":"念不完的信","opening":"三十四岁那年，巷尾阮先生叫你念信。他眼睛坏了，只认声音。儿子在日门做工，一季一封信。这封是脚夫捎来的，压着声说：人去冬没了，信是工友凑钱写的。你进屋点灯。他侧着头听，手捏住你一点袖口，捏到念完才松。他说：我这辈子没见过白天。生在暗班，长在灯下，每回排到队尾，等挤到前头，门就关了。你这才知道，他不是没赶上，是一回也没轮到。信念到最后多一行：下月十六，儿回。","ask":"他问下月是不是真能回，你怎么答？","days":120,"npc":"","memory":"念给阮先生的信","choices":[{"title":"照信念完","desc":"你把最后一行又念了一遍，一个字没改。","hint":"你每季都得来念一封。","tone":"obey","outcome":"他听完，把信叠好，压在枕头下，说下月要买半斤好油，灯点整夜。你走时他送到门口，扶着门框。下月到了，人没来。他又叫你去念旧信，一封一封，念到第三封时说：不急，路上慢。你看见桌上多摆了一副碗筷，筷子头朝外。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":""}},{"title":"把实情说出来","desc":"你放下信，说脚夫讲，日门那边早没有这个人了。","hint":"他从此不叫你念信了。","tone":"tell","outcome":"他听完，手还按在桌沿上，按了很久，指节发白。他说：我知道了。他把信一封一封收进一个木匣，匣子盖不上，用绳捆了。你再去，门是开的，他坐在暗处，桌上没点灯。邻居说你走以后，他再没让人念过信，也没再摆那副碗筷。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":2},"flag":"told_ruan_truth","thread":"他再没让人念过信"}},{"title":"替他写回信","desc":"你回去裁纸，学代书人的字，替他儿子写一封。","hint":"你的字比代书人硬。","tone":"secret","outcome":"你写：工程未完，明年回。念给他听时，他说这一封怎么这样短。你说代书人忙。他把信贴在脸上，闻了很久，说：有灯油味。你说路上沾的。他把信跟别的信放一起，用一块灯布包着。后来每季你都写一封，写到第五封，他已经记不清儿子的字长什么样了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"wrote_letters","thread":"你替人写了五封信"}}]},{"id":"wu_s18","act":"side","age":[36,36],"mode":"narration","title":"半刻引路灯","opening":"三十六岁那年冬天，影市后巷抬出一个人。管市的人把他放在渠沿上，脸盖灯布，脚上一只鞋。你认得他：段七，二十年前在闸口支纸屏卖影子。后来影子卖光了，人还在，走路没人跟。他身上那盏小灯的芯还是新的，剪得齐。管市的女人翻出一张灯牌、半张纸，说他欠半刻光时，欠了四年。欠着的人不能点引路灯，也不能进化灯房——化灯房在日门西边，一年只开三回。她把灯牌丢进渠里。","ask":"她等着有人认这半刻，你认不认？","days":10,"npc":"","memory":"半刻的引路灯","choices":[{"title":"替他补上这半刻","desc":"你把自己的灯牌递过去，说这半刻记在我名下。","hint":"这半年你家的灯早灭一刻。","tone":"pay","outcome":"管市的人在灯牌上划了一道，说分三个月扣。段七得了一盏纸糊的引路灯，点起来只有豆大。你把灯搁在他脚边，看他被抬进化灯房，墙上没有影子。回家母亲还没睡，问你怎么这样晚，你说市上人多。那三个月你家的灯每天早灭一刻，她没问，只把灯往你这边推了推。","eff":{"bond":2,"health":-2,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":3},"flag":"paid_duan_seven","thread":""}},{"title":"报作无名尸","desc":"你说不认识他，让管市的人按无名尸登记。","hint":"册子上少了一个名字。","tone":"rule","outcome":"管市的女人点点头，在册上写：无名，男，约四十。灯牌收了，那盏小灯没人要，塞给你。你走出巷子，忽然想起二十年前他描影子时手腕上有一道疤。回家你把小灯点上，灯座底下刻着一个七字，刻得很浅，被油浸黑了。你看了很久，把灯放到柜子最高一层。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"灯座上那个七字"}},{"title":"卖他的灯抵债","desc":"你把那盏小灯拿到当铺，换了半刻，抵他的欠。","hint":"灯座上那个字，你没看清。","tone":"practical","outcome":"当铺的人掂了掂，说铜座还值点。半刻抵上了，段七有了一盏纸糊的引路灯，抬进了化灯房，墙上空着。你捏着当票往回走，走到半路才想起灯座上刻过一个字，当时油黑，没看清。那盏灯后来被人赎走了。赎的人是谁，当铺不说，你也没再问。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"欲":1},"flag":"","thread":""}}]},{"id":"wu_s11","act":"side","age":[42,42],"mode":"narration","title":"闸口的三十息","opening":"四十二岁那年，老吴要去喝他闺女的喜酒，叫我替他守一夜闸。闸在漏底渠第二道口，一块铁板，一根绞绳，规矩是每刻开一次，数到三十息就关。关早了，水退回灯蕨坑，泡烂一畦芯草；关晚了，水往第七坊的下巷灌。老吴把更牌塞给我，教我听水声：声音变闷，就是要满。他走的时候换了身干净衣裳，鞋是新纳的，影子在渠沿上拉得很长。","ask":"第三刻，渠里有人拍铁板，你开不开？","days":10,"npc":"","memory":"绞绳上的手印","choices":[{"title":"多开二十息","desc":"你把绞绳多放二十息，让渠里的人爬出来。","hint":"下巷的水漫过了门槛。","tone":"risk","outcome":"爬出来的是灯蕨坑的四个女人，裤腿全湿了。她们刚上台阶，水就翻过渠沿往下巷去，谁家的门板被水推得撞墙。行会来人量了水线，扣了你一季光时。那四个女人里有一个后来给你送过一双补好的袜子，没留名字，袜底纳得密。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"替四个女人担的一季光时"}},{"title":"数到三十就关","desc":"你数得很慢，数到三十，照规矩把闸压下去。","hint":"拍板声响到后半夜。","tone":"rule","outcome":"铁板压下去，水声闷了一下，接着又响。拍板的声音一下一下，慢下来，后来没有了。天亮老吴回来，看了看水线，说：你没多开，对。他蹲在渠边抽了一袋烟，说上回有人多开十息，西头的墙塌了，压死九个。他把烟灰磕在水里，水面浮起一层白。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"惧":3},"flag":"closed_gate_on_time","thread":""}},{"title":"先回家搬东西","desc":"你跑回下巷，把自家的灯和油搬到高处，再回来。","hint":"回来时闸已经自己漂开了。","tone":"practical","outcome":"你把灯、油罐、母亲的牌位都搬到阁楼。回来时绞绳松了，闸板被水顶开一掌宽，下巷已经进了水。你踩在水里把闸压回去，压了半个时辰，膝盖抖得站不住。第二天行会问是谁当的班，你说是我。老吴在旁边看着你，什么也没说。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"老吴什么也没说"}}]},{"id":"wu_s19","act":"side","age":[48,48],"mode":"narration","title":"天黑是因为没人点灯","opening":"四十八岁那年，巷子里的灯又少了两盏。日门迟开过那一回以后，钟楼派下来的光时一年比一年薄，入夜只剩三四点光，风一过就晃。隔壁阿荞五岁，她娘在灯油行糊纸袋，常常整夜不回。那天她坐在你门槛上，看你修灯，嘴里嚼着一根没点的灯芯草，嚼得只剩一头。看了很久，她忽然问：天黑，是不是因为没人点灯。她问得很认真，两只手撑在膝盖上，影子投在门槛里头。","ask":"她等着你答，你怎么跟她说？","days":30,"npc":"","memory":"天黑是不是因为没人点灯","choices":[{"title":"带她去点灯","desc":"你提上灯，牵着她，把巷里空着的灯座一盏盏点上。","hint":"回家时你自己的油见了底。","tone":"warm","outcome":"点到第五盏，油只剩一个底。阿荞踮着脚帮你把灯芯拨正，指头烫了一下，缩回去含在嘴里。那晚巷子亮到后半夜，她娘回来时在巷口站住，抬头看了一路。第二天你家没油，摸黑吃的饭。阿荞端一碗汤过来，说：我给你照路。她手里举着一根点着的灯芯草。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"","thread":""}},{"title":"告诉她天本来这样","desc":"你说天不是谁点黑的，它本来就这样，点灯也点不亮。","hint":"她以后不再问这类话。","tone":"honest","outcome":"她听完，哦了一声，把手从膝盖上拿下来，坐了一会儿就回家。后来她再没问过灯的事。她娘说她夜里不再哭着要灯，睡得很老实。有一年巷里点长明灯，别家孩子都挤在门口看，她站在自家门里，隔着门缝看，看了一会儿就把门关上了。","eff":{"bond":-1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"told_child_darkness","thread":""}},{"title":"挂出她的问话","desc":"你把她的问话写在灯罩纸上，挂在铺子门口，让人答。","hint":"行会的人会来撕这张纸。","tone":"niche","outcome":"来修灯的人看见了，有的写：是。有的写：不是，是灯少。有个老头写了半行又划掉。纸挂了整整一冬，边角被油烟熏黑，答话挤得没处写。行会在巷口钉了块木牌，说铺面不许贴字，撕下纸卷走了。阿荞等他们走远，从袖里摸出一小片纸，说：我抄了一份。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"爱":2},"flag":"","thread":"阿荞抄的那小片纸"}}]},{"id":"wu_s12","act":"side","age":[52,52],"mode":"narration","title":"静下来的三分钟","opening":"五十二岁那年，日门开在午时。广场上挤得转不开身，人人提着灯，到门边就把灯罩上布套。隔壁的瞎眼孩子阿萤十一岁，第一次被带来，手抓着我的袖子。钟楼敲到第十二下，声音停了，广场一下子没了响动。连卖汤饼的都不翻勺，风把谁的灯布吹起来，也没人去按。静得能听见渠里的水。阿萤在我手心里敲了一下，问：来了没有。","ask":"静得能听见水，这三分钟怎么过？","days":10,"npc":"","memory":"手心上的暗号","choices":[{"title":"在他手心敲回去","desc":"一下是没来，两下是快了，光落下来时你按住他的手。","hint":"今年你自己没抬头。","tone":"warm","outcome":"你敲一下，他抿嘴；敲两下，他仰起脸。光落到广场上时，你看见他眼皮动了一下，赶紧把他手按平。他站着不动，脸朝着门那边，鼻翼一张一张。三分钟过完，人群出声，他问你亮不亮。你说亮。他笑了，问明年还来不来。你的影子被光压回脚边。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":2},"flag":"told_ayin_light","thread":""}},{"title":"拽住插队的人","desc":"一个后生贴着墙往前挪，你抓住他后领，把他拽回来。","hint":"他怀里的灯摔碎了。","tone":"rule","outcome":"他往后一退，撞在别人身上，灯掉在地上碎了，响声在静里头炸开。半广场的人回头。他蹲下去捡碎片，说替他娘占的位置，他娘腿不好。钟警过来把他带出去。那一年有人说光被这声响惊短了，你走过巷子，有人在背后指，指到你拐弯。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"哀":4},"flag":"","thread":"那一年有人说光短了"}},{"title":"悄悄往前挪","desc":"你扶着阿萤，借着没人动，往前挪了七个位置。","hint":"后头抱孩子的人退了一步。","tone":"sneak","outcome":"你挪到第三排，光落在脸上，热的，眼皮上有一层红。身后有人轻轻嗯了一声，是个抱孩子的女人，孩子被挤得背过脸去。门合上时你回头看，那女人还站在原地，孩子睡着了。阿萤问你刚才怎么走得那么快。你说人多。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"欲":2,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s07","act":"side","age":[55,55],"mode":"narration","title":"一整夜的灯","opening":"五十五岁那年，灯油行的人叫你去祁府装一盏灯。祁府在第七坊上层，门前的灯牌是铜的，刻着一个祁字。管家领你进后院一间空屋，屋中央摆着一盏半人高的铜灯，灯腹能装一整壶油。管家说：老爷要这灯点满十二刻，一夜，不许灭。你问点给谁看。他说：不给人看，给刚落地的小少爷积福。灯油行的人量了十二刻油，一勺一勺往里灌，灌到灯口平了。那袋漏钱搁在桌上，谁也没数。","ask":"铜灯灌满了油，这火你接不接？","days":15,"npc":"","memory":"十二刻的铜灯","choices":[{"title":"换上自己的灯芯","desc":"你支开管家，把行会配的芯换成自己带来的好芯。","hint":"这个月的灯芯少了一段。","tone":"repair","outcome":"行会的芯是陈的，烧到第六刻就会炸花。你换上自己那根，火苗立得直，屋里亮得能看见梁上的灰。你蹲在灯边看了半个时辰，想起你爹说过，一辈子没点过整夜的灯。管家进来添茶，问你蹲着做什么，你说看火。他说：火有什么好看。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":"一根不留名的好灯芯"}},{"title":"问起灯牌上的名字","desc":"你指着门前的铜灯牌，问管家老爷是不是叫祁九。","hint":"管家看你的眼神变了。","tone":"ask","outcome":"管家说，老爷的名讳不是你能叫的。他顿了顿，又说：老爷年轻时在司昼院做过事，借名的事多了，谁记得清。你想起二十四岁那年，你爹递给你一张纸，上头另一个名字，就是祁九。管家把工钱结给你，让你从后门走。你走出祁府，回头看见那间屋的窗纸后头白得晃眼。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"恶":2},"flag":"asked_qijiu","thread":""}},{"title":"点着就走","desc":"你划火点灯，看火苗站稳，收了工钱就回巷子。","hint":"回家那盏灯，你一直没点。","tone":"practical","outcome":"灯点起来时，屋里一下子没了影子，四个墙角都亮。你退到门口，眼睛胀，缓了一会儿才看清台阶。回家母亲还没睡，在里间问：点上了？你说点上了。她又问：整夜？你说整夜。她哦了一声，把灯芯捻得更小。那晚你家的灯比平时早灭了一个时辰。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"wu_s13","act":"side","age":[63,63],"mode":"narration","title":"第一次看见火","opening":"六十三岁那年，渠边一户人家叫我送灯。门是两块旧板拼的，进门先要弯腰。屋里没窗，四壁糊着灯布，布上有一块块深色的印子，是多年熏出来的。女人把门闩上，才把桌上的灯布掀开一条缝。她儿子四岁，从生下来就没见过火，只见过布底下的光。孩子凑过去，眼睛刚睁开就哭了，哭得喘不上气，一边哭一边往后退，退到墙角，用手背挡着脸。","ask":"孩子哭得发抖，这盏灯留不留？","days":60,"npc":"","memory":"布底下的一线光","choices":[{"title":"陪着，一层层揭","desc":"你坐下来，把灯布一层层揭，每揭一层就停一会儿。","hint":"你回家时巷门已经落了闩。","tone":"heal","outcome":"揭到第三层，他不哭了，只抽气；揭到第五层，他伸手来够火，影子小小地落在墙上。天快亮时他睡着了，脸朝着灯。你出门晚了，巷门落了闩，钟警记了你的灯牌号，扣两刻。女人送你到门口，说下回不敢再叫你来。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"brought_light_to_child","thread":"扣掉的两刻光时"}},{"title":"提灯转身就走","desc":"你说黑户点灯要连累整条巷，把灯提起来，闩上门。","hint":"女人在门里说了声谢。","tone":"protect","outcome":"你走在下巷，还听得见那孩子在哭，哭一阵，停一阵。第二个月钟警来查灯牌，下巷有几家被断了三夜光，有个老人夜里起来摔断了腿。女人家的门一直关着。开春你从那儿过，门板上贴了一张新纸，写着此户已迁。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"门板上那张此户已迁"}},{"title":"剪一条缝","desc":"你用灯布罩住灯，在朝墙那边剪一条指宽的缝。","hint":"那条缝留了整整一冬。","tone":"practical","outcome":"光贴着墙走，不朝门。孩子慢慢敢看了，每天坐在墙根，把手伸进那道光里，影子很小，像一只摊开的手。入冬后有一夜，巡巷的钟警看见门缝下有一条亮线，敲了门。第二天那户人家搬走了，桌子还在，灯布叠得整齐，压在灯座上。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}}]},{"id":"wu_s20","act":"side","age":[66,66],"mode":"narration","title":"省下来的三十一根","opening":"六十六岁那年冬天，油又薄了。你坐在灯下穿芯，剪子量了量，往下挪半寸，剪断。剪完没动，看着那截短的——母亲的手势，她剪了一辈子，剪到眼睛坏。她留下的灯摆在桌角，罩上那道裂还在。柜里一只旧罐，装着半年省下的短芯，一根根用纸捻着写了日子，你数过，三十一根。灯把你的影子推到罐子上。有人敲门，隔壁新搬来的女人端着空灯盏，说家里灯牌没办下来，孩子夜里咳，想借火。","ask":"她端着空灯盏站在门口，你怎么办？","days":60,"npc":"","memory":"三十一根短芯","choices":[{"title":"倒空那罐灯芯","desc":"你把三十一根短芯都倒进她灯盏里，说够点一阵。","hint":"你自己接着剪短芯。","tone":"warm","outcome":"她捧着灯盏，说这怎么好。你说拿着，孩子夜里要吃奶。她走几步又回来，把芯拨出一半放回你桌上，说够了。你追出去，她已经拐进巷子。那晚你把拨回来的一半摊在桌上数，十六根，长的长短的短。你点了最短的一根，坐到很晚。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}},{"title":"照册子记她一笔","desc":"你翻开灯册，问她姓名住处，把这一盏记在上头。","hint":"她没有灯牌，钟警会来收灯。","tone":"rule","outcome":"她报了名字，说住在西头第三间。你写完，合上册子，说这是规矩，没牌的人家不能借火。第三天钟警来敲门，把她家的灯收走了，说黑户点灯要罚三夜暗禁。她抱着孩子站在巷子里，没骂你。孩子咳了一夜，第二天你听见那声音换到别处去了。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"recorded_black_household","thread":"她抱着孩子站在巷子里"}},{"title":"剪成两段教她点","desc":"你取一根短芯剪成两段，教她分两晚点，各点一半。","hint":"孩子后半夜还是咳。","tone":"teach","outcome":"她学得很快，两段芯用纸捻好，揣进袖里。走时她说了三声谢。你关上门，坐在灯下，忽然想起母亲生你那晚也是这么剪的，一截今晚点，一截压在枕下。你把手里的剪子放下，又拿起来，把自家那根也剪短了半寸。那晚隔壁的咳嗽声断断续续，一直到亮班。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"你把自家的芯也剪短了"}}]},{"id":"wu_s14","act":"side","age":[72,72],"mode":"narration","title":"借出去的灯","opening":"七十二岁那年，我把灯借给了一个抱孩子的女人。她说天亮前还，放在巷口石墩上，说的时候孩子在她肩上睡，脸压得扁。天亮了她没来，第二天也没来。那盏灯的罩子上有一道裂，是我自己磕的，别人不一定认得，我认得。没有灯，家里那几晚就早早点上短芯，一碗饭吃完就灭。第七天，我在第三坊的当铺窗里看见了它，摆在最里头，罩子朝外，那道裂对着街。","ask":"灯在当铺窗里，你进不进去认？","days":200,"npc":"","memory":"当铺窗里的裂","choices":[{"title":"认了，转身走","desc":"你在窗外站了一会儿，什么也没说，回巷子去了。","hint":"夜里起身，你摸不准台阶。","tone":"leave","outcome":"你回去把短芯又剪短一截，一晚上只点半个时辰。冬天有一夜你起来添水，脚在台阶上踩空，磕了膝盖，坐了很久才爬起来。后来你不再走第三坊那条街。有人问起那盏好灯，你说送人了，说到这句就停住，不再往下说。","eff":{"bond":-1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"你不再走第三坊那条街"}},{"title":"去钟楼告她","desc":"你说灯是借出去被当的，请钟警按偷光论。","hint":"她抱着孩子跪在当铺门口。","tone":"report","outcome":"钟警查了当票，找到她家。她抱着孩子跪在当铺门口，说男人走了，孩子发热，当的是油钱。灯追回来了，罩子上多了一道新磕痕。她按手印认了罚，孩子在旁边一直咳。你抱着灯往回走，灯很轻，轻得不像话，你换了只手提。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_borrower","thread":"灯罩上多了一道磕痕"}},{"title":"让她来点灯","desc":"你找到她家，说灯给她用，往后每天来替你点一次。","hint":"她来了整整一个冬天。","tone":"deal","outcome":"她每天傍晚来，先把灯点着，再把你的水缸挑满，孩子放在门槛上玩灯芯草。开春她们搬走了，没留下话。你还是每天傍晚把灯摆在桌上，摆到天全黑，才自己去点。听着巷子里的脚步声，你总要先抬头看一眼门。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":""}}]},{"id":"wu_s08","act":"side","age":[74,74],"mode":"narration","title":"教小半认光","opening":"七十四岁那年，阿蕨拄着拐来敲你的门。她比你小一岁，左手食指上一道旧疤，是小时候在灯蕨坑让麻绳勒的。她说重孙小半六岁，夜里总哭，说黑里有东西。她把他推到你面前：你教教他，你眼睛快不行了，手还灵。孩子站在灯边不敢伸手，鼻子先凑过去，闻灯油，闻灯芯草，闻你手上的味道。你想起三十岁那年，母亲闭着眼，也是这样教你。","ask":"小半问，灯灭了，黑到哪里去了？","days":20,"npc":"","memory":"第一次教人认光","choices":[{"title":"教他听灯芯","desc":"你让他闭上眼，把灯芯凑近，听它烧到几寸会响。","hint":"你把最后一根好芯给了他。","tone":"teach","outcome":"他闭着眼，睫毛抖，听见第三声时笑了，说像水开了。你教他用手背试灯罩的热，教他闻油里掺没掺水。到天黑，他能摸出哪盏灯快灭了。他走时把那根好芯攥在手心，攥得发亮。那晚你家的灯烧的是剪剩的短芯，蓝了三次。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"喜":2},"flag":"","thread":"一根攥得发亮的好灯芯"}},{"title":"牵他去巷口看灯","desc":"你牵着他的手，一盏一盏看过去，看别人的灯。","hint":"回来那段路，你歇了三回。","tone":"escort","outcome":"巷口卖汤饼的灯是漏光的纸罩，风一吹，影子在墙上跑。修鞋的灯罩是铁皮的，光只照手底下那一块。你告诉他，灯不一样，黑也不一样。走到巷尾你走不动了，坐在石墩上，他跑去叫人。回来时他提着一盏家里的灯，一路照着你，灯举得太高，照的是墙。","eff":{"bond":4,"health":-3,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"喜":1},"flag":"","thread":""}},{"title":"告诉他灯要买","desc":"你说光是用光时换的，家里点不起整夜，得学会在暗里睡。","hint":"他不哭了，阿蕨看了你很久。","tone":"honest","outcome":"小半点点头，问一刻是多长。你拿灯芯比给他看，这么长，一刻。他把手比成那么长，收进袖子里。阿蕨在门槛上坐下，说：他爹小时候也这么问过。孩子没再哭，夜里抱着一小截灯芯睡。阿蕨走时没回头，拐杖点地的声音一下一下，出了巷子。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":""}}]}]},"借寿渡":{"no":3,"name":"借寿渡","subtitle":"用我的日子，换你多留一天","through":"祖母用剩下的日子换你活下来。你身上有别人给的时间，一生都在决定要不要也把自己的一部分给出去。","cast":[{"id":"grandma","name":"阿婆","role":"烧契人","tag":"祖母"},{"id":"father","name":"渡生","role":"摆渡人","tag":"父"},{"id":"sibling","name":"纸鸢","role":"糊纸","tag":"妹"}],"main":[{"id":"jie_m01","act":"main","age":[0,0],"mode":"montage","title":"雾夜的一盏灯","opening":"你生在渡口的板屋里，那夜河上起雾，两盏灯只亮了一盏。父亲在对岸，船到河心就看不见水牌。阿婆把自己备下的寿衣拆了，改裹成一件小袄，袖子太长，掖了两折。她抱着你在岸边等船，雾贴在脸上，凉得像湿布。有个赶夜路的人从雾里过，问：抱的什么？阿婆说：抱的是三月初七，卯时。天亮前父亲才把船撑回来，灯罩是湿的。他看见你，没说话，先把船缆在桩上绕了三圈。","ask":"满月那夜你哭个不停，最后在谁怀里睡着？","days":30,"npc":"","memory":"雾夜的一盏灯","choices":[{"title":"抓住阿婆的袖口","desc":"阿婆把你抱到灰契台边，你攥着她的袖口睡沉。","hint":"契角上留下你的手印。","tone":"family","outcome":"你攥着她的袖子睡了一夜。袖里有一张折好的契纸，被汗浸软，角上留下一块淡黄的印。阿婆没换新的，往后每次烧契前，都先摸一下那个角。父亲夜里回来，站在门口看了一会儿，没进来抱你。第二天他出船，把缆绳多绕了一圈。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"惧":1},"flag":"","thread":""}},{"title":"让他去修船","desc":"父亲把你放回炕上，去换船底那块糟板，你哭到嗓子哑。","hint":"他天亮前就走了。","tone":"practical","outcome":"父亲把你放进阿婆怀里，蹲到船边拔钉子。那块板糟了半截，一拔就碎。你哭到嗓子哑，阿婆抱着你在岸边走，走到鸡叫。船修好了，他天亮前就出了船，回来时给你带了一小块麦芽糖，糖化了，粘在纸上。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"","thread":""}},{"title":"伸手去够那盏灯","desc":"你从阿婆怀里探身，把岸上那盏灯的灯罩碰歪。","hint":"手背上烫出一粒泡。","tone":"seek","outcome":"灯罩歪了，光扫到河心。雾里有人应了一声，是父亲在船上。他循着光把船撑回来，船头撞在桩上，闷响一声。你手背上烫出一粒泡，阿婆用唾沫抹了抹。那盏灯的罩子从此都是歪的，谁也不去正它。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":1,"惧":2},"flag":"","thread":""}}]},{"id":"jie_m02","act":"main","age":[3,3],"mode":"dialogue","title":"灰契台的火","opening":"三岁那年入秋，你烧起来。先是手脚凉，后来说胡话，说灶台上的灰在动。郎中来过，留下三包药，说看今晚。父亲一盆一盆地端河水，用布擦你的手心。阿婆翻柜，翻出那件小袄裹住你，袄襟上还有去年的米汤印。她的手在你额头上按了按，起身往渡口西头去了。灰契台的石头被火烤得发黑。你从门缝里看见一点火光，很小，像一粒豆。","ask":"火还在烧，你从床上爬起来做什么？","days":10,"npc":"grandma","memory":"烧到名字那一下","choices":[{"title":"扑过去拉她的手","desc":"你从门缝爬出去，抓住她烧契的手往后拽。","hint":"火舌舔了你的手背。","tone":"protect","outcome":"契烧歪了，三年只借成一半。你的手背留下一块亮疤，阿婆的袖子烧穿一个洞。往后每逢阴天你咳嗽，她就把手按在你手背上，一按就是半宿。那块疤一直在，像一小片没化开的蜡。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":""}},{"title":"喊爹去拦她","desc":"你哭喊起来，父亲赤脚冲出去抢那张契。","hint":"阿婆三天没跟他说话。","tone":"tell","outcome":"父亲一把把契从火里抓出来，火苗断在中间，纸少了半张。你的烧当夜就退了。阿婆蹲在地上捡那些纸角，捡了很久。她左手被火燎起一串泡，后来那只手一直不太听使唤。她三天没跟你父亲说话，第四天让他把船缆重新系了一遍。","eff":{"bond":-3,"health":1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":"阿婆的左手一直不利索"}},{"title":"闭上眼装睡","desc":"你缩回被里，听见她进门，赶紧把眼睛闭上。","hint":"你知道了她不让人知道的事。","tone":"secret","outcome":"她回来时身上有灰味。她以为你睡着，蹲下来摸了摸你的额头，从柜底摸出一个蓝布包，把东西塞进去，又推回最里头。蓝布包的一角露出半张空契，一个字也没写。你一直没问。那个角上的蓝线，你记了一辈子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":1},"flag":"saw_blank_contract","thread":""}}]},{"id":"jie_m03","act":"main","age":[7,7],"mode":"narration","title":"纸寿巷的秤","opening":"阿婆带你去纸寿巷买契纸。巷子窄，两边墙上晒着纸人，风一吹，纸人的袖子一起动。写寿人的桌子摆在巷口，桌上一杆小秤，秤钩上挂一只铜盘，盘底磨得发亮。一个瘦男人坐在板凳上，卷起袖子，把手按在黄纸上，人都叫他陈三。写寿人往秤盘里放纸钱，秤杆慢慢平了。陈三说：十二年。写寿人就在契上写：十二年。巷口站着个穿绸的陌生人，不进来，只伸出一只手。阿婆把你的头按低，说：看路。","ask":"那张契烧到一半，你要做什么？","days":20,"npc":"","memory":"纸寿巷的铜盘","choices":[{"title":"按住陈三的契","desc":"你挣开阿婆，跑过去把陈三的契按住，说别卖完。","hint":"契角多了一个小印。","tone":"protect","outcome":"火烫了你的手，写寿人把你拨开，契已经烧掉一个角。他看了看你，笑：小保人。他蘸了印泥，把你的拇指按在剩下的纸角上。阿婆冲过来扯你，脸白得像纸。回家她用皂角给你搓手，搓掉一层皮。多年后你在契库看见那张契，角上那个小印还在，模糊得像一粒灰。","eff":{"bond":-2,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"哀":2},"flag":"bearing_witness_mark","thread":"契角上有你的指印"}},{"title":"大声问他生日","desc":"你走到陈三面前，问：你卖了日子，谁给你过生日？","hint":"那笔买卖没做成。","tone":"ask","outcome":"穿绸的人皱了皱眉，把手收回去，走了。陈三蹲在墙根，说：腊月十九。阿婆把这道记在灶砖上。那年冬天他没熬过去。阿婆说不是你的事，可你总记得他那只磨穿的鞋，后跟露着灰白的袜子。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"你替一个卖寿的人记生日"}},{"title":"拉阿婆往回走","desc":"你拽着阿婆的衣角往回走，不敢再回头。","hint":"你记住了他磨穿的鞋跟。","tone":"escape","outcome":"阿婆由着你拽，走得很快。到巷口她停下来，回头看了一眼，说：看过了就记住。你只记得陈三的鞋。那天晚上你把脚缩在被子里，不敢伸出去。此后很多年，你见人先看鞋。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":1},"flag":"","thread":""}}]},{"id":"jie_m04","act":"main","age":[12,12],"mode":"dialogue","title":"三月初七","opening":"纸鸢蹲在门槛上糊纸鸢，举起来给你看，笑得让人心里发酸。阿婆开始忘事：忘锅，水烧干三回；忘关风门；忘了你爹的名字，管他叫撑船的。她从纸寿巷回来，站在门口看你，问：你是哪家的孩子？可到了三月初七，天没亮她就起了，煮一个鸡蛋，用红纸染了，放在你枕边。她说：三月初七，卯时，七斤二两，昨夜下雨，船上湿。你剥鸡蛋，红纸染了手指。她忽然又问：你是谁家的？","ask":"她又问你是谁家的，你怎么答？","days":30,"npc":"grandma","memory":"红纸染的鸡蛋","choices":[{"title":"说是你家的","desc":"你把剥好的鸡蛋掰一半塞给她，说：你家的。","hint":"那天下午你没去渡口。","tone":"family","outcome":"她接过鸡蛋，没吃，握在手心里。半天里她问了你七回，你答了七回。第七回她忽然说：我孙子叫……她卡住了，看着你的脸，说：算了。那天下午渡口招学徒，你没去，第二年才补上。她在门上贴了一张纸，你不认字她也让你念：阿婆的孙子。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"你晚了一年才进渡口"}},{"title":"翻出小袄给她看","desc":"你把那件小袄翻出来，把袖口掖的两折给她看。","hint":"她清醒了一个下午。","tone":"warm","outcome":"阿婆摸着针脚，说：这是我缝的，袖子长，掖两折。她一下想起来了，讲你出生那夜雾大，灯只亮一盏，你爹的船到天亮才回来。她讲了三遍，每一遍都一样。天黑后她又忘了。从那天起，小袄一直搭在她膝上，谁收她跟谁急。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"小袄再没离开她的膝盖"}},{"title":"告诉父亲她忘了","desc":"晚上你把阿婆认不出你的事，一五一十告诉父亲。","hint":"那晚门上多了一道插销。","tone":"tell","outcome":"父亲听完，望着河面站了一会儿，第二天在门外加了一道插销，夜里从外头插上。阿婆拍了一夜门，隔着门板叫你的名字，叫了七遍，每一遍都对。你在门里应她，应到嗓子哑。第三天她用菜刀把插销砍了，谁也没提这件事。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她砍掉了那道插销"}}]},{"id":"jie_m05","act":"main","age":[16,16],"mode":"dialogue","title":"第一杆秤","opening":"十六岁那年你到渡口做学徒。父亲不肯，说撑船的人脚不沾岸，命都在水上。阿婆说：他手稳。你于是去了。头三个月只烧水、扫地、递印泥。第一回独立称寿在九月，来的是个四十来岁的女人，要给病着的男人借两年。她把手在围裙上擦了三遍，才把寿纸放到铜盘里。秤杆翘起来，翘得很高。父亲站在门外，背对着你，看河面，说：翘是寿重，平了才是数。女人说：借两年。可秤上的数，只够一年半。","ask":"秤上差半年，你怎么落笔？","days":20,"npc":"father","memory":"秤杆翘了半寸","choices":[{"title":"照实写十八个月","desc":"你在契上写下十八个月，把笔搁正。","hint":"她走时在门槛上摔了一跤。","tone":"rule","outcome":"女人盯着那几个字看了很久，跪下给你磕了个头。你去扶，她已经起来了。她说：够了。出门时她在门槛上绊了一下，手撑在泥里。父亲说：你做得对。那晚你睡不着，听见河上有橹声，一直响到天亮。半年后她的男人还是走了，差整整六个月。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"差的那六个月"}},{"title":"把秤往下压半寸","desc":"你一只手扶住秤杆，慢慢往下压，压到平。","hint":"秤记住了这只手。","tone":"protect","outcome":"契上写了两年。女人拿着契出门，走几步又回来，把怀里两个鸡蛋放在桌上。你没要，她放下就跑。那男人多活了半年，开春还能下地。你的右手腕起了一道青，像被绳勒的，两年才退。父亲始终没问。此后你每次称寿，先看一眼自己的手腕。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"惧":3},"flag":"cheated_scale","thread":"手腕上的青痕两年才退"}},{"title":"放下秤去叫师傅","desc":"你把秤杆扶正，说：这契我称不了。","hint":"师傅来称，还是那个数。","tone":"dodge","outcome":"师傅来了，重新挂秤，称了三遍，还是十八个月。他把契写完，递给女人，说：这行手不能软。女人接过契，看了你一眼，那一眼你记了很多年。师傅走后，父亲说：秤不认人，可人得认秤。你没接话。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":""}}]},{"id":"jie_m06","act":"main","age":[22,22],"mode":"narration","title":"蓝布包","opening":"阿婆是秋天走的。头天傍晚她还坐在门口择菜，黄叶一堆，青叶一堆，分得比往常慢。半夜她叫你，说柜底有个蓝布包。你去拿，回来时她已经睡着了，手搭在床沿，掌心朝上。天亮她没醒。父亲从渡口回来，船没靠稳就跳上岸，鞋全湿了。他站在门口，脸朝着河面，说：请人来烧契。烧契人从她袖里摸出一张契，不是空的。上头用铅笔写着一行小字：余寿尽数转予长孙。","ask":"契念完了，谁来点这把火？","days":20,"npc":"","memory":"尽数转予长孙","choices":[{"title":"接火自己点","desc":"你接过火纸，先在引路纸船上写下自己的名字，再点契。","hint":"河上有人叫错你的名字。","tone":"carry","outcome":"名字写上去，纸船推进河心，没沉，顺水走了。契烧完，灰落进石缝里。那年冬天起，巷里人叫你叫不利索，有时叫成别人的名字。你自己也有过一回，站在门口想不起自己姓什么，想了半炷香。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":4},"flag":"gave_name_to_guide","thread":"你的名字留在河上"}},{"title":"把火递给纸鸢","desc":"你把火纸递到纸鸢手里，让她自己送阿婆这一程。","hint":"她烧完去收了阿婆的碗。","tone":"honest","outcome":"纸鸢接了火，手很稳。契烧到名字时停了一停，她等它自己卷，一点没催。烧完她把灰扫进河里，转身去收阿婆的碗。那只碗她收了很多年，一直放在自己柜里。此后她没再提过长孙两个字，也没问那行字是什么时候写的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":"她再没提过长孙两个字"}},{"title":"把契收进怀里","desc":"你从烧契人手里抽回契，折好塞进怀里，说等等。","hint":"你揣了三天才烧。","tone":"keep","outcome":"烧契人说：不烧，她的寿就散在河上，谁也接不住。父亲看着河面，说：随他。纸被体温焐软，边角起毛。第四天夜里你自己去灰契台烧了，没人看见。灰装进一个小布袋，压在柜底。那年冬天你总梦见门口有人在择菜。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"柜底有一小袋灰"}}]},{"id":"jie_m07","act":"main","age":[27,27],"mode":"dialogue","title":"改过的名字","opening":"纸鸢二十四岁那年，河对岸糊灯笼的人家来提亲，来了两回，第二回带一包桂花糖。亲事说得差不多，男方家托人问一句：姑娘名下还有多少寿？父亲不懂这些，来问你。你在契库翻了一夜，翻出一张旧契：借寿三年，保的是阿婆，出寿那一栏原本空着，后来填了纸鸢的名字。填字的笔迹你认得，她小时候学写字，横总是往上挑。那年她十九，阿婆病得起不来床。","ask":"这张旧契摊在灯下，你怎么办？","days":30,"npc":"sibling","memory":"她改过的名字","choices":[{"title":"划五年到她名下","desc":"你在契库另写一张转寿契，划五年给纸鸢。","hint":"她出嫁那天袖口响。","tone":"carry","outcome":"你按了印，把底档压在最底下。她的名字下面多了五年，够办一份体面的嫁妆。她出嫁那天穿红袄，袖口是旧纸糊的，走一步响一下。你没告诉她。三年后她生了个女儿，请你起名。你想了想，说：叫小满。她笑起来，说：这名字好，不欠谁的。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_years_to_sister","thread":"她不知道那五年是谁给的"}},{"title":"把旧契摊给她看","desc":"你把那张旧契摊在她面前，问她为什么改。","hint":"她第一次没笑。","tone":"honest","outcome":"她看了很久，笑起来，说：我那时候手抖，把寿字写成了受。你别管。她说完把契折好，塞回你手里，转身去熬浆糊。那天她没再笑。提亲的人第二天来问，她说：不嫁了。父亲在门口看河面，一句话没说。她后来一直没嫁。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"她后来一直没嫁"}},{"title":"夜里把旧契烧了","desc":"你趁夜把旧契从契库抽出来，在灰契台烧掉。","hint":"烧了档，她名下就干净了。","tone":"secret","outcome":"烧契人说：烧了档，人就真没名了。你说：她本来也不想要这个名。第二天你告诉提亲的人，纸鸢名下没有寿，也没有债。婚事成了。她嫁过去第三年，渡警来查旧档，问起一张缺号的契。你说不知道。那晚你在灰契台坐到天亮。","eff":{"bond":3,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"burned_sister_record","thread":"契库少了一张旧档"}}]},{"id":"jie_m08","act":"main","age":[35,35],"mode":"narration","title":"买寿的人","opening":"三十五岁那年，有个穿绸的人到渡口找你。他不坐船，站在岸上，鞋底没沾泥。他说家里老太太要过八十大寿，缺八年。他报了一个数，那个数够你把旧船换三条，够给纸鸢置一份嫁妆，够把阿婆的坟修成石头的。他把一沓阳楮压在秤盘上，秤杆一下沉到底。你看着那杆秤，秤钩还在轻轻晃。他说：我打听过，你身上有别人给的日子，多出来的，卖一点不亏。","ask":"他把秤压住等你回话，你怎么回？","days":15,"npc":"","memory":"秤盘一下沉到底","choices":[{"title":"把秤盘扫翻","desc":"你一把把秤盘扫翻，阳楮散在岸边的泥里。","hint":"那个数你记了一辈子。","tone":"refuse","outcome":"他没恼，蹲下去一张一张捡，捡完在袖子上擦了擦手，说：打扰了。他走时天快黑了，对岸的灯还没点。你记住了他报的数，不是整数，零头三文。后来有个冬天船漏了，你蹲在舱里算，那个数正好够换三条船，你算完，把橹摔在舱板上。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":2,"惧":1},"flag":"","thread":"你记住了那个价钱"}},{"title":"问他买给谁","desc":"你不接钱，问他这八年买给谁。","hint":"老太太到死不知道。","tone":"ask","outcome":"他说买给老太太，老太太自己不知道。你说：那你回去问问她愿不愿意。他愣了一下，说：她要是愿意，我就不来了。你把秤收进柜里，挂了锁。那个数你还是记住了，零头三文。那年冬天他家老太太没了，八十大寿没办。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":3,"怒":1},"flag":"","thread":"八十大寿没办"}},{"title":"说自己的日子","desc":"你告诉他，你这条命是三岁那年阿婆烧契换的。","hint":"渡警来翻过阿婆的柜子。","tone":"confess","outcome":"他听完，把阳楮收回去，说：那我不买了。你送他上船，他站在船尾朝你拱手。那个数你没忘，零头三文。半个月后渡警来查旧档，问起三岁那年的一张契。契早烧了，查不出，可你被记了一笔。那年冬天的渡牌没发给你。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"told_own_borrowed_life","thread":"你那年没领到渡牌"}}]},{"id":"jie_m09","act":"main","age":[50,50],"mode":"narration","title":"手很稳","opening":"五十岁这年，灰契台的老烧契人死了，钥匙交到你手里。你在渡口称了三十四年寿，烧契却是头一回。你记得他的手式：契纸对折，字朝外，火从下角起，烧到名字时停一停。来烧契的人有的不说话，有的蹲下去数灰。灰落进河里，河面不响。你的手一直很稳。这天来个老太太，六十八岁，穿洗白的蓝布褂，手里牵个五岁的孙子。契上写着六个字：余寿尽数转予长孙。","ask":"她把契推过来，你要怎么烧？","days":60,"npc":"","memory":"手稳得像别人的","choices":[{"title":"称一称，报实话","desc":"你把她的寿纸放上铜盘，称完把数报给她。","hint":"她说四十天够拆洗棉裤。","tone":"honest","outcome":"秤平了，是四十天。你报了数。她想了想，说：够把棉裤拆洗一遍。契照烧，火很稳。她走那天你不在。后来她孙子来渡口，说阿婆的棉裤拆洗过，晒在竹竿上，没来得及缝。竹竿还在那儿，风一大就响。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"棉裤没来得及缝"}},{"title":"从自己名下添十天","desc":"你在契尾添十天，从自己那张空契上划过去。","hint":"你的手指开始发麻。","tone":"carry","outcome":"你没告诉她。她多活了十天，棉裤拆洗、晒干、缝好了，针脚歪歪扭扭。那年冬天你右手两根指头发麻，摸秤星摸不准，只能凑到灯下看，看完再称一遍。老太太的孙子后来每年清明送一包桂花糖，你一次也没吃。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"gave_ten_days","thread":"秤星摸不准了"}},{"title":"把火递给孩子","desc":"你把火纸递给站在旁边的孩子，说：你来点。","hint":"孩子点了三次没点着。","tone":"distance","outcome":"孩子的手抖，火纸掉了两回。老太太弯腰捡起来，自己把契点着了。烧完她拍了拍孙子的手，说：行了，别怕。孩子没哭，一直看着火。你站在旁边，忽然想起自己三岁那年，从门缝里看见的那粒火。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}}]},{"id":"jie_m10","act":"main","age":[70,70],"mode":"narration","title":"抱孩子的人","opening":"七十岁这年，河面又起雾。渡口两盏灯，对岸那盏坏了，只剩岸上一盏。一个年轻人抱着孩子站在岸边等船，孩子裹得很紧，只露出一张脸。他问你：这船过不过河？你说：过。他上船坐在船尾，把孩子往怀里又紧了紧。孩子的脸烧得通红，呼吸很轻，像一只小兽。年轻人说：听说这渡口能买日子。你手里的橹停了一下，船在水上转了半圈。","ask":"他问能不能买日子，你怎么答？","days":20,"npc":"","memory":"裹得很紧的孩子","choices":[{"title":"写自己的八年","desc":"你取一张新契，写上自己的名字和八年，按上印。","hint":"你手背上起了块青斑。","tone":"protect","outcome":"契烧起来，火苗比你的手掌长。孩子当夜退了烧。年轻人跪下磕头，你把他拉起来，说：别记我的名字，记日子就行。那年冬天你开始怕冷，手背上起了一块青斑，按下去是凉的。开春他抱着孩子来，孩子会笑了，伸手抓你的橹。","eff":{"bond":5,"health":-4,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_own_years","thread":"孩子抓过你的橹"}},{"title":"教他自己写","desc":"你把小秤和印泥推到他面前，教他称，教他写。","hint":"他写的是自己的名字。","tone":"teach","outcome":"他学了半夜，称了三回，第三回手不抖了。他在契上写了自己的名字，按印时把印泥按出了格。孩子活了。他抱孩子下船时回头冲你笑，说：够了。十年后孩子来渡口坐船，已经比船桨高，不知道自己身上有谁的日子。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":2},"flag":"taught_father_trade","thread":"孩子不知道自己身上有谁的日子"}},{"title":"劝他别买","desc":"你告诉他，借来的日子要还双倍，还得是孩子还。","hint":"他记住了你说的每个字。","tone":"refuse","outcome":"年轻人抱着孩子下船，没回头。开春你听说孩子没了。第三年他来过一趟，站在岸上问你：那天你为什么不让我买？你说：我拦了。他说：你没拦。他走的时候，怀里空着，襁褓叠得方方正正。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":3},"flag":"","thread":"他说你没拦"}}]},{"id":"jie_m11","act":"main","age":[79,80],"mode":"narration","title":"门板上的日子","opening":"八十岁，你的记性也坏了。先忘船桨放哪，后来忘纸鸢嫁的是哪一家，再后来，你站在渡口，忘了自己为什么站在那儿。可你记得生日。你在门板上用炭写：渡生，腊月十一；纸鸢，五月初五；陈三，腊月十九。写到最后一个，你停了手——三月初七，卯时，那是你的。天黑前你把两盏灯都点上，对岸那盏是你新换的罩子。小袄搭在膝上，柜底蓝布包里还剩一张空契，是阿婆的，契角上有你婴儿时的手印。","ask":"这张空契，你要怎么处置？","days":360,"npc":"","memory":"三月初七，卯时","choices":[{"title":"称一称自己","desc":"你把小秤挂起来，把自己的寿纸放上铜盘。","hint":"秤杆翘着，你没让它平。","tone":"honest","outcome":"秤杆翘得很高，你没往上加，也没往下压。你把空契摊开，写上自己的名字，压在秤下，不烧。烧契人问你为什么，你说：这回我想知道，我到底欠了谁多少。她没再问，把秤擦了擦，挂回梁上。纸鸢看见门板上的数，拿沙子搓了半宿，搓得只剩几个生日。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"weighed_self","thread":"秤下压着你自己的契"}},{"title":"教孩子记日子","desc":"你叫来隔壁六岁的孩子，指着门板一个一个念。","hint":"他记住了三个。","tone":"teach","outcome":"孩子学得慢，把腊月十九念成腊月九。你说重来。教了七天，他记住三个。第八天他跑来问：三月初七是谁？你说：是我。他说：那我记着。他把这四个字念得很快，像背一首没听过的歌。你听见了，转身去添灶，柴塞了三次才塞进去。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":"他答应记着三月初七"}},{"title":"把空契送给他","desc":"你把空契折小，塞进孩子手里，说：拿去记生日。","hint":"那是阿婆留下的最后一张。","tone":"warm","outcome":"孩子拿着空契跑出去，纸被风吹得哗哗响。他问：这上头能写字？你说：能，写谁的生日都行。他跑了半条巷子又回来，说：我先写你的。你说：三月初七，卯时。他记不住，你就又说了一遍。风把纸吹起来，他追了很远，你站在门口看。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":2},"emotion":{"喜":2,"爱":4},"flag":"gave_blank_contract","thread":"空契到了孩子手里"}}]}],"side":[{"id":"jie_s01","act":"side","age":[6,6],"mode":"dialogue","title":"雾天不渡","opening":"那年你六岁，雾从河心往岸上爬，爬过水牌，把对岸那盏灯整个吃了。父亲把船缆又绕了一圈，说雾里看不见水牌，船出去就找不着回来的路。岸上站着个女人，怀里抱一个蓝布包袱，鞋帮湿透，站一会儿换一次脚。她说对岸捎话来，她娘昨夜就不认人了。她把包袱往上托了托，说：我会水。父亲看着河面，没接话。","ask":"雾里那盏灯，你要怎么用？","days":10,"npc":"father","memory":"没人过河的一天","choices":[{"title":"举灯站上船头","desc":"你把灯举到船头，父亲看你一眼，把橹推进水里。","hint":"手心的泡破了，落了疤。","tone":"protect","outcome":"船跟着灯光走，走得很慢。到河心，两盏灯只剩手里这一盏。女人上岸时天已经亮了，回头朝船上点了一下头。你的手心烫出一片白泡，破了，沾了河水，疼了半个月。父亲的船底蹭掉一道漆，他补了一冬。那盏灯的罩子从此更歪，谁也没去正它。","eff":{"bond":3,"health":-2,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"手心留了一块白疤"}},{"title":"抽掉跳板","desc":"你把跳板抽回岸上，说雾天不渡，转身进屋。","hint":"她没再求你第二遍。","tone":"rule","outcome":"女人在岸上站到天黑。中间她把包袱打开过一次，里头是一双新做的布鞋，底上纳着密密的针脚。黄昏时对岸撑来一只小划子捎信，说她娘卯时走了。她把鞋包好，朝你父亲点了点头，走了。第二天早上跳板还在你屋门口，谁也没去搬。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"跳板在门口放了一夜"}},{"title":"蹲下来陪她等","desc":"你搬个小凳放在她旁边，自己坐在门槛上，不催也不劝。","hint":"你误了那天的早饭。","tone":"wait","outcome":"她坐着，你坐着。雾散得很慢，先露出水牌，再露出对岸的灯。她跟你说话，说她娘会做一种甜糕，蒸的时候要盖三层布。说到第三层布，对岸的划子来了。她站起来，把包袱抱紧，鞋底在泥里陷了一下。你回家时锅里只剩锅巴，阿婆没问你去了哪儿。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"jie_s09","act":"side","age":[9,9],"mode":"narration","title":"两张一样的契","opening":"九岁那年秋后，渡口来个老汉，褂子是新的，浆得发硬，扣子扣错一颗。他从袖里摸出两张契纸，一样大小，一样折了四折，摊在灰契台上。他不认字。写寿人收了两斗米，给他两张，说一张烧给孙子，一张压箱底，可他分不清。灰契台石缝里嵌着上一场的纸灰，风一过，两张纸一齐响。梁上小秤垂着，铜盘不动，两盏灯还没点。你只认得一个“寿”字，是阿婆用炭写在门板上教的。","ask":"两张一样的契摊在灰上，你指哪一张？","days":15,"npc":"","memory":"两张一样的契","choices":[{"title":"牵他去纸寿巷","desc":"你把两张契都收进袖里，牵着他的袖子往纸寿巷走。","hint":"回来时天黑了，鞋少一只。","tone":"escort","outcome":"写寿人对着灯看半天，说一张是借，一张是还，指错要出人命。老汉要回两斗米，塞你半块饼。回来时你踩进沟里，鞋冲走一只，脚底划开一道口。阿婆用盐水给你洗，问你怎么这么晚，你说玩忘了。那半块饼你留了三天，硬得咬不动。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"","thread":"一只鞋冲进了河里"}},{"title":"说给他孙子听","desc":"你把两张契摊在老汉孙子面前，说烧错一张，你爷就没日子了。","hint":"那孩子把契撕了。","tone":"honest","outcome":"孩子把两张契一起抓过去撕成四半，扔在石台上。老汉打他一巴掌，打完自己愣住，蹲下去捡纸片，捡不起来的用指头刮。回家路上两人一前一后，谁也没说话。那个冬天老汉走了。孩子开春来过渡，看见你就把头低下去，直到上船才抬起来。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"他上船才抬起头"}},{"title":"指着寿字替他分","desc":"你只认得一个寿字，就指着有寿字那张，说这张留着。","hint":"烧错了，你还不知道。","tone":"gamble","outcome":"老汉信了，把另一张投进火里，火苗很旺。他把有寿字那张叠好塞进贴身衣兜，走时还回头朝你拱手。入冬他孙子来买纸，说他爷把日子给错了人，家里正闹。你站在秤边，手心里全是汗，那杆秤晃了很久才停。从此你认字，先认那个寿。","eff":{"bond":0,"health":-1,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"misread_two_contracts","thread":""}}]},{"id":"jie_s02","act":"side","age":[13,13],"mode":"dialogue","title":"第四排的纸人","opening":"纸寿巷的作坊在巷子最里头，门口晾着一排纸人，风一过，几十只袖子一起动。你替阿婆送浆糊去，纸鸢在里头帮着裁纸，手指上全是干了的糨糊，白花花一层。屋里有草纸和松香混着的味道，闻久了嘴发干。你等她裁完最后一刀，抬头看见架子上第四排有个小纸人，穿着件小袄，袖子掖了两折。你认得那件袄。纸鸢顺着你的眼睛看了一眼，把手里的裁刀放下了。","ask":"那件小袄穿在纸人身上，你问什么？","days":15,"npc":"sibling","memory":"第四排的纸人","choices":[{"title":"接着裁那叠纸","desc":"你把浆糊放下，蹲下去帮纸鸢裁完剩下的那叠纸。","hint":"你手上裂了一个月的口子。","tone":"help","outcome":"你裁了一个下午，纸边裁得比她还齐。往后一个月，你每天早上去作坊帮着晒纸人，一排一排翻面，手上裂开的口子沾了糨糊，火辣辣地疼。纸鸢当你不知道，阿婆也当你不知道。架子第四排那个小纸人，你每天晒到它的时候，都把它翻得慢一点。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"哀":3,"爱":3},"flag":"","thread":"你替全家守着这件事"}},{"title":"抱回家给阿婆","desc":"你把纸人从架子上取下来，抱在怀里，一路走回渡口。","hint":"纸鸢一个月没跟你说话。","tone":"honest","outcome":"阿婆看见纸人，先摸了摸那两折袖子，问：这是谁家的孩子。你说：是我。她哦了一声，把纸人接过去放在膝上，一晚上没说话。夜里你起来喝水，看见她用手掌把纸人的脸一遍一遍抹平。第二天纸人不见了，架子上空出一块。纸鸢问你，你说不知道。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"架子上空出一块"}},{"title":"把它的脸按平","desc":"你把纸人从架子上拿下来，用手掌把那张脸按平。","hint":"老板娘打了你三下戒尺。","tone":"defy","outcome":"纸糊的脸被按塌了，浆糊从边上挤出来，粘在手心里。老板娘从里屋出来，用戒尺打了你手心三下，说替身没了脸，水就不认人。纸鸢把纸人抱回去，重新糊了一张脸，画得很像你，只是眉毛歪了一点。那年冬天起你下水就抽筋，过河要先报三遍名字。","eff":{"bond":1,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":1},"flag":"faceless_substitute","thread":"你过河要报三遍名字"}}]},{"id":"jie_s10","act":"side","age":[17,17],"mode":"narration","title":"混在一处的灰","opening":"十七岁那年清明前，灰契台一天烧七场。午后起风，两家的灰被卷到石台同一个凹处，分不出谁是谁。一个男人蹲下去，用竹片把灰往布袋里拨，连石缝里的都用指头抠出来。他说他儿子怕黑，要带回去放在床头。另一个是老太太，手里的布袋还空着，站在旁边看了一会儿，说：那我要哪一堆。小秤还挂在梁上，铜盘被风吹得轻轻碰秤座。","ask":"两家混在一处的灰，你怎么分？","days":10,"npc":"","memory":"混在一处的灰","choices":[{"title":"把话说清楚","desc":"你把两家的布袋都放在石台上，说灰混了，分不出来。","hint":"老太太回去躺了三天。","tone":"honest","outcome":"男人把布袋口捏紧，问：那我这三天对着谁说话。没人答他。老太太把空袋塞进袖子，说她老伴生前就不爱跟人挤。男人把灰带走，走到河心撒了一半。老太太回家躺了三天，起来把牌位擦了一遍。往后每年清明两家在渡口碰见，都点一下头，谁也不提那天。","eff":{"bond":0,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"把错认下来","desc":"你说灰是你扫混的，赔一张新契，当夜重烧一场。","hint":"罚了你三个月工钱。","tone":"carry","outcome":"师傅扣了你三个月工钱，让你在灰契台跪了半炷香。夜里你重烧一张契，写上那孩子的名字和生辰，烧成新灰装进男人的布袋。老太太那边，你把台上剩的灰扫一半给她，说就是原来那堆。两个人都走了，谁也不知道拿的是谁的。你膝盖疼了半个月，阴天更疼。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":3},"flag":"took_blame_for_ashes","thread":"膝盖阴天就疼"}},{"title":"一人分一半","desc":"你把灰扫成两堆，用秤分了，一人一袋。","hint":"谁也不知道拿的是谁。","tone":"practical","outcome":"你用小秤分了，两袋一样重。男人把布袋揣进怀里，走得很快；老太太把袋子抱在胸前，走得很慢，像抱着一个睡着的人。谁也没问。多年以后你在渡口碰见那男人，他跟你打招呼，说他儿子托梦，说黑。你没接话，低头把船缆又绕了一圈。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"","thread":"他说他儿子托梦说黑"}}]},{"id":"jie_s03","act":"side","age":[19,19],"mode":"narration","title":"卖给仇人的寿","opening":"那女人是傍晚来的，穿一件灰布褂子，袖口磨得发亮。她手里捏着一张折了四折的契，边角起了毛。她说要出寿，全出。你把小秤挂上梁，问她买家是谁。她把契推过来，名字那一栏朝里折着，说：你别念我的名字。秤盘里放上她的寿纸，秤杆一路沉下去，沉到底，铜盘磕在秤座上，响了一声。父亲在门口看了一眼，没进来。","ask":"她让你别念名字，你念不念？","days":15,"npc":"","memory":"折了四折的契","choices":[{"title":"照契念出名字","desc":"你把契展开，一字一字念出来，念到名字时抬了头。","hint":"买家的儿子站了出来。","tone":"rule","outcome":"买家的儿子在人群里，听完往前走了一步，说这寿他们家不要。他把定金从袖子里掏出来放在秤盘上，转身就走。女人把契捡起来，按原来的折痕折好，说：你念得对。她走的时候脚步很稳，秤还挂在梁上，铜盘晃了很久才停。","eff":{"bond":-1,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":"买家的儿子退了定金"}},{"title":"把名字折进去烧","desc":"你把名字那一角折向里，火从下角点起，没念出声。","hint":"你按印时按出了格。","tone":"secret","outcome":"火烧到折角时停了一下，又往上走。契成灰，名字没了。女人看着火，肩膀松下来，像卸下一副担子。三天后对岸传来她没了的消息。那个人还在喘气，家里人说是寿买对了。你袖口烧了个洞，一直没补，后来每次烧契都先把角折一折。","eff":{"bond":2,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"burned_nameless_contract","thread":"袖口上的洞没补"}},{"title":"把秤摘下来","desc":"你把小秤从梁上摘下，说这契不称，让她回去。","hint":"她去了纸寿巷。","tone":"refuse","outcome":"她看了你一会儿，把契收进袖子，说：你们都一样。第二天你听说纸寿巷有个写寿人接了这桩，抽了两成。契是在巷口烧的，念没念名字，没人告诉你。那阵子你称寿总要多称一遍，称完把秤擦得发亮，擦到铜盘上照得出人影。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"你不知道那名字念没念"}}]},{"id":"jie_s11","act":"side","age":[24,24],"mode":"dialogue","title":"结冰的那年","opening":"二十四岁那年腊月，河面结冰，从这岸结到对岸，冰上落一层薄雪，看不出哪儿厚哪儿薄。船冻在桩边，橹冻在船上。父亲每天早上提一壶热水浇缆绳，浇开一截，又冻上一截。两盏灯只点着一盏，火苗贴着灯罩。第七天夜里，对岸有人举着火把喊船，喊了一夜。天亮才看清是个男人，说他娘躺在屋里喘不上气，要请这边的郎中过去。父亲蹲在岸边，用桨柄敲了敲冰，冰响了一声，很闷。","ask":"冰上那条没人走过的路，你走不走？","days":20,"npc":"father","memory":"冰封的第七天","choices":[{"title":"先踩一趟冰","desc":"你在腰上拴绳，让父亲拽着，一步一步往对岸挪。","hint":"两个脚趾后来没知觉。","tone":"brave","outcome":"走到河心，冰在脚底下叫了一声，你整个人陷下去，绳子勒进腰里。父亲把你拖上来，你怀里还护着郎中的药包，纸湿了一半。郎中是第二天绕上游的桥过来的，人救回来了。你右脚两个脚趾从此没知觉，走路有点跛。开春冰化，你在桩上刻了一道，刻得很深。","eff":{"bond":2,"health":-4,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"walked_on_ice","thread":"右脚两个脚趾没知觉"}},{"title":"把船锁上","desc":"你把跳板抽了，隔河告诉他冰在走水，谁也不许下。","hint":"他听了你的话。","tone":"rule","outcome":"他隔着河喊了半宿，后来不喊了。天亮时那边的火把灭了。你后来知道，他娘是后半夜走的，走的时候他守在床边。开春他来渡口，给你作了个揖，说：那天你说得对。你说不出话，替他把船钱免了。此后每年腊月，你都要在岸边多站一会儿，听冰响。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"每年腊月你在岸边多站一会儿"}},{"title":"带人撒灰开路","desc":"你把灰契台攒的灰一筐筐抬到冰上，撒出一条道。","hint":"契库的旧档全湿了。","tone":"niche","outcome":"灰撒上去，冰不滑了。两岸的男人排成一队，一个扶一个，把郎中挪了过去。那天夜里没有人掉下去。可灰契台攒了三年的灰全撒完了，契库底档被雪水浸透，开春查出一摞糊账。渡警来问，你认了，记了一过，那年没领到渡牌。你的手被筐绳勒出四道血口。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"jie_s04","act":"side","age":[26,26],"mode":"narration","title":"退回去的契","opening":"那孩子是自己来的，七八岁，脚上一只鞋是湿的，身上那件小袄袖子太长，掖了两折。他把一张契摊在灰契台上，契角烧掉一点，字歪歪扭扭。他说：我奶奶把日子给我了，我现在好了，能不能退回去。他说话时一直盯着你的手，好像你会变戏法。灰契台上还留着上一场火的灰，风一吹，露出底下的石纹。你蹲下来，跟他一般高。","ask":"这张要退的契，你怎么答他？","days":20,"npc":"","memory":"一张要退的契","choices":[{"title":"指给他看契上的字","desc":"你蹲着，把契上的字一个一个指给他，说日子已经在他身上。","hint":"他把契撕成两半。","tone":"honest","outcome":"他听完，把契捏紧，捏了一会儿，撕成两半，扔进河里。纸在水上散开，一会儿就没了。他没哭，问你：那她还能活多久。你说不知道。他走的时候把湿鞋在门槛上蹭了蹭，蹭干净才出去。后来他再没来过渡口。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"他再没来过渡口"}},{"title":"烧一张空的退契","desc":"你另取一张空契，写上孩子的名字，当着他的面烧了。","hint":"火里垫的是你自己的日子。","tone":"warm","outcome":"火苗立起来，比纸高。他盯着火看，嘴唇跟着动，念的是他奶奶的名字。烧完他把灰捧起来装进衣兜，说要带回去给她看。你从自己名下划了四十天，谁也没告诉。那年冬天你怕冷，睡觉要盖两层被。开春他跑来告诉你，奶奶能下地了。你说好。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"burned_false_return","thread":"他兜里装着那捧灰"}},{"title":"带他去见奶奶","desc":"你牵着他过河，把契塞回他手里，让他自己去问。","hint":"老太太在里头骂了你一句。","tone":"escort","outcome":"老太太躺在里屋，听孙子问完，半天没说话。后来她伸手把契拿过去，压在枕头底下，说：不退。孩子问为什么。她说：退了，我就白疼你了。孩子没听懂，站在床边抠被角。出门时老太太在里头说：你带他来做什么。你答不上来，船撑到河心才想出一句话，也没说出口。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":3},"flag":"","thread":"她压在枕头下的契"}}]},{"id":"jie_s12","act":"side","age":[31,31],"mode":"narration","title":"两个人的数","opening":"三十一岁春天，来了一对夫妻，都不到四十。女人先说，想称一称两个人的日子，不借也不卖，只想知道谁先走，好把话说完。男人补一句：也好安排。你把小秤挂上梁，铜盘擦了一遍。女人先称，秤杆翘得很高，你报：九年零四个月。男人把寿纸放上去，秤杆几乎没动。你报：两年半。屋里静下来，窗外有鸭子叫。","ask":"他们问这两年半该怎么过，你怎么说？","days":30,"npc":"","memory":"秤上的两年半","choices":[{"title":"该怎么过就怎么过","desc":"你把秤收好，说日子不是省出来的，该干什么干什么。","hint":"他把想做的事排成了一张纸。","tone":"honest","outcome":"男人回家把想做的事列在纸上，一件一件划：修屋顶、补墙、把他娘的坟迁到朝阳坡上、去看一回海。最后一件没划掉。两年半头上他死在梯子上，手里还捏着瓦刀。女人把那页纸压在箱底，活了很久，纸黄了字还认得。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"纸上最后一件没划掉"}},{"title":"关半天渡口陪坐","desc":"你把船缆系死，说今天不摆了，三个人坐到天黑。","hint":"渡牌扣了三个月。","tone":"stay","outcome":"三个人坐在灰契台边，女人说起成亲那天下雨，男人说起第一次撑船把桨掉进河里。说到天黑，谁也没提那两年半。第二天有人告到阳楮司，渡牌扣三个月。那三个月你天天去他家修屋顶，修到一半，男人说：够了，剩下的我自己来。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"屋顶修到一半"}},{"title":"少报他两年","desc":"你把他的数报成四年半，说秤老了，看不太准。","hint":"他多做了两年白工。","tone":"secret","outcome":"他松了口气，说四年半够把孙子送进学堂。他没日没夜地干，第二年冬天就倒了。女人来还秤时说：你那天报的是四年半。你说：秤老了。她把秤放在柜台上，说：他后来自己又去纸寿巷称过一回。走时把门带上，很轻。","eff":{"bond":-1,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":4},"flag":"underreported_years","thread":""}}]},{"id":"jie_s05","act":"side","age":[38,38],"mode":"narration","title":"纸船上的名字","opening":"那个人是从上游漂下来的，卡在渡口的木桩上，衣裳泡得发白。你把他拖上岸，从他袖子里抖出一张契，出寿人那一栏写着自度两个字，受寿人空着。你把他放上小秤，秤盘一动不动，像挂着一块石头。他左脚少一个脚趾，断口很旧。父亲站在旁边说：无名的人，水会慢慢忘掉他。天快黑了，引路的纸船还空着，船上要写一个名字。","ask":"纸船上那个名字，你写谁？","days":15,"npc":"","memory":"秤盘一动不动","choices":[{"title":"写上自己的名字","desc":"你把自己名字写在纸船上，推船下水，看着它走。","hint":"右肩一到下雨就发沉。","tone":"protect","outcome":"纸船没沉，顺水走了。你回家换了衣裳，躺下就梦见一件湿衣裳搭在椅背上，滴了一夜水。往后每逢下雨，你右肩就发沉，像压着一只手。半年后有个女人来渡口打听一个男人，说他的船翻在上游。你听她说完，说没见过。她走后你在灰契台坐到天黑。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"哀":3},"flag":"gave_name_to_stranger","thread":"一到雨天右肩就沉"}},{"title":"给他编一个名字","desc":"你在纸船上写了一个编来的名字，一笔一笔写得很慢。","hint":"他女人叫的不是这个名字。","tone":"gamble","outcome":"名字写完，你念了一遍，声音在雾里散开。纸船走了。开春他女人找来，拿着一双鞋，说他左脚少一个脚趾。你带她去河心，指了那片水。她蹲在船头叫了一个名字，不是纸船上的那个。水面上什么也没有。她走时说：谢你给他一个名字。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"她叫的名字不对"}},{"title":"让纸船空着走","desc":"你没写名字，把空纸船推进水里，站着看它散开。","hint":"到冬天你记不清他的脸。","tone":"rule","outcome":"空船在水上转了两圈，慢慢散了，纸片贴着水面往下游走。父亲说：这行就是这样，无名的归河。你把他那件湿衣裳晒在桩上，晒了三天，第四天不见了，不知道是风刮走还是有人收的。入冬后你想不起他的脸，只记得那只少了一个脚趾的左脚。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}}]},{"id":"jie_s13","act":"side","age":[43,43],"mode":"narration","title":"给狗一个生日","opening":"四十三岁那年夏天，隔壁的孩子抱着一条黄狗来渡口。狗已经硬了，耳朵上有个豁口，是小时候被猪咬的。孩子把狗放在灰契台上，从怀里摸出一张契纸，纸被他攥得发软。他说：它没有名字，也没有生日，人家说没名字的过不了河。他说要把自己的生日给它，让你写。他把手指头伸进嘴里咬了一下，挤出一滴血，按在契角上。小袄搭在椅背上，是你小时候那件。","ask":"这张要写生日的契，你落不落笔？","days":15,"npc":"","memory":"给狗一个生日","choices":[{"title":"写自己的生辰","desc":"你在纸上写下三月初七，卯时，替他把这一笔担下来。","hint":"从这天起，生日不算你的。","tone":"carry","outcome":"火苗立起来，比纸高。孩子蹲下去看灰，问上头写的是不是他的生日。你说是。他把灰装进布袋，挂在狗脖子上，埋在后坡。那天以后，每年三月初七你都在门槛外放一碗饭。孩子长大后问过一次，你说给一个老朋友。他哦了一声，没再问。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"gave_birthday_to_dog","thread":"门槛外那碗饭"}},{"title":"照规矩办","desc":"你说人不能把生日给畜生，狗没名字，只能空船走。","hint":"他学会狗叫。","tone":"rule","outcome":"孩子不听，抱着狗在灰契台上坐到天黑。你把空纸船推进水里，船转了两圈，散了。他回家后有一阵子不说话，蹲在墙根学狗叫，叫得院里别的狗都应。他娘来跟你说，让你别往心里去。第二年开春，你在后坡看见一个新堆的土包，上面插着两根树枝。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"后坡上的两根树枝"}},{"title":"教它一个名字","desc":"你铺一张新契纸，教他一笔一笔写：豁耳。","hint":"他写了十七遍才写正。","tone":"teach","outcome":"他写了十七遍，把豁字写得像个歪嘴。写完你让他自己念，他念得很响，念完把纸烧了。灰落进水里，没散。他说：它记住了。你说：你记住就行。那年冬天他常来渡口，蹲在秤边看你称寿，看了一年。他给狗起的那个名字，后来写在了他自己的门板上。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"喜":1},"flag":"","thread":""}}]},{"id":"jie_s06","act":"side","age":[47,47],"mode":"narration","title":"磨掉一半的号","opening":"回名洲的契库在半坡上，屋里常年一股霉味，抽屉一格一格编着号。来的是个五十来岁的男人，穿洗白的短褂，手里捏一块木牌，牌上的号磨得只剩一半。他说要赎名字。你把抽屉拉出来，里头的契压了二十年，纸都粘在一起，揭开一张要哈一口气。他站在门口不进来，说：我不记得我叫什么了，人家都叫我老陈家的。你问：那你姓什么。他搓着木牌，搓下一层木屑，说：这个也说不准。","ask":"他要赎的这张契，你怎么算？","days":20,"npc":"","memory":"磨掉一半的号","choices":[{"title":"按规矩收足","desc":"你把秤放平，报出他还差多少，让他自己选。","hint":"他选了明天。","tone":"collect","outcome":"他听完，把手伸进秤盘，说这些全给你。你称了，一年零四十天。契烧了，名字念出来时他跟着念，念错一个字，又念一遍。第二天早上他没起来。来收尸的人问他叫什么，你说了一个名字，那人写在木牌上，写完吹了吹墨。木牌是新挂的。","eff":{"bond":2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"新木牌上的墨"}},{"title":"替他补上差的","desc":"你在契尾添上自己的日子，把秤压平，不告诉他。","hint":"你的手凉了一冬。","tone":"carry","outcome":"名字还给他了。他捧着契走出门，走几步又回来，问：这上头写的真是我。你说是。他把契贴在胸口，笑了一下，牙是黄的。那年秋天他还来渡口坐过半天，跟人说他有名字了。入冬前他走了，走得有名有姓。你那双手凉了一冬，第二年开春才回暖。","eff":{"bond":4,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":4},"flag":"paid_for_name","thread":"手凉了一冬"}},{"title":"说这一格空了","desc":"你把抽屉推回去，说档找不着，让他下个月再来。","hint":"他来了四回。","tone":"hide","outcome":"他每月来一回，站在门口，不催。第三回他带了两个煮鸡蛋放在柜台上，说路上捡的。第四回他走不动，孙子搀他进门，说：我记起来了，我叫陈守田。说完他自己愣了一下，笑了。你说：那就不用赎了。他说：那也得赎，赎了才算还清。你把抽屉拉开，这回没关上。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"柜台上两个煮鸡蛋"}}]},{"id":"jie_s07","act":"side","age":[55,55],"mode":"narration","title":"一张契两个人","opening":"那对老夫妻是天黑前来的，两个人搀着，走得一样慢。老头耳朵还灵，老太太耳背，他凑到她耳边说话，声音大得整条岸都听见：你先按。老太太摇头。他们把一张契纸摊在灰契台上，纸是新的，边角压得很平，在箱底放了些年。写寿人说一张契只能写一个名字。老头说他还有六年，她还有两年，说：写她的名字。老太太说不要，说他会做饭吗，锅都烧穿三个。两个人说到两盏灯都点上，谁也没按手印。","ask":"一张契写一个人，你写谁？","days":15,"npc":"","memory":"谁也没按手印","choices":[{"title":"收下老头的寿","desc":"你把老头的寿纸放上秤，秤平了，写老太太的名字。","hint":"她骂了他五年。","tone":"rule","outcome":"老头按了印，按得很重，印泥出了格。老太太在旁边拉他的袖子，没拉住。契烧完，两个人搀着回去了。老头第二年开春走的。老太太又活了五年，五年里每天骂他一句，骂完给他留一碗饭，搁在灵位前，第二天早上再端走。第五年她走时手里捏着那张契的角。","eff":{"bond":2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"","thread":"她捏着契角走了"}},{"title":"把契收起来","desc":"你把契折好压在秤下，说回去商量清楚再来。","hint":"那年冬天老头先走了。","tone":"dodge","outcome":"他们把契留下，搀着回去了，一路上还在争。入冬老头病倒，没熬到腊月。开春老太太一个人来渡口，站在岸上问：那天你要是把契烧了，他是不是还能多活两年。你说不知道。她说：我也不知道，我就是想问问。她没上船，沿河岸走回去，走得比来时慢。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她问的那句话"}},{"title":"添上自己的日子","desc":"你在契尾添上自己的两年，写下两个人的名字。","hint":"老头从灰里拨出你的名字。","tone":"carry","outcome":"火苗分成两股往上走。老头蹲下去看灰，从灰里拨出你的名字，拨了半天，说：这不行。你说烧都烧了。往后两年两个人都能下地，老头把渡口的台阶修了，一块一块垫平。第三年秋天他们前后脚走的，差三天。此后每年清明，你门口多一双布鞋，鞋底纳得密。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":1,"爱":4,"哀":3},"flag":"gave_years_to_couple","thread":"清明门口那双布鞋"}}]},{"id":"jie_s14","act":"side","age":[58,58],"mode":"dialogue","title":"出嫁前一夜","opening":"五十八岁秋，纸鸢要出门了。对岸修钟的老先生托媒人来过三回，第三回带来一对修好的座钟，走得很齐。头天夜里她来渡口，穿改过的红袄，袖口是旧纸糊的，走一步响一下。她坐在门槛上，红布包放在膝上，半天没打开。椅背上搭着你小时候那件小袄，她进门时伸手摸了一下袖口。两盏灯都点着，河上有风。她说：哥，我明天就姓别人的姓了。她笑了一下，说：我二十岁那年，还以为自己活不到二十。","ask":"红布包放在膝上，你伸手做什么？","days":10,"npc":"sibling","memory":"红布包里的日子","choices":[{"title":"划掉她的名字","desc":"你取出家契，当着她的面，把她的名字划了一道。","hint":"她笑着看你划完。","tone":"rule","outcome":"笔尖在纸上顿了一下，划出一道黑。她一直笑着看，划完说：那我明天就不算这家的人了。她把红布包打开，里头是阿婆那只碗，碗口磕了一个豁。她把碗放在桌上，说：这个留给你。走的时候她没有回头，红袄的袖口一路响到岸上。那只碗你后来用它喝水，喝了很多年。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"阿婆那只豁口碗"}},{"title":"给她压箱的日子","desc":"你另写一张契，从自己名下划五年，塞进她的箱底。","hint":"她到死不知是谁给的。","tone":"carry","outcome":"你写到后半夜，火苗在灯罩里一跳一跳。第二天她的箱子上船，是你亲手抬的，箱底压着那张契，谁也没说。她嫁过去第七年，男人病了一场，她把那张契拿出来用，用完烧了，说不知是哪个亲人留的。那五年从你身上走的，你冬天怕冷，手背上起了一块青。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"gave_years_to_sister_again","thread":""}},{"title":"陪她坐到天亮","desc":"你把西屋的炕烧上，什么也不问，给她倒一碗热水。","hint":"鸡叫时她走了。","tone":"stay","outcome":"两个人坐在门槛上，谁也没提明天。她说起小时候糊纸人，浆糊抹多了，纸人的脸塌了；说起阿婆记得每个人的生日，唯独忘了自己。鸡叫头遍她站起来，把红布包塞给你，说：门板上那些日子，我抄了一份。她走了。你打开，最后一行是三月初七，字比别的都小。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"","thread":"红布包里那张纸"}}]},{"id":"jie_s15","act":"side","age":[74,74],"mode":"narration","title":"疼不疼","opening":"七十四岁这年，渡口的活儿多半交给别人，你只在灰契台边坐着看火。来的是个姑娘，十六七岁，从纸寿巷走来，鞋上全是土。她手里捏着一张写好的契，只差一个手印。她说她娘咳了半年，郎中说熬不过冬，写寿人说她名下有九年，可出六年。她把契摊在你面前，问：借寿到底疼不疼。灰契台上没有火，风把契角掀起来又放下。","ask":"她问借寿到底疼不疼，你怎么答她？","days":20,"npc":"","memory":"借寿到底疼不疼","choices":[{"title":"说实话，疼","desc":"你告诉她疼在后头：每回有人叫你名字，都要算一算还剩几年。","hint":"她还是按了手印。","tone":"honest","outcome":"她听完撸起袖子，露出手腕一道旧疤，说：那我受得住。她按了印，印泥按出了格。契烧起来，火苗很短。她娘多活一冬，开春还是走了。姑娘嫁到上游，每年回来一趟，站在灰契台边不烧契，只站一会儿。你每回都陪她站，谁也不说话。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"","thread":""}},{"title":"说声不疼，替她烧","desc":"你说不疼，接过她的契，划掉她的名字，添上自己的六年。","hint":"你的手再拿不稳筷子。","tone":"carry","outcome":"你趁她不注意，把出寿那一栏改成自己的名字，按下印。火苗立起来，比纸高，她伸手去够，被你挡回去。她娘多活两年，看见她出嫁，也看见外孙。姑娘一直以为契是她自己烧的，逢人就说渡口的老先生心好。你的手从那年起拿不稳筷子，夹菜要夹两回。","eff":{"bond":5,"health":-4,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":4,"哀":3},"flag":"took_girls_six_years","thread":"筷子夹两回"}},{"title":"让她坐一夜","desc":"你不答，点一盏小灯，让她坐在台边看别人烧契。","hint":"天亮她把契带回去了。","tone":"wait","outcome":"那一夜来三个人：一个给儿子烧，一个给仇人烧，一个给自己烧。姑娘没说话，看到第三场，把手放在火边烤了烤。天亮她把契折回原样揣进袖子，说：我知道了。她没按印。她娘那年冬天走了。后来每年清明她都来坐一会儿，说不后悔。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"每年清明她来坐一会儿"}}]},{"id":"jie_s08","act":"side","age":[78,78],"mode":"narration","title":"秤盘里的纸片","opening":"七十八岁这年冬天，你把小秤挂回门框上，取一张空白契纸放在铜盘里。秤杆翘起来，翘得很高。你撕了一些小纸片，一片算一天，一天一天往盘里加，加到秤杆平了，就不再加。你把纸片取下来数，数了三遍，每一遍都一样。屋里很静，灶上的水响了一声。小袄搭在椅背上，袖口那两折早磨薄了。你把纸片拢成一叠，放在膝上，窗外河面白蒙蒙的。","ask":"这一叠纸片，你打算怎么办？","days":30,"npc":"","memory":"数了三遍的日子","choices":[{"title":"把秤收进柜里","desc":"你把纸片和小秤一起收进柜底，第二天照常去渡口。","hint":"谁也不知道你数过。","tone":"steady","outcome":"第二天你照常去渡口，把船缆绕三圈，把两盏灯都点上。纸鸢来看你，问你怎么瘦了，你说冬天都这样。那叠纸片压在柜底，和一小袋灰放在一起。后来你忘了自己数过几遍，只记得秤杆平的那一下，铜盘轻轻碰了碰秤座。日子照旧过，最后一天也没人知道是第几天。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":"柜底那叠纸片"}},{"title":"叫纸鸢一起数","desc":"你把纸鸢叫来，把纸片摊在桌上，让她再数一遍。","hint":"她数出不一样的数。","tone":"honest","outcome":"纸鸢数了两遍，数出的数比你的多。她说你漏了，把纸片重新码成一摞，码得很齐。她当天就搬回来住，把西屋的炕烧上，夜里起来两回看你。她的男人来劝过三回，她没回去。开春她的女儿也搬来了，三个人挤在板屋里。那叠纸片搁在窗台上，谁也没再数。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"told_sister_count","thread":"纸鸢搬回来住了"}},{"title":"把多的压在灯下","desc":"你把纸片分出一半，写成一张无名契，压在灯座底下。","hint":"灯座底下后来空了。","tone":"carry","outcome":"你把纸片分成两半，一半折进一张无名契，写完不落名字，压在渡口那盏灯的灯座底下。谁需要谁拿，谁拿谁就多活几天。那年冬天你弱得快，走两步要歇一歇。开春灯座底下的契不见了，灰也没有。你没问是谁拿的。到死你也不知道那几天落到了谁身上。","eff":{"bond":3,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"left_unnamed_contract","thread":"灯座底下空了"}}]}]},"钟葬群岛":{"no":4,"name":"钟葬群岛","subtitle":"替死人敲钟的人，替活人记住","through":"每沉一口钟，全岛就忘掉一个人。你做了守钟人，替别人记住他们忘掉的名字。","cast":[{"id":"father","name":"铜九","role":"守钟人","tag":"父"},{"id":"mother","name":"海娥","role":"织网","tag":"母"},{"id":"sibling","name":"小螺","role":"捞钟人","tag":"妹"}],"main":[{"id":"zhong_m01","act":"main","age":[0,0],"mode":"montage","title":"第三口钟","opening":"凌晨，海面很平。塔上的钟自己响了一声，不脆，像有人在水底敲空碗。父亲放下碗，说：又沉了一口。那天沉的是第三口钟。母亲在草席上生你，接生婆剪脐带时，钟声还没散，窗缝里灌进来一股海腥味。屋里的人忽然都不说话了——他们同时忘了一个名字。父亲把钟谱摊在膝上，笔尖悬着，找不到该写的地方。你在这时候哭出声，很响。","ask":"满月那晚，父亲摊开钟谱，你伸手抓什么？","days":30,"npc":"","memory":"第三口钟沉了","choices":[{"title":"攥住钟锤柄","desc":"你把父亲的钟锤抱在怀里，木柄上全是他的汗味。","hint":"母亲从此不提船钱。","tone":"carry","outcome":"父亲把钟锤往你手里送了送，说：沉，是块守钟的料。当晚他把你的名字写进钟谱的守钟人一栏，墨还没干就合上了。母亲在灶边织网，梭子来回，没抬头。那之后她再没提过攒船钱的事，罐子却一直放在织机底下，没动过。","eff":{"bond":4,"health":0,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"named_as_keeper","thread":"母亲的船钱罐还在织机下"}},{"title":"抓住那截衣角","desc":"你抓住母亲袖口一截烧焦的布，掰不开。","hint":"布上有奶味和烟味。","tone":"keep","outcome":"母亲的手停住。她把那截布从你手里抽出来，看了看，又塞回你的襁褓。那晚她没睡，在门口坐到天亮，海边烧过一堆小火，剩半截衣角埋在灰里。你从小枕着那块布，布上有奶味和烟味，钟一响就醒。她每年烧衣的时候，会往你这边看一眼。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":2},"flag":"","thread":"枕下的半截衣角"}},{"title":"朝海哭到天亮","desc":"谁抱都哭，只有抱到门口朝海才停。","hint":"父亲把钟谱合上了。","tone":"seek","outcome":"母亲抱着你在门口站了半宿，海风把你的哭声吹散。父亲坐在桌边，钟谱摊着，笔尖的墨干在纸上。他说：这孩子留不住。你的名字那一栏空了三年，后来是你自己踩着小凳，拿他的笔描上去的，描得歪，他没改。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"惧":2},"flag":"unnamed_three_years","thread":"名字是你自己描上去的"}}]},{"id":"zhong_m02","act":"main","age":[6,6],"mode":"dialogue","title":"铜喉塔","opening":"六岁那年，父亲第一次带你上铜喉塔。塔身是铜的，摸上去比海水凉，手一贴上去，骨头里都听见响。爬到第七层，往下看，七声礁在潮里排开，一块对着一口钟。父亲让你把耳朵贴在壁上，说：听。海底有钟在响，一声一声，隔着水传上来，像有人在很远的地方敲一口空锅。钟声中间有个女人在念名字，念一遍，停一停。父亲嗓子哑，说话像钟的余音：听见什么了？","ask":"父亲问你听见什么，你怎么答？","days":10,"npc":"father","memory":"海底传来的钟声","choices":[{"title":"说出听见的名字","desc":"你把听见的那个名字说给父亲，一个字一个字说清。","hint":"父亲说是你听岔了。","tone":"honest","outcome":"父亲听完，先看塔下的海，再看你的嘴。他掏出钟谱，把那个名字写上去，写完又用指甲刮掉，刮得纸起毛。当晚议会的人上塔问话，父亲说是孩子听岔了，把人送下塔。那一年他没再带你上塔。母亲在你枕边放了一小袋盐，说压惊。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":2},"flag":"told_father_name","thread":"父亲把那个名字刮掉了"}},{"title":"跟父亲下塔","desc":"他说绳子卡了，你跟着下去，在底下替他扶梯。","hint":"那个名字没听清。","tone":"help","outcome":"梯子很陡，父亲踩一阶，你扶一阶。他的手在你头顶上，粗糙，稳。钟声从塔顶漏下来，隔了一层铜，听不真了。他在底下换绳，你在旁边举灯，灯油滴在手背上。那晚回家，他多给了你半块饼。那个名字你只记住一个阿字，后来在钟声里找了很多年。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":"只记住一个阿字"}},{"title":"敲小钟应一声","desc":"你摘下塔上的小钟锤，朝铜壁敲了一下。","hint":"海底的声音停了。","tone":"defy","outcome":"声音停了，停得很干净。父亲在塔下喊你，喊了七声，你没应。他冲上来，脸白得像刚捞上来的鱼，第一次朝你吼：你应它，它就来。塔上的小钟裂了一道缝，从那以后声音是哑的。他没再带你上塔，直到第二年开春。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":4,"哀":1},"flag":"answered_bell","thread":"小钟裂了一道缝"}}]},{"id":"zhong_m03","act":"main","age":[11,11],"mode":"dialogue","title":"这是病","opening":"第四口钟是冬天沉的。沉之前，岛上有个磨刀的阿潭，独眼，右手少半根指头，给你磨过一把小刀，刀柄缠蓝线。钟沉那天早上，你路过他家门口，他女人在扫台阶，台阶上有鱼鳞和海腥味，门槛边晾着一双旧靴子。你问：谭伯呢？她抬头说：谁。你说：磨刀的，独眼。她想了想，说：好像是有过这么个人。她记得那双靴子，不记得靴子是谁的。回家母亲把手在围裙上擦了擦，说：这是病，别记。","ask":"母亲说这是病，你怎么办？","days":20,"npc":"mother","memory":"独眼阿潭的靴子","choices":[{"title":"把记得的写下来","desc":"你偷一张钟谱的纸，用炭画下阿潭的白眼睛和蓝线刀柄。","hint":"纸藏在针线盒底。","tone":"keep","outcome":"母亲翻你的枕头，翻出那张纸。她看了很久，没烧，把它折成小方块，压进针线盒底。她说：收着，别给人看。从那天起，她给你缝了个贴身的小袋，袋子是用旧网线编的。你后来才知道，那个袋子本来是给要离岛的人装船钱的。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":2},"flag":"wrote_forgotten_man","thread":"针线盒底的那张纸"}},{"title":"当面念出名字","desc":"你站在院子里，把谭伯的名字念了三遍，念得很大声。","hint":"母亲第一次打了你。","tone":"honest","outcome":"母亲从灶边冲出来，捂住你的嘴，把你拖进屋。她的手很凉，劲很大。那天晚上她打了你一下，打在手心上，不重。她说：你把他喊回来，钟就要再沉一口。你问：那我记着也不行。她说：记着是你的事，喊出来是全岛的事。她说完去洗碗，碗在水里碰得很响。","eff":{"bond":-3,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"spoke_name_aloud","thread":"母亲说喊出来是全岛的事"}},{"title":"喝下艾草水","desc":"母亲熏你的耳朵，你端着碗，一口一口喝完。","hint":"你忘了他的声音。","tone":"obey","outcome":"艾草水苦得舌根发麻。你喝完吐了一回，母亲给你拍背，手一直在动。那天夜里你梦见磨刀的声音，第二天就不记得了。你先忘了他的声音，还记得那只白眼睛；过了半个月，白眼睛也淡了，只剩一把缠蓝线的刀柄。刀还在你抽屉里，你不知道是谁磨的。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":4,"惧":2},"flag":"drank_mugwort","thread":"缠蓝线的刀柄"}}]},{"id":"zhong_m04","act":"main","age":[15,15],"mode":"dialogue","title":"数名字","opening":"十五岁，你正式做学徒。守钟房在铜喉塔底下，屋顶漏，墙上挂着一排耳塞，是用蜡和布搓的；岛上的人把该还的东西刻在蜡上。父亲把钟谱摊在桌上，纸被海水泡过，边角发毛，字迹洇成一团一团。他教你：一声钟，一个名字；钟声不停，名字不能断，断了那一个就还不上。他敲了一下小钟，让你数。你数到第五声，第七声里多出一个名字，很轻，像有人在你耳边补了一句。","ask":"第七声里多出一个名字，你怎么记？","days":30,"npc":"father","memory":"钟声里数名字","choices":[{"title":"照实写进钟谱","desc":"你把那多出来的名字写进第七行，一笔一画。","hint":"父亲把那一行划了。","tone":"rule","outcome":"父亲看了一眼，拿过笔，把那行划掉，划得很重，纸都破了。他说：多记一个，全岛多背一年。你问是谁的名字，他没答，把钟谱合上，压在一块铜锭底下。晚上你收拾桌子，看见他在最后一页添了一行小字，写完用手掌盖住。你把抹布拧干，没问。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"saw_father_secret_line","thread":"最后一页被手掌盖住"}},{"title":"记在自己手心","desc":"你把那个名字写在左手心，写完攥成拳。","hint":"汗把字洇开了。","tone":"secret","outcome":"那天你攥了一夜拳头，第二天洗手，字已经洇成一团黑。你又写了一遍，写在手腕内侧，袖子盖得住。父亲看见了，没问。后来你在他钟谱的夹层里摸到一张薄纸，泡烂的纸，软得像布，上面是同一个名字，笔迹是他的。你把它放回去，从此你们谁也没提。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"哀":2},"flag":"knows_father_extra_name","thread":"钟谱夹层里的薄纸"}},{"title":"停下来问父亲","desc":"你按住钟绳，问他那多出来的是谁，问到他不答。","hint":"他陪你坐到天亮。","tone":"ask","outcome":"父亲说：你数错了。你从头再数，数到第七声，那个名字又来了。他不说话了，坐在门槛上，一口一口喝凉茶。塔外的潮水退下去，露出礁石。你数到天亮，数得舌头发干。他起身时拍了拍你的肩，说：学不会也好。这句话你记了很多年。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":1},"flag":"","thread":"他说学不会也好"}}]},{"id":"zhong_m05","act":"main","age":[19,19],"mode":"dialogue","title":"钟舌","opening":"十九岁那年，小螺半夜翻窗回来，浑身海腥味，头发上还挂着海草。她从怀里掏出一枚钟舌，铜的，冷的，比本岛任何一口钟的舌头都短一寸。她说：你猜我从哪儿摸的。沉钟渊底下，一口没名字的钟。你要怕，就当它是条不会烂的鱼。她说得像开玩笑，尾音还往上挑，手却一直在抖。钟舌上刻着一圈字，不是岛上的字，你一个也不认得。她把钟舌塞进你手里：替我藏两天。","ask":"这枚钟舌，你要怎么处置？","days":15,"npc":"sibling","memory":"不属于岛的钟舌","choices":[{"title":"帮她藏起来","desc":"你把钟舌裹进旧网，塞到灶膛后头的砖缝里。","hint":"卫队来搜过一次。","tone":"secret","outcome":"卫队是第三天来的，挨家翻箱。母亲把织机挪了半尺，正好挡住那块松砖。卫队的人用铁棍敲墙，敲到灶边，母亲说灶刚熄，灰会迷眼。他们走了。小螺回来取钟舌，把脸埋在你肩上，很快松开。你后来发现她没取走，只把钟舌挪到了自己的鱼篓底。","eff":{"bond":5,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":2},"flag":"hid_foreign_clapper","thread":"钟舌还在小螺的鱼篓里"}},{"title":"交给父亲","desc":"你趁小螺睡着，把钟舌包好，放到父亲的钟谱上。","hint":"她被罚去静湾。","tone":"report","outcome":"父亲看了钟舌一眼，脸色没变，只说：从哪来的，送回哪去。第二天卫队来了，小螺被带走，判在静湾服无钟苦役三个月。她走的时候没看你，鞋底在门槛上蹭了一下。三个月后她回来，手上多了两道绳痕，还讲海腥味的笑话，只是不再讲海底的事。","eff":{"bond":-6,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_sister_clapper","thread":"她不再讲海底的事"}},{"title":"让她扔回海里","desc":"你把钟舌推回去，说扔回海里，别带进家门。","hint":"她说扔了。","tone":"practical","outcome":"小螺把钟舌揣回怀里，说：行，扔。第二天她出海，回来时两手空空，晚饭吃了三碗。你没问。半年后你替她晒鱼篓，篓底摸到一块硬东西，用油布包着，还是那枚钟舌。你把它放回原处，盖好。海风把鱼篓吹得响，像很小的钟。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":"鱼篓底的油布包"}}]},{"id":"zhong_m06","act":"main","age":[24,24],"mode":"narration","title":"守一夜","opening":"二十四岁那年，第五口钟要沉。钟谱上被划掉的名字是阿鲛，渔妇阿箬的女儿，三年前死在海上，尸首没捞回来。按规矩，守钟人要在沉钟前夜去那户人家，点一盏灯，陪到钟响。阿箬的屋里挂着件小袄，灶上温着一碗鱼汤。她把这些年攒的潮铢推给你，你没接。她抓住你的手腕说：钟响的时候，你替我念她的名字，一遍一遍念，我跟着你念。她顿了顿：别让我忘了她。","ask":"钟要沉了，阿箬抓着你的手，你怎么答？","days":10,"npc":"","memory":"阿箬家的那盏灯","choices":[{"title":"答应替她记","desc":"你点头，坐在灯下，把阿鲛的名字念了一夜。","hint":"第二天她问你贵姓。","tone":"carry","outcome":"钟响的时候，阿箬跟着你念，念到第三遍就停了，眼睛看着灯芯。钟声散尽，她松开你的手，起身去灶上热鱼汤，问：你是哪家的后生。你说你是守钟的。她点头，给你盛了一碗。你喝完出门，在海边把阿鲛的名字念了三遍，记进自己心里，此后每年这天都替她记一回。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"carries_a_jiao","thread":"每年替她记一回"}},{"title":"告诉她实话","desc":"你说忘是忘定了，我只能替你记着，留不住。","hint":"她把你赶出门。","tone":"honest","outcome":"阿箬把你的手甩开，说：那你来干什么。她把灯吹了，屋里黑下来。钟响时你站在门外，听见她在里面念，念得很快，像怕赶不上。第二天她把小袄烧了，烟从窗口出来，一股焦布味。她再没跟你说过话。你每年还是替她记着阿鲛，记在一个她不知道的地方。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"她再没跟你说过话"}},{"title":"骗她不会忘","desc":"你说钟只收该收的，她不会忘，让她安心睡。","hint":"她睡得很沉。","tone":"hide","outcome":"阿箬信了，把灯芯捻小，躺下，很快就睡着，呼吸很轻。钟响的时候她翻了个身，没醒。第二天她起来，站在小袄前面问你：我女儿呢。你说：出海了。她点头，去灶上热粥，多摆了一副碗。你每年替她圆一次这个谎，圆到她搬去别的岛。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":4},"flag":"lied_to_a_ruo","thread":"多摆的那副碗"}}]},{"id":"zhong_m07","act":"main","age":[31,31],"mode":"dialogue","title":"最后一块衣角","opening":"三十一岁，第五口钟沉了以后，母亲开始烧东西。先是旧衣服，后来是鞋，再后来是一卷没织完的网线。她每天傍晚去海边，火很小，烟贴着水面走。你问她烧给谁，她说：烧给海。她坐在灶边，手一直在动，像在补一张看不见的网。有一回你翻她的针线盒，翻出一块烧剩的衣角，巴掌大，是襁褓上的布。母亲收回去用手量了量：就这么点大。她说：最后一块了。你问是谁的。她想了很久：记不清了。","ask":"母亲把最后一块衣角交给你，你怎么办？","days":20,"npc":"mother","memory":"烧剩的半块布","choices":[{"title":"替她烧了","desc":"你蹲下去，用火镰点着衣角，看它卷成一个小卷。","hint":"烟里有股奶味。","tone":"obey","outcome":"布烧得很快，火苗是黄的，烟里有股奶味。母亲站在旁边，手垂着，没动。烧完她说：好。从那天起她再没去过海边，傍晚坐在门口织网，织得比以前慢。你想起塔上那个念了又念的名字，阿澜。这个名字此后只有你一个人知道，你没告诉过她。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"burned_last_cloth","thread":"阿澜只剩你记得"}},{"title":"把衣角藏起来","desc":"你假装失手，把衣角掉进沙里，用脚踩住。","hint":"母亲找了一夜。","tone":"keep","outcome":"母亲蹲在沙滩上找，找到半夜，火镰掉在水里也没管。第二天她没问你，把织机搬到窗边，一整天没说话。那块衣角你藏在钟谱夹层里，和父亲那张泡烂的薄纸放在一起。很多年后你打开，布已经硬了，还有一点焦味。母亲到死都以为烧了。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"hid_last_cloth","thread":"她到死都以为烧了"}},{"title":"问她那是谁","desc":"你抓住她的手，说阿澜，问她记不记得这个名字。","hint":"她把名字念错了。","tone":"ask","outcome":"母亲的手在你手里停住。她说：阿澜。她把这个名字念了两遍，第三遍念成了阿蓝，自己没发觉。她说：我记得她怕黑，记得她左耳后有一颗痣。可我想不起她长什么样。你告诉她，名字是从父亲钟谱最后一页看来的。她点点头，把手抽回去，转身进屋，那晚没点灯。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":6,"惧":3},"flag":"told_mother_name","thread":"她把阿澜念成了阿蓝"}}]},{"id":"zhong_m08","act":"main","age":[38,38],"mode":"dialogue","title":"你叫什么","opening":"三十八岁那年，父亲开始忘事。先是忘了钟绳挂在第几个钉子上，后来忘了退潮的时辰。有一天他在塔下叫你，叫了一声喂，又改口叫小螺。你回头，他站在梯子上，手里拿着钟谱，问你：你叫什么来着。他说得很平常，像问今天涨不涨潮，嗓子哑得像钟的余音。他记得你是他儿子，记得你左腕上有颗痣，吃饭时还是把鱼肚上的肉夹给你。他只是想不起那个名字了。","ask":"父亲问你叫什么，你怎么答？","days":30,"npc":"father","memory":"父亲忘了你的名字","choices":[{"title":"写在他手心上","desc":"你拉过他的手，用指头一笔一笔写你的名字。","hint":"你写了九天。","tone":"heal","outcome":"第一天他看了半天，说：好字。第二天他又问。你写，他看。写到第九天，他把手攥起来，说：别写了，磨得疼。后来你在他枕头底下摸到一张泡烂的纸，被口水浸软，上面歪歪扭扭全是你的名字，写满一页，最后一个只写了一半。你把纸晾干，夹进钟谱。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":4},"flag":"wrote_name_on_palm","thread":"写满一页名字的软纸"}},{"title":"说这是钟声吃的","desc":"你说这病是钟声吃记忆，不是你老了，别撑着上塔。","hint":"他把钟锤挂上门后。","tone":"honest","outcome":"父亲听完，坐在梯子上没动。第二天他把钟锤从塔上拿下来，挂在门后，再没上去过。他每天擦那把锤子，擦得木柄发亮。有人来请他去听钟，他摆手，说：我听不准了，别误事。你替他上了塔。夜里你听见他在院里跟母亲说话，只听见一句：别让孩子看见我数不清。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"father_left_tower","thread":"他每天擦那把钟锤"}},{"title":"应下小螺这名字","desc":"他再叫你小螺，你就应，应得跟真的一样。","hint":"妹妹在门口站着。","tone":"dodge","outcome":"他叫你小螺，你应。他让你去把西边的钟绳收紧，你去。小螺有一回在门口听见了，站着没进来，转身走了。晚上她在灶上热饭，说了一句：哥，你应得挺像。她说完笑了一下，笑得很短。父亲到死都以为家里有个儿子叫小螺，另外一个，他忘了叫什么。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"爱":2},"flag":"","thread":"哥，你应得挺像"}}]},{"id":"zhong_m09","act":"main","age":[45,45],"mode":"dialogue","title":"她叫阿澜","opening":"四十五岁，母亲病了一个冬天。她躺在床上，手还在动，一下一下，像在织一张看不见的网。小螺从海上赶回来，鞋上带着海腥味，进门还说：娘，我给你带了条会骂人的鱼，它一路骂我网眼大。母亲笑了一下。岛上的人说，钟吃掉的名字，会在人临死前吐回来半口。那天傍晚，母亲忽然说：阿澜。她说完自己愣住，问你：阿澜是谁。屋里很静，钟声从塔上漏下来，一声。她的手还在被子上动。","ask":"母亲问阿澜是谁，你怎么答？","days":20,"npc":"mother","memory":"母亲最后的话","choices":[{"title":"说那是你姐姐","desc":"你俯下身，说阿澜是她的大女儿，死在第三口钟那天。","hint":"她听完，把脸转向墙。","tone":"honest","outcome":"母亲的眼睛睁着，看着房梁。她说：那我怎么不记得。你说：钟把她带走了。她想了很久，说：我记得有个人怕黑。她又问：她怕黑，我怎么没给她留灯。你说：留了，每年都留。她点点头，把手放到被子外面，慢慢不动了。窗外退潮，礁石露出来。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"爱":3},"flag":"mother_died_knowing","thread":"她问怎么没给她留灯"}},{"title":"说那是网的名字","desc":"你说阿澜是她织过的一种网，她织得最好，别多想。","hint":"她信了。","tone":"peace","outcome":"母亲哦了一声，说：那网结实，能兜住石头。她说完就睡了，睡得很安稳。后半夜她走了，手停在被子外面，像还要去够梭子。你替她把手指一根一根合上。小螺问你她最后说了什么，你说：说网。小螺点头，说：她这辈子就会这个。你没再解释。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":5},"flag":"lied_to_mother_end","thread":"她以为阿澜是一种网"}},{"title":"不答，替她数钟","desc":"你握住她的手，跟着塔上的钟，一声一声数到七。","hint":"你数到七，她的手停了。","tone":"carry","outcome":"你数到第三声，她的手动了一下；数到第五声，她跟着你的手指数；数到第七声，她的手停了。你没告诉她阿澜是谁。后来你想，她也许本来就知道，只是那个名字被钟咬掉了一半。你把她烧剩的衣角缝进自己的袖口，从此每年海边多一个人站着。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"爱":3},"flag":"counted_to_seven","thread":"袖口里的衣角"}}]},{"id":"zhong_m10","act":"main","age":[52,52],"mode":"narration","title":"裂缝","opening":"五十二岁，最后一口钟裂了。裂缝从钟口往上爬，爬到钟肩，像一条干了的水道。潮声议会的人来了三回，带着新的钟谱和一箱铜料，说补钟要献记忆，一年一段，献到钟不裂为止。静潮教团的哑姑也来了，跪在静湾的沙上，不出声。她见你过来，用手指在沙上写：让它沉，人就轻了。父亲已经认不出塔，每天还在门后擦那把钟锤。","ask":"钟裂着，全岛在等，你先做什么？","days":60,"npc":"","memory":"最后一口钟裂了","choices":[{"title":"献出母亲的记忆","desc":"你把手按在钟上，先交出母亲的声音，换一年。","hint":"你很快忘了她怎么叫你。","tone":"repair","outcome":"铜是凉的，凉到手心发麻。你走出静湾时，忽然想不起母亲的声音，只记得她织网时手一直在动。第二年裂缝又长一寸，你又去一回，这回交出她坐在门口的样子。第三回你站在她坟前，认不出碑上的字。钟撑住了，你的来处却越来越薄。","eff":{"bond":0,"health":-3,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":3},"flag":"fed_mother_memory","thread":"你忘了母亲的声音"}},{"title":"告诉全岛准备忘","desc":"你挨家敲门，说钟要沉了，让各家把名字写在手上。","hint":"父亲把钟锤藏了。","tone":"refuse","outcome":"岛上的人先是骂你，后来有人真的拿炭在手上写名字。议会的人来拦，说钟还没沉，不许散播。父亲听说了，把钟锤藏进灶膛后的砖缝，谁问都说不知道。哑姑在静湾朝你点头。你回家看见父亲坐在门槛上，手里空着，一遍一遍擦手心。","eff":{"bond":-1,"health":0,"reputation":-3,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":3},"flag":"warned_island","thread":"父亲把钟锤藏了"}},{"title":"按册子找下一家","desc":"你翻开议会的新册，去敲第一户的门，让他们献。","hint":"开门的是个小女孩。","tone":"practical","outcome":"开门的是个七八岁的女孩，她娘病在床上。你把册子摊开，说献一段记忆，钟就能多撑一年。女孩问：忘了娘，是不是就不疼了。你没答。她娘在屋里说：献我的。你站在门口，把册子合上又打开，最后写下了她娘的名字。回塔的路上，你听见自己的脚步很响。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":2},"flag":"collected_memory","thread":"女孩问忘了娘疼不疼"}}]},{"id":"zhong_m11","act":"main","age":[70,78],"mode":"narration","title":"静湾","opening":"七十岁那年，你握着父亲的钟锤站在静湾。钟在水里，只露出钟肩，裂缝张开，像一张要说话的嘴。全岛的人在岸上等。这八年钟一直裂着，没沉。裂缝每长一寸，就有人往里填东西——有人填铜，有人填记忆。你填自己：填到最后，你记得钟谱上每个名字，却忘了阿箬的脸、母亲的声音。七十八岁春，钟在水下响了一声，很闷。小螺带着女儿站在人群里，女孩攥着那枚不属于本岛的钟舌，海腥味飘过来。","ask":"钟要沉了，你举着锤，怎么办？","days":360,"npc":"","memory":"握着钟锤的八年","choices":[{"title":"敲响它","desc":"你把钟锤抡圆，砸在钟耳上，让全岛都听见。","hint":"钟声散后，谁都不能再忘。","tone":"brave","outcome":"钟声从静湾滚出去，撞在七块礁石上，又滚回来。岸上的人一个个站住——他们想起来了：阿澜、阿鲛、阿潭，还有你。有人叫出你的名字，声音发抖。钟没有沉，裂缝合上一半，海却退得很快，露出老航道。你知道它还会回来收。那天夜里，岛上没有一个人睡着。","eff":{"bond":3,"health":-3,"reputation":2,"coins":0,"stats":{"机缘":1},"emotion":{"爱":5,"惧":4},"flag":"rang_last_bell","thread":"海退得太快了"}},{"title":"让它沉","desc":"你退后三步，把钟锤放在沙上，看着水漫过钟肩。","hint":"明天没人记得你。","tone":"leave","outcome":"水漫过钟肩，漫过裂缝，钟没有响。岸上的人先是愣着，后来互相看看，像刚从长睡里醒来。有人问：咱们站这儿干什么。有人笑，说回家吃饭。你站在最后面，把那本泡烂的钟谱塞进钟口，看着它一起沉下去。小螺回头找了你一眼，没认出你。第二天船出了湾，海退了。","eff":{"bond":-2,"health":-4,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"哀":5,"爱":2},"flag":"let_bell_sink","thread":"小螺没认出你"}},{"title":"把名字分给人","desc":"你翻开钟谱，一页一页念，让岸上的人一人认一个名字。","hint":"有人会记错。","tone":"teach","outcome":"你念一个，就有人举手。阿鲛分给卖鱼的，阿潭分给磨刀铺，阿澜分给小螺的女儿。有人念两遍才念对，有人把两个字记成一个。念完你把空谱扔进水里，钟自己沉了，没响。岸上的人各自攥着一个名字回家，像攥着一枚烫手的铜。","eff":{"bond":4,"health":-2,"reputation":1,"coins":0,"stats":{"魅力":2},"emotion":{"爱":4,"哀":4},"flag":"shared_names","thread":"有人把两个字记成一个"}}]}],"side":[{"id":"zhong_s01","act":"side","age":[7,7],"mode":"narration","title":"数钟歌","opening":"七岁那年夏天，退潮后礁石一块块露出来，孩子们在滩上跳格子，一边跳一边唱数钟歌：七块礁，七口钟，七个不能念的名字。唱到第七句，谁接不上，就要被推下海。你唱得最熟，因为母亲织网时也哼这个调。那天新来的孩子唱到第七句，把“沉”唱成了“睡”。孩子们一下全停了，只有盐壳在脚底下响。他娘站在岸上，手里提着一串咸鱼。","ask":"第七句唱错了，你怎么办？","days":10,"npc":"","memory":"孩子们数钟的歌","choices":[{"title":"替他唱完第七句","desc":"你大声接上，把“睡”唱回“沉”，然后自己跳进水里。","hint":"咸水从鼻子里出来。","tone":"protect","outcome":"你跳下去，水到胸口，脚底踩到滑的石头。他伸手拉你，自己没湿。孩子们笑起来，把格子让给他。往后几年，一到第七句，他就看你一眼。你落下一个毛病：下水前先咳一声。","eff":{"bond":3,"health":-1,"reputation":1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":"一到第七句他就看你"}},{"title":"按住他重唱三遍","desc":"你把他按在礁石上，一句一句逼他唱对，唱错就重来。","hint":"他后来不唱歌了。","tone":"rule","outcome":"第三遍他唱对了，声音很平。孩子们叫他哑钟，他娘把咸鱼塞给他，牵走了。那年秋天他没再来滩上。再后来他上了外岛的船，走的时候没跟人说。数钟歌里第七句从此少一个声音。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"他走时没跟人说"}},{"title":"跟着把他推下去","desc":"你伸手推在他后背上，和大家一起喊，喊得比谁都响。","hint":"他额头磕在礁上。","tone":"defy","outcome":"他栽进水里，起来时额角裂了一道口，血混着海水往下流。他笑着说小伤，把咸鱼分给推他的人。你没接。那天回家，母亲问你怎么一身盐，你说摔了一跤。那道疤他带了一辈子。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"恶":2},"flag":"","thread":"那道疤他带了一辈子"}}]},{"id":"zhong_s09","act":"side","age":[10,10],"mode":"narration","title":"喜宴上的誓","opening":"十岁那年秋天，阿树娶阿棠。祠堂里摆两张桌，桌上是咸鱼、海带和一坛浊酒，海腥味压过酒味。按规矩，两家的岛钟要合鸣，鸣过之后新人把誓说给钟听。阿棠的娘把一块耳蜡按进她手心，说：说响些，钟听见了才算数。阿棠张了张嘴，没出声；阿树也张了张嘴，也没出声。满祠堂的人都不说话，只有钟绳在梁上轻轻晃。你蹲在桌底下，替他们捧着那盏灯。","ask":"一句誓都说不出口，你怎么办？","days":10,"npc":"","memory":"祠堂里的半句誓","choices":[{"title":"替他们把誓喊出来","desc":"你从桌底钻出来，站到钟前，把两个人的誓一句一句喊完。","hint":"钟记住了你的嗓子。","tone":"protect","outcome":"你喊到第三句，钟自己响了一声，很轻。阿棠的娘把酒倒进海里，祠堂里的人这才动筷子。婚后他们待你像自家人，年年给你留一条鱼。可你说话从此带一点回声，数钟歌唱到第七句就哑。阿棠后来跟人说：那天的誓，不是我们说的。","eff":{"bond":4,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"惧":2},"flag":"spoke_wedding_vow","thread":"誓是你替他们说的"}},{"title":"去叫证婚的守钟师","desc":"你跑去塔上把父亲拉来，让他按规矩把誓录进谱里。","hint":"誓一入谱，全岛多背一年。","tone":"rule","outcome":"父亲提着钟谱下塔，鞋都没换。他把两个人叫到钟前，一句一句问，一句一句记，记在泡烂的纸页边上。誓录进去了，婚算成了。那年冬天岛上多病了一个月，议会把多出来的名字写在谱末，字很小。阿棠从此在人前不叫阿树的名字，只叫一声喂。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"registered_wedding_vow","thread":"她在人前只叫一声喂"}},{"title":"敲盆把话盖过去","desc":"你抓起桌边的铜盆跳上凳子，敲得满祠堂听不见人说话。","hint":"婚成了，谱上没有他们。","tone":"defy","outcome":"铜盆响得刺耳，阿棠趁机把誓说给阿树一个人听，说得很轻。钟没听见。婚事办完了，可钟谱上两个人的名字没有并到一处。第二年他们生了孩子，孩子的名字只能写在谱的边角上，字小得像蚊子。阿棠的娘三年没跟你说话，见你就把门关上。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"惧":3},"flag":"covered_wedding_vow","thread":"谱边角上那个小字"}}]},{"id":"zhong_s02","act":"side","age":[12,12],"mode":"narration","title":"一墙耳蜡","opening":"十二岁那年，母亲让你送一袋盐去北礁。余婆的屋里只有一个灶、一张床，和一面墙的耳蜡。蜡是灰白的，一块挨一块，每块上刻一个名字，用指甲划的。她九十一岁，眼睛只剩一条缝，耳朵却尖，听脚步就知道是你。她说年轻时替人报名，全岛的名字都在她这儿。她从灶边摸出一块新蜡，蜡上刻着两个字，外面裹着一张泡烂的纸。她说：这个人我快记不住了。你替我记。","ask":"余婆把一块蜡塞给你，你怎么办？","days":60,"npc":"","memory":"余婆的一墙名字","choices":[{"title":"坐下来学那一墙名字","desc":"你每天下午来，让她念，你跟着背，背错就重来。","hint":"十三个名字你背漏了。","tone":"learn","outcome":"你学到入冬，背下两百来个，梦里都是别人的姓。那块刻着两个字的蜡你贴身收着，蜡被体温焐软了边。余婆腊月里走了，走前把墙上最后一块按在你手心。议会来收墙，你站在门口，忽然想不起其中十三个。那十三个名字此后一直空着，像掉了牙的牙床。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"learned_names","thread":"十三个名字空着"}},{"title":"报给议会收走","desc":"你跑去议会说北礁有一墙名字，请他们抄进钟谱。","hint":"蜡墙当天就搬走了。","tone":"report","outcome":"来了三个人，把蜡一块块撬下来，装进木箱，说要抄进新谱。余婆坐在灶边，手放在膝盖上，没拦。木箱抬出门时她问：抄完了还回来吗。没人答。新谱放进潮库房，第二年你去看，纸泡烂了一半，蜡也化了，黏在箱底。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"reported_wax_wall","thread":"蜡在箱底化了"}},{"title":"只拿走自家那块","desc":"你在墙上找到自家的姓，抠下那块蜡，揣进袖子。","hint":"她看着你挑。","tone":"practical","outcome":"余婆没说话，看你在墙上找。你找到铜九两个字，抠下来，蜡边碎了一角。她说：挑得对，一个人记一个就够。那块两个字的新蜡你没拿，留在她灶台上。你回家把自家的蜡放进盐罐，盐把蜡面磨亮。余婆死后那面墙被邻居拆了当柴烧，有股蜡味，飘了半个礁。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":"盐罐里那块蜡"}}]},{"id":"zhong_s03","act":"side","age":[17,17],"mode":"dialogue","title":"钟里有一只碗","opening":"十七岁那年，小螺第一次带你下沉钟渊。她在你腰上系绳，绳打七个结，说拉三个结是上来，拉五个结是绳断了。水到胸口时你听见钟声，不是从塔上，是从脚底下传上来的，闷，像有人在楼下搬桌子。潜到第三口气，你看见那口钟：侧躺在沙上，钟口朝上，里头是干的，干得发白，摆着一只碗、一双筷子，碗底结着一圈盐。","ask":"钟里那只碗，你要不要动？","days":10,"npc":"sibling","memory":"沉钟渊的那口钟","choices":[{"title":"把碗扶正，添一把盐","desc":"你把碗摆正，从怀里摸出一撮盐撒进去，朝钟口磕三个头。","hint":"上来时你咳出海水。","tone":"heal","outcome":"磕到第三个头，气就不够了。小螺拉绳，把你拖上去，你在船上咳了半天，咳出咸水。那口钟在你耳边响了一声，很轻。之后每逢阴天，你左胸里像压着一只碗。你没跟人说起过那口钟里的碗，也没再下去过。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"爱":2,"惧":3},"flag":"fed_bell_bowl","thread":"阴天胸口像压着碗"}},{"title":"上来讲给父亲听","desc":"你把看见的一字不落说给父亲，包括碗和那双筷子。","hint":"沉钟渊封了，小螺没了活计。","tone":"honest","outcome":"父亲听完，连夜上了议会。第二天沉钟渊立了浮标，不许下潜。小螺的鱼篓空了一个月，她坐在码头补网，见你过来就把脸转开。她说：你知道那底下有多少人靠它吃饭。你没答。那年冬天她借了别人的船，去了更远的未响海。","eff":{"bond":-4,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"reported_bell_bowl","thread":"她去了更远的海"}},{"title":"把碗揣进怀里带走","desc":"你把碗塞进怀里，用衣襟裹住，朝小螺比了个上去的手势。","hint":"碗里的盐永远干不了。","tone":"greed","outcome":"碗在怀里是凉的，贴着肋骨。上岸后你把它藏在塔底的砖缝里。第二天早上去看，碗底又结了一圈盐，昨天明明擦干了。你没敢再用它吃饭。小螺问你在底下拿了什么，你说什么也没拿。她看了你一会儿，没再问。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"欲":2,"惧":2},"flag":"took_bell_bowl","thread":"碗底天天结盐"}}]},{"id":"zhong_s10","act":"side","age":[18,18],"mode":"narration","title":"皮上的名字","opening":"十八岁那年，阿屿来找你。他弟弟阿汀是第四口钟沉那天没的，尸首没捞上来，钟谱上只留了一行。他坐在塔下，把左袖卷到肩，手臂内侧已经划好了两个字，墨吃进皮里，边上肿得发亮，还差最后一笔。他把针和一碗盐水推给你，说：你识字，你替我添。又说：你念一遍就行，我自己不敢念。塔外正在退潮，海腥味从窗缝里进来，桌上压着一张泡烂的纸。","ask":"针在你手里，最后一笔添不添？","days":15,"npc":"","memory":"皮上的两个字","choices":[{"title":"替他添上这一笔","desc":"你按住他胳膊，念一遍阿汀，把最后一笔描完，血珠冒出来。","hint":"钟会顺着血找来。","tone":"warm","outcome":"最后一笔落下去，他咬着筷子没出声。血珠沿字边走，盐水一抹，字黑了。你念名字时，塔上的钟自己响了一声。此后你半夜总听见有人叫阿汀，应过一回，右耳就整夜有钟声。三年后他的船没回来，捞上来时胳膊泡白了，字还在，钟却不肯为他响：名字在皮上，钟不认。","eff":{"bond":4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"爱":3,"惧":3},"flag":"inked_ati_name","thread":"右耳整夜有钟声"}},{"title":"报到守钟卫队","desc":"你把针收进袖子，出门就往卫队那边走，没回头。","hint":"他们用浮石磨他的皮。","tone":"report","outcome":"卫队当天下午就来了，两个人按住他，一个人用浮石和盐水磨。磨到第三遍，他不再挣了。字没了，皮上留一块淡红的疤，两个指头后来弯不直，捏不住网梭，改在岸上补船。他没骂你，只是有一年冬天在鱼市碰见，把手往袖子里缩了缩。","eff":{"bond":-5,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"reported_tattoo","thread":"他把手缩进袖子"}},{"title":"推给他一张纸","desc":"你把那张泡烂的纸推过去，说照这个描，别出声，我下去。","hint":"他描错了一笔。","tone":"avoid","outcome":"你下了塔，在礁上坐到天黑。他自己对着铜镜描，描歪了一笔，阿汀描成了阿灯。第二天他来谢你，把胳膊给你看，你没说是错的。此后他逢人就念阿灯，念得又顺又响。真正的阿汀没人念了，钟谱上那一行慢慢洇开，只剩一个汀字还认得出。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"恶":1},"flag":"","thread":"阿汀被描成了阿灯"}}]},{"id":"zhong_s11","act":"side","age":[26,26],"mode":"dialogue","title":"会响的箱子","opening":"二十六岁那年，小螺从沉钟渊拖上来一只箱子。木头的，四角包铜，铜上生绿锈，锁是死的。箱子一挪就响，不是木头响，是里面有东西在撞，一下一下，跟人心跳一样。她把箱子摆在塔底，蹲在旁边听，头发上的海腥味往下滴水。她说：行会出三十个潮铢收它，我还没答应。她抬头看你：你说里头是什么。箱缝里渗出一点水，是黑的。","ask":"箱子还在响，你把它怎么办？","days":20,"npc":"sibling","memory":"一挪就响的箱子","choices":[{"title":"藏进塔底替她担下","desc":"你跟行会说箱子散在礁上了，把它塞进塔底的砖洞。","hint":"它每一潮都响一回。","tone":"secret","outcome":"行会的人来问了两回，你都说散了。箱子塞进塔底，每天两次潮水一动，它就在砖洞里头撞，隔着地板传上来。你渐渐睡不整夜，右耳常年有闷响。小螺照旧分到一份钱，什么都不知道。第三年砖洞渗黑水，塔底的地板烂了两块，你换地板时没敢把箱子挪出来。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":3},"flag":"hid_ringing_box","thread":"塔底砖洞里的黑水"}},{"title":"报议会，当众沉回去","desc":"你去议会说了，第三天来了船，把箱子抬到七声礁外坠下去。","hint":"小螺的份子钱没了。","tone":"rule","outcome":"沉箱那天来了一船人，箱盖撬开过一线，里头是一口拳头大的钟，钟舌用头发缠着。议会的人念了一个名字，不是你岛上的姓。船开出七声礁，箱子坠下去，海面冒了一串泡。行会扣了小螺三个月份子，她坐在码头补网，说：你至少该先跟我说一声。此后她下潜不再叫你。","eff":{"bond":-4,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"恶":2},"flag":"sunken_ringing_box","thread":"她下潜不再叫你"}},{"title":"卖给北滩的陆商","desc":"你让行会牵头，把箱子卖给等在北滩的陆商，价加了一倍。","hint":"船开出未响海，它还在响。","tone":"trade","outcome":"陆商当场数了钱，用麻布把箱子裹三层，抬上船。船半夜开走，你在岸上还听见那一下一下的撞，撞到桅杆那边才散。小螺换了一副新网，请你喝了半坛酒。第二年有外岛的人说，那箱子在陆上的铺子里，标价翻了三倍，还在响，买的人排到门口。","eff":{"bond":2,"health":0,"reputation":-1,"coins":140,"stats":{"机缘":2},"emotion":{"欲":3,"惧":2},"flag":"sold_ringing_box","thread":"那箱子还在别人的铺子里响"}}]},{"id":"zhong_s04","act":"side","age":[29,29],"mode":"narration","title":"三双空鞋","opening":"二十九岁那年秋天，三条船出去，回来一条。祠堂地上铺了三张草席，席上摆三双鞋，鞋里填了沙，怕被风吹走。门槛上结了一层盐，踩上去咯吱响。阿树的媳妇抱着他的烟杆坐在最前头，烟杆里的灰早凉了。按规矩，人没有尸首，不能携钟入海，钟就不该敲。可三家人都在等，等的是一声。","ask":"没有尸首的葬礼，这钟怎么敲？","days":20,"npc":"","memory":"没有尸首的葬礼","choices":[{"title":"把名字刻进钟壁","desc":"你用铁钉在钟内壁划三个名字，划完再敲，敲到手指发麻。","hint":"钟壁多了三道划痕。","tone":"repair","outcome":"铁钉打滑，划破你左手虎口。钟响的时候声音是空的，像敲在一口井上。三家人跪下去，阿树的媳妇把烟杆插进沙里。议会来人看了钟壁，说坏了规矩，罚你三个月不许上塔。那三道划痕一直在，后来每回敲钟，你都听得见它们在响。","eff":{"bond":3,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":3},"flag":"carved_three_names","thread":"钟壁上的三道划痕"}},{"title":"照规矩，不敲","desc":"你把钟绳盘好挂回钉子，说没有尸首就不能敲，谁求也不敲。","hint":"有个人朝你扔了鞋。","tone":"rule","outcome":"阿树的媳妇把鞋脱下来朝你扔，沙撒了一地。她说不敲，他们就成了无声的东西，在海底拖着整座岛。你弯腰把鞋捡起来，放回席上。三家人自己抬着空席去了海边，没有钟，只有浪。那之后那片海没人撒网，鱼多得发黑。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"那片海没人撒网"}},{"title":"去行会借一口钟","desc":"你去捞钟行会借来一口钟，说先办事，账以后再算。","hint":"那口钟的声是别人的。","tone":"trade","outcome":"钟是从外岛运来的，铜色发青，声音比本岛的尖。敲到第三下，阿树的媳妇抬头看塔，说这不是他听惯的声。事办完了，三家人各自回家。你欠行会三个月的活，替他们刷船底、晒网。后来阿树的小女儿问你：我爹的名字敲起来是什么声。你张了张嘴，没答上来。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"恶":1},"flag":"rented_bell","thread":"他女儿问名字的声音"}}]},{"id":"zhong_s05","act":"side","age":[33,33],"mode":"narration","title":"她还抱着那件小袄","opening":"三十三岁那年，阿箬来塔下找你。她老得快，头发白了一半，怀里抱着一件小袄，袖口磨破，领子上有一圈洗不掉的黑。她说：我屋里一直有这件袄，我每天早上给它掸灰，掸完就站在门口。她顿了顿，说听说守钟人记性好。她抬眼看你：你别让我忘了她。我已经忘了，我怕连“忘”这件事也忘掉。","ask":"她求你别让她忘了女儿，你怎么应？","days":15,"npc":"","memory":"阿箬抱着小袄","choices":[{"title":"应下，每年念一次","desc":"你点头，问清日子，说每年的那一天我来门口念她的名字。","hint":"你拿自己的记性垫给她。","tone":"carry","outcome":"你把阿鲛两个字记在自己心里，每年那天去她门口念一遍。她听见了，就问是谁家的孩子，你说是海上的。她点头，给你留一碗鱼汤。念到第七年，你发现自己忘了别的一些事，先忘的是鱼汤的味道。小袄还挂在她屋里，灰越掸越薄。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":3},"flag":"carries_a_jiao_again","thread":"先忘的是鱼汤味"}},{"title":"告诉她实话","desc":"你说你记不住那么久，钟声一响，谁都会忘，别指望我。","hint":"她再没上过塔。","tone":"honest","outcome":"阿箬的手从袖口上松开。她站了一会儿，说：那我记着袄就行了。她转身下塔，走到第三级又回头问你：她是不是叫阿鲛。你说不知道。她点点头，走了。此后她再没上过塔。每年那天你还是去海边站着，不进门。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":1},"flag":"","thread":"她在第三级回头问过"}},{"title":"把小袄收进塔里","desc":"你说袄放这儿，塔里干燥，她什么时候想看就上来看。","hint":"她后来不来了。","tone":"keep","outcome":"你把小袄折好，放进塔底那只旧木柜，柜里还有几块没刻字的耳蜡。阿箬头一个月来了四回，第二个月来一回，后来不来了。小袄在柜里放了很多年，领子上那圈黑还在。有一年潮气重，袄角生了霉，你拿出去晒，晒完又叠好放回去。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"kept_a_ruo_coat","thread":"柜里那件小袄"}}]},{"id":"zhong_s12","act":"side","age":[35,35],"mode":"narration","title":"它为什么哭","opening":"三十五岁那年，小螺的女儿阿蜊五岁。她跟着上塔送饭，蹲在钟口底下，忽然抬头问：它为什么哭。那天海上起风，风从钟口的裂缝挤进去，出来时变成一种细声，一高一低，跟人憋着哭一样。她仰着脸等你说，手里还攥着半块饼。塔下有人在晒网，海腥味顺着塔身往上爬，钟锤靠在墙角，柄上有一圈汗渍。","ask":"一个五岁的孩子问钟为什么哭，你怎么答？","days":10,"npc":"","memory":"裂缝里的哭声","choices":[{"title":"告诉她在数名字","desc":"你蹲下来，说钟里有人在数名字，数到自己那一个就停一下。","hint":"她开始跟着数。","tone":"honest","outcome":"她听完没说话，把饼掰成小块，一块一块摆在钟座上。当晚她躺在席上数手指，数到第七下停一停。半个月后她能在钟声里听出那个多出来的名字，跟你十五岁时一样。小螺在门口站了一夜，第二天问你：你教她的。你没答。她从此不让阿蜊上塔，可阿蜊已经会数了。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"惧":4},"flag":"taught_child_names","thread":"阿蜊已经会数了"}},{"title":"爬上去糊住那条缝","desc":"你带着蜡和旧网爬上钟肩，把那条裂缝一层层封死。","hint":"缝里的气没处走。","tone":"repair","outcome":"蜡一按上去，哭声就断了。阿蜊在底下拍手，说它不哭了。她记了很多年，逢人就说塔上的钟是哑的。那冬天缝从钟肩爬到了钟腰，议会来看了一回，罚你三个月不许碰钟。你后来才知道，那声音是钟在出气，气堵住了，钟就自己往里裂。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":2},"flag":"sealed_bell_crack","thread":"缝爬到了钟腰"}},{"title":"抱她上塔听一夜","desc":"你把她裹在怀里抱上塔顶，坐到天亮，让她自己听。","hint":"你胳膊麻了三天。","tone":"carry","outcome":"她听到半夜就睡着了，脸压在你肩上，口水湿了一片。那一夜风停着，钟一声没哭。天亮下塔，小螺提着灯站在门口，接过孩子，只说了句饭在锅里。她把孩子抱走，没回头。你举了一夜的胳膊，麻了三天，抬不起来敲钟。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":2},"flag":"held_child_all_night","thread":"那晚钟一声没哭"}}]},{"id":"zhong_s06","act":"side","age":[42,42],"mode":"narration","title":"第七句是什么","opening":"四十二岁那年冬天，你在塔下补钟绳。门外有女孩跳格子，唱数钟歌，唱到第七句，她唱“睡”。你张嘴要纠正，忽然发现下一句不在嘴里了。调子还在，三个字的位置还在，唱到那里要停半拍也还记得——就是不记得那三个字。风从塔缝里钻进来，带着盐，也带着一点焦布味，母亲今天又在海边烧东西。你把手里的绳结拆开重打，打了三遍，三遍都是空的。","ask":"第七句那三个字，你怎么办？","days":30,"npc":"","memory":"忘掉的第一句","choices":[{"title":"到滩上替她担下来","desc":"你跟大人们说歌是你让改的，与孩子无关，骂名你接。","hint":"你被当成糊涂人。","tone":"protect","outcome":"老婆子在滩上骂了你半天，说你守钟守糊涂了，把歌都守丢了。女孩没挨打，站在人后面看你。往后她编的那三个字就这么唱下去，一年一年，谁也说不清哪一版是真的。你在塔上听着，听着听着也当它是真的了。","eff":{"bond":2,"health":0,"reputation":-2,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"took_blame_for_song","thread":"你也当它是真的了"}},{"title":"按她重唱到我点头","desc":"你叫住她，说唱错了，一遍遍重来，唱到你点头为止。","hint":"你指的其实是自己猜的。","tone":"teach","outcome":"女孩重唱了六遍。你听着，觉得哪一种都像，就指了第二遍，说这个对。她记住了，回家教她弟弟。第二年滩上的孩子都这么唱。她后来做了歌头，谁唱错她打谁手心。你站在塔上听，听不出哪儿不对，只是心里知道自己给的是猜的。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":2,"恶":2},"flag":"taught_guessed_song","thread":"她打人手心"}},{"title":"跟着她哼过去","desc":"你把那三个字改成哼，哼得含糊，混在孩子的声音里。","hint":"第七句从此只哼不唱。","tone":"hide","outcome":"女孩没听出来，跳到下一格。后来你也这么哼，孩子们跟着学，第七句就没了词，只剩三个音。有回外岛来的人问这歌怎么唱，孩子们哼到那儿一齐停半拍，接下去。你在旁边听着，喉咙里有点痒，像还欠一口气。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":2},"flag":"hummed_seventh_line","thread":"欠着的那半拍"}}]},{"id":"zhong_s13","act":"side","age":[47,47],"mode":"narration","title":"三天的哑钟","opening":"四十七岁那年，哑姑要死了。她住在静湾后面的石屋里，屋里没有钟，连一块铜片都没有——静潮教团的人不许有钟。她瘦得只剩一把骨头，用指头在你手心写：我有名字。写完又写：三天。意思是她那口钟只等三天。可她的名字早不在谱上：入教那年，议会把她的名字从旧册上划了，那页纸泡烂了，划痕比字还粗。塔上的钟这几天一直没响，海腥味压在湾里散不开。","ask":"三天里，这个没名字的人怎么办？","days":10,"npc":"","memory":"没有名字的钟","choices":[{"title":"报上自己的名字敲","desc":"第三天清早，你报上自己的名字，替她敲了那口小钟。","hint":"钟以后会数你两遍。","tone":"carry","outcome":"钟响的时候她还睁着眼，听见了，嘴角动了一下。她走后教团的人把骨灰撒进湾里，没立碑。第二年钟声里数名字，数到第七下多出一个，是你的名字。你在塔上站着，觉得脚下轻了半寸。再往后有人叫你，你回头总要慢半拍。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":3},"flag":"rang_for_mute_with_own_name","thread":"你回头总要慢半拍"}},{"title":"报议会，按无名处置","desc":"你上塔翻出旧册，把她那一栏空着报了上去。","hint":"她走的时候钟没响。","tone":"rule","outcome":"议会当天就回了话：无名者不敲钟，免得全岛多背一年。第三天夜里她走了，石屋里静得能听见潮。教团的人来抬她，不让你进门。他们把一口没响过的小钟放在她胸口，一起抬去静湾。那年冬天湾里的水特别响，渔民说底下有东西在撞船板。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":"湾里有东西撞船板"}},{"title":"编一个名字给她","desc":"你在石屋门口的沙上写三个字，教教团的孩子念。","hint":"那不是她的名字。","tone":"niche","outcome":"你编的名字叫阿默，好念，孩子学了三遍就会。第三天钟响了，声音发闷，像敲在一口装满沙的罐子里。全岛多背了一年，议会查不出多的是谁。后来有人在静湾捡到一块耳蜡，上头刻着阿默两个字，边上插了一炷香。你不知道该不该说那名字是假的。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":3,"爱":2},"flag":"invented_mute_name","thread":"耳蜡上那个假名字"}}]},{"id":"zhong_s07","act":"side","age":[60,60],"mode":"narration","title":"还你一句话","opening":"六十岁那年，外岛船靠岸，下来一个男人，头发白了，背一只旧鱼篓。他在鱼市站了半天，问有没有一户姓周的，没有人接话。他走到塔下坐下，唱数钟歌，唱到第七句，唱的是“睡”。四十年前，他娘阿婵临死前把一张泡烂的纸塞给你，纸上是两个字，她让你收着，说有一天会有人来问。她还说：他不是沉在海里，他是自己走的。这话别跟岛上人讲。","ask":"他坐在塔下，那句话你说不说？","days":20,"npc":"","memory":"泡烂的那张纸","choices":[{"title":"把纸和实情都给他","desc":"你把纸摊在他膝上，说：你娘让我记着，你是自己走的。","hint":"她托你守住的那句话，你破了。","tone":"honest","outcome":"他把纸捏在手里，指头抖了一下，说他知道，是他自己走的。他问娘有没有骂他。你说没有，她只说你走那天鞋没带。他低下头，很久没说话。走前他把鱼篓留给你，篓底一层干盐。你回塔后想起阿婵交纸时的眼睛，觉得自己欠她一句。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"told_zhou_truth","thread":"他走那天鞋没带"}},{"title":"只说娘等他到老","desc":"你把纸给他，说她等到最后一天，别的话一个字不提。","hint":"他谢了你，眼里没有底。","tone":"keep","outcome":"他问娘临死前说了什么。你说她念你的名字，念了好多遍，别的没说。他点头，把纸折成小方块收进怀里，说那就好。第二天他上船走了，在船尾朝塔挥了挥手。纸的事你办完了，那句话还留在你这里，像一颗咽不下去的盐粒。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"哀":3,"爱":3},"flag":"kept_chan_promise","thread":"咽不下去的盐粒"}},{"title":"到鱼市把名字喊出来","desc":"你站到鱼市中间，把周载两个字喊三遍，喊到钟自己响。","hint":"全岛要多背一年。","tone":"brave","outcome":"名字喊出去，塔上的钟自己响了一声，卖鱼的都停了手。有人忽然说：我见过一个额角有疤的孩子。话一开头，又有人想起阿婵在门口晒咸鱼。那年冬天岛上死了两个老人，比往年多，议会把多出来的名字记在谱末，写得很小。他留下来了，住在北坡。","eff":{"bond":4,"health":-1,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"惧":2},"flag":"spoke_zhou_name","thread":"谱末那个小字"}}]},{"id":"zhong_s14","act":"side","age":[62,62],"mode":"narration","title":"多出来的名字","opening":"六十二岁那年，议会要重修钟谱。最后一口钟裂着，谁也不知道还能撑几年，旧谱上的名字得赶紧抄进新册。父亲那本谱交到你手上，纸被海水泡过，边角发毛，翻一页掉一点渣。你抄到最后一页，那里有两行字：一行是阿澜，你知道是谁；阿澜下面还有一行，字更小，被手掌擦了半辈子，擦得只剩轮廓。你凑到灯下看，是铜九——你父亲自己的名字，写在亡者那一栏，日子是你出生那天。","ask":"这一行多出来的名字，你怎么办？","days":60,"npc":"","memory":"谱上多出的一行","choices":[{"title":"照原样抄进新谱","desc":"你把铜九两个字一笔一画抄下来，抄在阿澜下面。","hint":"岛上要多背一年。","tone":"rule","outcome":"新谱收上去那天，抄谱的老先生数了一遍，抬头看你一眼，没说话，在页末添了个小字。那年冬天岛上死了两个老人，比往年早。鱼市上有人骂，问谁家又多记了一个。你没应。父亲的嗓门你早记不全了，可那两个字在谱上，白纸黑字，谁也擦不掉。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"copied_father_name","thread":"谱末那个小字"}},{"title":"抄在手心，刮掉那行","desc":"你先把铜九写在左手心，再用指甲把谱上那一行刮白。","hint":"名字离了纸，得有人接着。","tone":"carry","outcome":"刮到最后纸破了个小洞。那年冬天岛上没多死人，你却在开春白了半头，眼睛也花了。父亲的名字没进新谱，只在你手心。汗一洇就淡，你每隔几天重写一遍，写到后来，笔画抖得不成形。旧谱你烧了一半，又夹出来，缺了一角。","eff":{"bond":2,"health":-3,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"carried_father_name","thread":"手心一次次淡下去的两个字"}},{"title":"拿去问最老的守钟师","desc":"你抱着谱上塔，去问议会里最老的那个守钟师。","hint":"他把谱收走了。","tone":"elder","outcome":"老守钟师把谱摊在膝上，指头压着那行小字，说：你爹来过，问我一个人的名字能不能写两回。我说不能。他哦了一声。第二天他报了上去，说旧谱有误，要收去校。谱被人用油布包走，你再去问，说在库里。此后你只在梦里见过那一页，铜九两个字被手掌擦得发白。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"怒":2},"flag":"","thread":"梦里那一页被擦白"}}]},{"id":"zhong_s15","act":"side","age":[74,74],"mode":"narration","title":"下一个守钟人","opening":"七十四岁那年，议会送来一个女孩，叫阿蚬，十一岁，瘦，头发用一根鱼线扎着。她站在塔底，仰头看那道从钟肩爬到钟口的裂缝，看了很久。她是北坡织网人家的孩子，三个月前在钟声里数名字，数到第七下，说多了一个。议会的人说这孩子耳朵有病，让你看看。你让她上楼，敲了一下小钟，她数到第七声，停住，说：这儿多一个。你手里的钟锤停在半空。四十年了，这句话你只在自己嘴里听过。","ask":"这个听得出多一个的孩子，你怎么教？","days":200,"npc":"","memory":"第七声多一个","choices":[{"title":"教她全部的名字","desc":"你把谱上的、谱外的名字一个一个念给她，让她跟着数。","hint":"教一个，你少一个。","tone":"teach","outcome":"教到第三个月，她能在钟声里数出四百一十三个名字，一个不差。你开始忘事：先忘了自己教过哪一句，后来忘了她叫什么，见了面只点头。她把你的名字写在塔壁内侧，用炭，写完用手掌抹平。你每天上去摸一遍，摸到字就安心，摸不到也想不起来少了什么。","eff":{"bond":5,"health":-3,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"爱":4,"哀":4},"flag":"taught_next_keeper","thread":"塔壁内侧用炭写的名字"}},{"title":"只教谱上的名字","desc":"你按议会的新册教，她一说多，你就说她数错了。","hint":"她学会了不信自己。","tone":"rule","outcome":"她学得很快，数得干净，四百一十二个，一个不多。议会来人考她，她答得一字不差，当场定了守钟的班次。她走那天在塔门口回头问：那第七下真的没有吗。你说没有。她点头，用蜡把耳朵封上。后来她敲钟敲得很准，只是从来不在塔上多站一刻。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"taught_by_the_book","thread":"她用蜡把耳朵封上"}},{"title":"挂回钟锤，下塔去静湾","desc":"你把父亲的钟锤挂回钉子，不再教，坐到静湾的沙上。","hint":"她跟议会的人学。","tone":"quit","outcome":"她在塔上等了你三天，第四天议会派了个老执事来，教她按册点名，点完就关窗。你坐在静湾的沙上，听见她敲错了一回，敲在退潮前半个时辰。你没上去。后来她敲得越来越顺，顺得像钟本来就这么响。你听着，觉得那声音里少了一个人。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"惧":2},"flag":"left_next_keeper","thread":"那声音里少了一个人"}}]},{"id":"zhong_s08","act":"side","age":[76,76],"mode":"narration","title":"雾里没有钟声","opening":"七十六岁那年春天，海上起雾。雾不是从海上来，是从水里长出来的，先没了七声礁，再没了塔尖。你按时敲钟，钟响了，声音出不去，像敲在一床湿棉被上。街上的人先是互相看，后来卖鱼的放下刀，整条街都停了。有人问：今天涨潮没有。没人答得出。这是全岛第一次害怕——不是怕死，是怕不知道自己还在不在时间里。","ask":"钟声出不去，你先做什么？","days":10,"npc":"","memory":"听不见钟的岛","choices":[{"title":"一直敲，敲到手掌裂","desc":"你不下塔，两天两夜抱着钟绳敲，手心磨破也不停。","hint":"你左耳再听不见高音。","tone":"grind","outcome":"敲到第二天，钟口是温的，你的手掌裂开两道，血沾在绳上。第三天有个孩子在岸边说他听见了，从水底下。雾当天下午散了。你的左耳从此听不见高音，小钟的声音你再也听不着。夜里安静的时候，那两天两夜的钟声还在耳朵里响。","eff":{"bond":2,"health":-3,"reputation":2,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"rang_through_fog","thread":"左耳听不见高音"}},{"title":"让各家把名字写手上","desc":"你挨家敲门，让每个人用炭把名字写在手心，一个时辰念一次。","hint":"有三家搬走了。","tone":"rule","outcome":"多数人照做了，念名字的声音一条街一条街地起。有个老头念到一半停住，说不记得自己叫什么，把手藏到背后。雾散了以后，有三家收拾东西搬去了外岛，说这岛疯了。留下的人从此有个习惯，洗手前先看一眼手心。","eff":{"bond":1,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":2},"flag":"wrote_names_on_hands","thread":"洗手前先看手心"}},{"title":"上塔把钟绳割断","desc":"你拿刀上塔，把钟绳割了，让这座岛这几天不算时间。","hint":"全岛欠了三天的债。","tone":"defy","outcome":"绳断的时候钟晃了一下，没响。岛上睡了三天，雾散才有人醒。醒来第一件事是算日子，可日子少了三天，谁也对不上。应响的债、耳蜡上刻的期、出海的班次，全都错开三天，此后年年有人为这三天吵架。你把断绳收在柜里，没再换新的。","eff":{"bond":-1,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"恶":1},"flag":"cut_bell_rope","thread":"年年为那三天吵架"}}]}]},"髓云都市":{"no":5,"name":"髓云都市","subtitle":"被删掉的那个人，还在你身体里","through":"你卖掉一段最好的记忆换母亲的手术费。她活了下来，却不记得你。","cast":[{"id":"mother","name":"母亲","role":"裁缝","tag":"母"},{"id":"father","name":"父亲","role":"码头工","tag":"父"},{"id":"friend","name":"阿棠","role":"记忆整理师","tag":"友"}],"main":[{"id":"sui2_m01","act":"main","age":[0,0],"mode":"montage","title":"缝在衣角","opening":"产房在城最底下那一层，窗外是排雾管，白雾一层压一层往上走，走到高处就散了。接生的护士拿雾髓棉球按你的脚心，屋里一股甜味，甜得发闷。你哭了一声，不大。母亲躺在铁床上，头发湿透，先问的是：孩子的手指全不全。父亲在走廊里坐着，鞋上带着码头的黑泥，帽子攥在手里，没进来。母亲把你的小褂翻过来，在衣角上缝了三个字，针脚一个挨一个。她说：这样我忘了，衣裳还记得。","ask":"她把你抱过来，你抓住什么","days":300,"npc":"","memory":"衣角上的三个字","choices":[{"title":"攥住她的手指","desc":"你攥住她右手食指，攥得指节发白，她没抽。","hint":"她那只手阴天就抬不起来","tone":"family","outcome":"她低头看你，手指没动，任你攥着，直到护士来抱你去洗澡。她后来跟人说，这孩子生下来手就是凉的。那天夜里她把你放在胸口，一只手一直握着你的手，另一只手在缝。她的右手食指后来阴天就抬不起来，她说是泡水泡的，没提你。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"爱":4,"哀":1},"flag":"","thread":""}},{"title":"推开那根针","desc":"你伸手去推她手里的针，针尖扎进自己掌心。","hint":"掌心留了个白点","tone":"warm","outcome":"血珠冒出来，你没哭，她先慌了，把你的手含进嘴里，尝到铁锈味。她说：傻的。那天她把针收进一只铁盒，盒子塞在缝纫机抽屉最里头。你左手掌心留下一个白点，一辈子都在。她后来提起，只说是你自己淘气。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":1},"flag":"","thread":""}},{"title":"让护士抱走","desc":"你松开手，让护士把你抱去婴儿室，不哭。","hint":"她说那晚听见你没哭","tone":"obey","outcome":"门一关，走廊里只剩推车轮子响。母亲躺回去，眼睛一直看门。半夜她扶着墙走到婴儿室窗外，站了半个钟头，回去时伤口渗了血。第二天她说：这孩子昨晚没哭。护士说哭了。她说不信，我听着呢。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"sui2_m02","act":"main","age":[6,6],"mode":"dialogue","title":"甜雾","opening":"雾髓温室在城北，玻璃顶，里面白得看不见人。母亲给温室的工人缝工装，二十件，捆在一块蓝布里，让你抱着。进门要过一道风帘，帘子一掀，甜味就上来了，像有人把一整罐糖化在水里。母亲把工装摊在案子上，让管事点数。点完她转过身，站在雾里，手还伸着，忽然不动了。她看看自己的手，又看看你，说：我来干什么的。管事在后头催。她的手在围裙上擦了擦。","ask":"她的手空着，你要怎么做才好","days":20,"npc":"mother","memory":"温室门口的空手","choices":[{"title":"替她把话说清","desc":"你告诉管事，我妈最近老忘事，工装是她缝的。","hint":"她再没接过温室的活","tone":"honest","outcome":"管事看了她一眼，把工钱数出来，说以后不用送了。母亲把钱攥在手里，一路没说话。回到家她把工装上的线头一根一根剪，剪得很齐。晚上她给你缝校服，缝到袖口停下，问你：今天是不是有人跟我说了什么。你说没有。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"牵她出来","desc":"你拉住她的手往外走，说衣服送到了，回家。","hint":"那批工装留在门口","tone":"protect","outcome":"她跟着你走，走到风帘外还回头看了一眼。工装留在案子上，工钱没结，第二天管事派人送了半价来，说活没交齐。她收下，没问为什么少。你在温室里站了小半个时辰，回家后半天想不起自己进门时先迈的哪只脚。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":1},"flag":"","thread":""}},{"title":"进去替她送","desc":"你抱起蓝布包，一个人穿过风帘，把衣服放上案子。","hint":"那天你只记得甜味","tone":"carry","outcome":"雾到你胸口，甜的，凉的，进到鼻子里就化开。你把工装一件件摆好，出来时腿有点软。母亲在门口数自己的手指，数到第三遍才看见你。她问：你怎么从里头出来。你说我一直在外头。那天以后，你只记得甜味，别的一点都想不起来。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}}]},{"id":"sui2_m03","act":"main","age":[12,12],"mode":"narration","title":"一整面墙","opening":"十二岁那年，学校带我们去封存塔认瓶。塔是灰的，进去要脱鞋，换一双薄底布鞋。管理员给每人发一块铜牌挂在脖子上，牌上打着号：B-1147。他说丢了要重新申请资格。塔里冷，瓶子码在架子上，码到看不见顶。玻璃上有一层薄雾，像刚有人朝上面呵过气。甜味从通风口里一点点渗下来。母亲在门外等你，看见你就招手，叫了一个名字，不是你的；她顿了顿，改口叫：阿砚。","ask":"队伍往前走，你在哪儿停下","days":10,"npc":"","memory":"铜牌上的号码","choices":[{"title":"数到最上面一层","desc":"你仰着头一层一层数，数乱了就从头再来。","hint":"出塔时队伍早走了","tone":"learn","outcome":"你数到一百二十七就乱了，重数，又乱。管理员来拍你的肩，说走了。出塔时队伍已经没影，母亲在门口蹲着，手里拎着你的鞋。回去的车上你还在数。很多年后你做审计员，站在架子前扫一眼，就知道哪一格空过。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"喜":2,"惧":1},"flag":"counted_the_wall","thread":""}},{"title":"问赎不回来怎么办","desc":"你指着墙角那排没名字的瓶子，问管理员那些是谁的。","hint":"母亲的针停了很久","tone":"ask","outcome":"管理员说，到期不赎，归公共库，名字刮掉，编号留着。他说：人还在，记忆归大家。晚上你把这话学给母亲听，还说她的名字以后也会被刮掉。她正在给你缝衣角，针停在布上，停了好一会儿，说：算。就是轻一点。她说完低头继续缝，线用完了也没换。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":3},"flag":"knows_public_pool","thread":""}},{"title":"写下母亲的名字","desc":"你在纸片上写她的名字，塞进一只空瓶，摆回架子。","hint":"她在外头等到天黑","tone":"warm","outcome":"管理员发现了，罚你把那一排架子擦一遍。你擦到手指发白，铜牌在胸口撞来撞去。母亲在塔外的台阶上等到天黑，没进来找，也没问为什么。那双薄底布鞋你穿回家，鞋底磨穿一个洞，她连夜给你补，补到半夜。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":""}}]},{"id":"sui2_m04","act":"main","age":[17,17],"mode":"dialogue","title":"差一截","opening":"医院在第九层，电梯里全是消毒水味，混着一点甜，是雾髓镇痛剂的味道。母亲躺在靠窗的床上，手背上扎着针，管子里一滴一滴。医生说越早置换越好，说排期在下个月，说费用还差一截。父亲蹲在走廊尽头，搪瓷缸里是散酒，酒味压过了消毒水。他今天话多，从码头的吊机讲到他二十岁扛过的盐包，一句一口。母亲摸你的手，说：别听你爸的，他喝多了。她的手比去年凉。","ask":"母亲说想回家，你先做什么","days":30,"npc":"father","memory":"走廊尽头的酒","choices":[{"title":"去办出院","desc":"你下楼办出院单，护士说排期作废，要重新等。","hint":"她那一夜睡得很沉","tone":"obey","outcome":"护士把单子推回来，让你签第二张。你签完上楼，父亲把搪瓷缸捏扁了，没骂你。回家那晚母亲睡得很沉，你守在床边听她呼吸。第二天早上她把药当成盐撒进了粥里，你吃了两碗，谁也没说破。排期再排上，是四个月以后。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"postponed_surgery","thread":"排期推到了四个月后"}},{"title":"说出还差多少","desc":"你站在床边，把还差多少、爸在借钱，全说了。","hint":"她把你的手抽了回去","tone":"honest","outcome":"母亲听完，把手从你手里抽出来，放在被子上，说：那就不做了。她那天没吃晚饭，护士来劝，她说胃不舒服。父亲半夜在阳台上抽烟，烟头一个一个摁在栏杆上。你回屋时听见她跟父亲说：别卖东西。父亲没应。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":3},"flag":"","thread":""}},{"title":"倒掉父亲的酒","desc":"你夺过搪瓷缸，把酒倒进洗手池，等他开口。","hint":"他说的那件事你没敢应","tone":"protect","outcome":"父亲愣住，随即笑了，笑得眼睛发红。他说他去问过价，码头三十年的记忆能换一半，说这话时手在裤子上擦。他还说：别跟你妈说。你点了头。回病房前你在楼梯间站了很久，听见楼下有人在喊号。第二天你开始打听另一种卖法。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":4},"flag":"father_offered_memory","thread":"你答应替父亲瞒着"}}]},{"id":"sui2_m05","act":"main","age":[18,18],"mode":"dialogue","title":"签在第三页","opening":"医院的走廊很白，护士让你在一张纸上签字。纸上的字你都认得，连起来却看不懂。签完你去了忆井广场。签约室在地下二层，桌上摊着七页合同，第三页是质押物清单，打着一行字：十六岁夏季，全段，含感官与情绪层，编号 B-1147。采集师把听膜推过来，说签这儿。你的外套搭在椅背上，衣角翻着，露出三个字。父亲跟在你身后，说去上个厕所，去了很久。","ask":"笔在你手里，你先想起什么","days":15,"npc":"father","memory":"十六岁的夏天","choices":[{"title":"留住那枚硬币","desc":"你要求留下买冰那枚硬币的记忆，只要这一件东西。","hint":"为这一件，价少了一截","tone":"keep","outcome":"采集师说可以，叫单点锚，要减价。你签了，父亲从走廊回来，在担保人那栏写了名字，写完把笔放下，手在裤子上擦。管子贴上太阳穴，像一条凉线爬进脑袋。醒来时天黑了，你手里攥着一枚旧硬币，磨得发亮，你不知道它是哪来的。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"爱":2},"flag":"kept_coin_anchor","thread":"你留着一枚不知来历的硬币"}},{"title":"签掉整段夏天","desc":"你在每一页上签字，最后一页按了手印，没抬头。","hint":"醒来时你数到十七","tone":"sell","outcome":"采集师数到十七，你就什么都不知道了。醒来时窗外全黑，桌上放着一张收据和一杯凉水。父亲坐在门口，见你睁眼，站起来又坐下，说：走吧。回家路上你问他今天几号，他说了，你算了算，少了一个夏天。你没觉得少了什么，这才是最怪的。","eff":{"bond":-2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":2},"flag":"sold_whole_summer","thread":""}},{"title":"叫父亲进来签","desc":"你走到走廊，把父亲叫进来，让他当着你的面签担保。","hint":"他把左手缩进了袖子","tone":"honest","outcome":"父亲进来，看了看合同，从口袋里摸出老花镜，镜腿用线缠着。他签得很慢，左手按纸，右手写。签完他把左手缩进袖子，说：别跟你妈讲。采集师笑了一声。出门你们在楼下各吃一碗面，谁都没提合同。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"father_signed_guarantor","thread":"你答应不告诉母亲"}}]},{"id":"sui2_m06","act":"main","age":[19,19],"mode":"dialogue","title":"这个年轻人是谁","opening":"母亲醒在第三天早上。术前医生说过，手术会拿走一段，拿哪段说不准。她先看窗，再看自己的手，看了很久，像在认。护士进来换瓶，把窗帘拉开一半，光落在被子上。她问：姑娘，我这是在哪儿。护士说医院。她点点头，忽然看见床尾的你，指了指，问护士：这个年轻人是谁。护士的手停在瓶子上，看了你一眼。","ask":"护士看着你，你先开不开口","days":20,"npc":"nurse","memory":"她问了句这是谁","choices":[{"title":"说我是阿砚","desc":"你往前走一步，说妈，我是阿砚。","hint":"她客气地请你坐下","tone":"honest","outcome":"她看着你，很礼貌地笑了一下，说：我儿子也叫阿砚，他今年八岁，左眉上有个疤。她把被子往上拉了拉，问你吃过饭没有，说医院的粥不好吃。你坐下，说吃过了。她点点头，转头看窗。你在床边坐到中午，她睡着了，手还搭在被子上，掌心朝上。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":2},"flag":"","thread":"她说阿砚左眉上有疤"}},{"title":"让护士替你说","desc":"你退到门外，让护士告诉她，这是你儿子。","hint":"她问儿子怎么没来","tone":"dodge","outcome":"护士出来说，她哦了一声，问儿子怎么没来。你说他忙。中午你进去，她正把饭里的肉挑出来，堆在碗边，说留给阿砚。你把那碗饭端去热，回来时肉还在。她问你：你是护士吧。你说不是。她想了想，说：那你是好人。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":1},"flag":"","thread":""}},{"title":"翻出那个衣角","desc":"你把枕边外套翻过来，指着衣角上的三个字给她看。","hint":"她摸完字，改摸你的手","tone":"warm","outcome":"她摸着那几个字，一个指头一个指头地摸。她说：这是我缝的。她抬头看你，眼神变了一下，只一下。她抓住你的手，说：你手怎么这么凉。你走时把外套留在她床上，穿单衣回去，夜里发烧两天。第二天她在纸上写你的名字，写了三遍，问护士这是谁。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":6},"flag":"she_touched_the_corner","thread":"她记得针脚，不记得人"}}]},{"id":"sui2_m07","act":"main","age":[26,26],"mode":"dialogue","title":"听别人的夏天","opening":"审计室在封存塔三层，没有窗，通风口里有雾髓的甜味。桌上摆着待核的瓶子，标签写着：某某，某年夏，全段。你戴上听膜，把里面的东西过一遍，看是否如标签。第一天核了十一瓶。第七瓶是一个女人卖掉的三岁女儿，你听见孩子唱一支跑调的歌，唱到一半停了。你摘了听膜，坐了会儿，接着核第八瓶。阿棠推门进来，两杯豆浆，说：你脸色像刚从雾里捞上来的。她笑了一下，笑完眼底那层青还在。","ask":"阿棠说这活干不长，你怎么答","days":60,"npc":"friend","memory":"核到第十一瓶","choices":[{"title":"递给她听膜","desc":"你把听膜塞给她，让她自己听一段，别说话。","hint":"她听完说这瓶是她收的","tone":"help","outcome":"她听了一半就摘了，说这瓶是她收的。她还说，她柜子底下压着一瓶客人的东西，两年没上交。你把那份核验单抽出来，签了自己的名，写了合格。她看着你签，没拦。从那天起，你们两个人守同一件事，谁都没再提。","eff":{"bond":5,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":3},"flag":"covered_atang","thread":"你替阿棠签了那张合格单"}},{"title":"照实写进报告","desc":"你把掺水的那瓶写进报告，连卖家姓名一起交上去。","hint":"父亲那晚没有喝酒","tone":"report","outcome":"报告交上去第三天，卖家的市民资格降了一级，是个在码头扛了半辈子盐包的老工人。父亲认识他，吃饭时听说了，筷子停了一下，说：你做得对。然后他进屋了，那晚没喝酒。你收拾碗的时候，发现他把酒坛的盖子扣得很严。","eff":{"bond":-3,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"reported_diluted","thread":""}},{"title":"改做无名瓶","desc":"你申请专核标签脱落、没人认领的那些瓶子。","hint":"这一格没人愿意干","tone":"niche","outcome":"上司同意了，因为没人愿意干。你给每一只无名瓶重新编号，记下里面的第一句话、最后一个动作。有一只是老太太在择菜，择到一半说起一个名字，说了三遍。你在备注栏写：疑似儿子。写完你想起母亲，把笔放下，去走廊上站了一会儿。","eff":{"bond":1,"health":0,"reputation":1,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":2},"flag":"audits_nameless","thread":""}}]},{"id":"sui2_m08","act":"main","age":[33,33],"mode":"dialogue","title":"标价十七倍","opening":"漂忆港在旧码头，退潮时滩上全是碎玻璃，踩上去咯吱响。摊子一个挨一个，东西不一样，价也不一样：有人卖初雪，有人卖一整个童年。雾从上层压下来，甜的，黏在喉咙口。你走在一排夏天的摊子中间，忽然停住。玻璃柜里横着一只瓶，标签发黄，编号 B-1147。价签用红笔写，数字后面加了三个零，是当初的十七倍。柜底有一层薄薄的白，像化了的冰。阿棠在你旁边，没说话。","ask":"摊主问你要不要，你怎么办","days":15,"npc":"friend","memory":"十七倍的价签","choices":[{"title":"报给鉴证师","desc":"你说这瓶来路不正，当场叫了港口的鉴证师。","hint":"瓶子被封进了公共库","tone":"report","outcome":"鉴证师来了两个，把柜子里的瓶子一只只登记。摊主被带走时回头看了你一眼，说：你有本事别来这行。阿棠说你这事做得对，又说：这下你更赎不回来了。瓶子进了公共库，编号还在，价签被撕了，柜台上留着一圈红笔印。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"reported_b1147","thread":"B-1147 被封进公共库"}},{"title":"抄下编号和价","desc":"你掏出本子，把编号、价钱、摊位号一笔一笔记下。","hint":"本子越记越厚","tone":"save","outcome":"你回家把本子塞进铁盒，铁盒是母亲装针的那个，盖子上有一道凹。从那天起你每个月往里头放钱，放完把盖子按紧。第二年漂忆港搬了地方，你又去找，摊子还在，价又涨了。你在本子上添了一行，写得比上回用力。","eff":{"bond":0,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"欲":2},"flag":"saving_for_b1147","thread":""}},{"title":"送母亲做延缓","desc":"你把攒的钱取出来，带母亲去做延缓，瓶子不赎了。","hint":"她多认了你两年","tone":"family","outcome":"支架做了两个钟头，她出来时握着你的手说想吃面。那两年她记得你的名字。第三年她先忘了你不吃葱，往你碗里撒了一把；过了半年，她问你今年十几；再后来把你的鞋当成她弟弟的，收进柜子。你路过漂忆港，不进去。","eff":{"bond":5,"health":-1,"reputation":0,"coins":-200,"stats":{"智识":1},"emotion":{"爱":4,"哀":4},"flag":"paid_for_mother_care","thread":""}}]},{"id":"sui2_m09","act":"main","age":[45,45],"mode":"dialogue","title":"只剩一半","opening":"赎回窗口在漂忆港最里头。你把合同复印件推过去，他对着灯看了很久，说：二十七年，最后一个月。瓶子调出来，编号 B-1147，跟十二岁那块铜牌一个号，装在一只纸盒里。阿棠在外头等，说：趁热，这玩意儿比记忆甜，还便宜。回家你把听膜贴上，听到第三段，声音断了。换一副，还是断。瓶里只到傍晚就没了，底下剩一层薄薄的白。合同背面有一行小字：提取时按浓度分装，浓者先售。","ask":"阿棠问要不要找剩下的一半","days":40,"npc":"friend","memory":"剩下一半的夏天","choices":[{"title":"跑遍漂忆港","desc":"你带着编号一家一家问，问到第四家，有人说浓的都进了私人柜。","hint":"那半瓶不拆卖","tone":"seek","outcome":"私人柜在城上层，雾最浓的地方，电梯要验三次记忆龄。你在楼下站了半天，没上去。回家你把半瓶放进缝纫机的抽屉，跟母亲的针盒、那枚旧硬币挨着。抽屉一拉开有股铁锈味。你后来每年开一次，不开听膜，只看一眼。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"欲":3},"flag":"","thread":""}},{"title":"放给母亲听","desc":"你把听膜贴到她耳边，让她听那段夏天。","hint":"听一次，瓶里薄一层","tone":"family","outcome":"听膜一贴，瓶里就薄一层。你还是让她听了。她听到中间伸手摸你的手，听完问：这是谁家的夏天。你说不知道。她点点头，说里头的蝉叫得好。第二天她把被子叠成方块，问你是哪家的师傅。你给她梳头，她一直看窗外。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":6},"flag":"","thread":""}},{"title":"摊开合同问他","desc":"你拿着合同去阳台，指着担保人那一栏问他。","hint":"他的字是用左手写的","tone":"honest","outcome":"父亲看了很久，咳嗽了两声。他说那年差的钱，担保人得签字。他怕你不肯，就趁你上厕所时签了。他说他这辈子只签过那一次假名字。你问他为什么用左手，他说右手抖。他把烟摁灭，说：你别怪我。你没说话，把合同折好，折得很慢。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":3},"flag":"knows_guarantor","thread":"父亲用左手签了担保"}}]},{"id":"sui2_m10","act":"main","age":[60,60],"mode":"dialogue","title":"归忆堂","opening":"母亲是立秋那天走的。走前三天不认人，只认得手，谁伸过去她就摸一摸，摸完说：凉。葬礼在城西归忆堂，塑料花上落了灰，角落点着雾髓香，甜得发闷。你穿着她缝的那件外套，衣角上三个字磨得只剩两个。净忆局送来一只小瓶，说是余忆，规定要在葬礼上放。司仪拧开瓶盖，她的声音很慢，叫的是你的小名：阿砚，饭在锅里，冰棍化了，你怎么才回来。","ask":"瓶子放完，司仪伸手来收，你","days":10,"npc":"friend","memory":"阿砚，饭在锅里","choices":[{"title":"要回那只瓶子","desc":"你说这瓶归家属，伸手从司仪手里拿回来，不松。","hint":"阿砚是她给你起的小名","tone":"keep","outcome":"你要回来，签了两张单子，一张交净忆局，一张自己收着。每年立秋你放一遍，第二遍声音就薄了，第五年只剩一句：饭在锅里。第八年你左耳听不清了，医生说别再听。你把瓶子挪到右耳边，还是听。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":7,"爱":5},"flag":"kept_funeral_bottle","thread":"瓶子一年比一年薄"}},{"title":"问是谁送来的","desc":"你拉住司仪，问这瓶哪年存的，为什么从没给过你。","hint":"底单在档案袋里等了十九年","tone":"ask","outcome":"司仪翻了底单，说十九年前她本人来存的，附一张纸，上面是她的字：等我走了再放，别提前给他。落款写得歪，最后一笔拖得很长。你把纸折起来放进内袋，出门时忘了拿伞，雨落在塑料花上。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":7,"爱":3},"flag":"knows_she_filed_it","thread":"她十九年前就写好了那张纸"}},{"title":"照规矩封存","desc":"你把手收回来，说按规定办，封存，别放了。","hint":"阿棠在门口站了很久","tone":"rule","outcome":"司仪把瓶子装进布袋，登记，让你签了名。亲戚散的时候有人低声说这儿子心硬。阿棠帮你收塑料花，收到一半说：她这辈子就攒下这一句。你说我知道。她把纸箱搁在门口，先走了。你在空屋里坐到天黑。","eff":{"bond":-4,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"怒":2},"flag":"sealed_residue","thread":"她最后那句被装进布袋"}}]},{"id":"sui2_m11","act":"main","age":[74,74],"mode":"montage","title":"不收记忆","opening":"七十四岁这年，净忆局来信，说你的记忆龄不足，要重新申请市民资格。附表有一栏：可支配记忆，请勾选愿交出的部分。阿棠的店在旧码头，门口挂一块木牌：不收记忆。她前年走了，店留给你。门后挂着母亲那件外套，衣角上只剩两个字。你在半瓶里听见十六岁的自己说：你别老摸我手了，热。她在余忆里记的你，蹲下来握她的手，说：妈，你手怎么这么凉。同一个下午，你们记成了两个人。","ask":"表在你手里，你勾哪一栏好","days":200,"npc":"","memory":"最后一个夏天","choices":[{"title":"交上半瓶夏天","desc":"你在表上勾了十六岁夏天，把剩下的半瓶也交了出去。","hint":"办事的人说这段不值钱","tone":"practical","outcome":"办事的年轻人抬头看了你一眼，说这段不完整，折不了多少。你说我知道。他给你换了一张临时市民证，纸的，压一层膜。你走出门，天有点阴，雾从街口漫过来。你忽然想不起母亲的缝纫机是什么颜色，站住想了很久，没想起来。","eff":{"bond":-2,"health":2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":6,"惧":3},"flag":"surrendered_memory","thread":""}},{"title":"摆两瓶在柜台","desc":"你把 B-1147 和她的小瓶并排摆在柜台上，写：非卖。","hint":"有小孩进来问那是什么","tone":"keep","outcome":"你找两块干净布把瓶底擦了一遍，标签自己写，字有点抖。有小孩进来问这是什么，你说：两个人的夏天。小孩问哪个是好的，你说都不好，也都不坏。一个月后信又来催，你没回，市民资格停了，配给也停了。你把门上的木牌翻过来，背面有阿棠写的一行：开了就别关。","eff":{"bond":3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"爱":5,"哀":3},"flag":"kept_both","thread":""}},{"title":"去封存塔查他","desc":"你带着余忆的编号去封存塔，查那个少年的档案。","hint":"系统里没有这个人","tone":"seek","outcome":"窗口的人查了三遍，说系统里没有这个编号，也没有这个人的脸。你说再查查。他说老太太的余忆里常有这种，是他们自己缝出来的人。你回家，把那个少年的样子画在纸上：十六岁，头发湿的，站在门口。画得不像，你还是贴在了柜台后头。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":3},"flag":"he_was_never_registered","thread":"她记得的那个人没有档案"}}]}],"side":[{"id":"sui2_s01","act":"side","age":[8,8],"mode":"narration","title":"养出来的童年","opening":"母亲把二十件工装摊在膝上，一件一件对齐衣角，你跟她进城北的玻璃棚。棚后头有间小屋，地上铺草席，墙角码着一排空瓶，瓶底一层薄白。屋里坐着一个和你差不多大的男孩，戴听膜，面前一只瓶，标着 K-032。管事的说这叫养童年，养到十二装瓶，卖给上头那些没有小时候的人。男孩摘下听膜问：你妈打你吗。你说打。他说他那个妈不打，只给他剥橘子，剥得很慢。他问橘子什么味。你说酸的。他说：我的是甜的。","ask":"他等着你说话，你先做什么","days":20,"npc":"","memory":"瓶底的橘子籽","choices":[{"title":"摘下他的听膜","desc":"你把听膜摘了，跟他讲你妈的手、衣角上的字，讲到天黑。","hint":"出来时你忘了那个下午","tone":"warm","outcome":"你讲一句，他学一句，学你妈叫你的腔调，两个人都笑。管事的来撵人时，他已经把你的话记住了大半。出门雾灌进鼻子，甜得发腻，那个下午你讲了什么，后来一句也想不起来，只记得嗓子哑了三天。第二年你再去，K-032 那格空了，管事的说装瓶出货了。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"你记不住自己讲过的那个下午"}},{"title":"去告诉管事","desc":"你拉着管事的袖子说，那是个孩子，不是样品，不能装瓶。","hint":"他提前三个月出了货","tone":"report","outcome":"管事的笑了一声，说这孩子的身子四岁就押给温室了，押到十二。第二天来了两个穿灰衣服的人查资质，温室怕生事，把 K-032 提前装了瓶。男孩被抬走时还戴着听膜，手在空气里抓。管事的说：你要是不多那句嘴，他还能在这儿养到十二。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":3},"flag":"reported_cultivated_child","thread":"他提前三个月被装瓶"}},{"title":"戴上他的听膜","desc":"你把听膜扣在自己耳朵上，想尝一口他说的那种甜。","hint":"你从此记得一只没养过的狗","tone":"greed","outcome":"里面是一个下午：有人剥橘子，剥得很慢，一只黄狗趴在门槛上，蝉在叫。甜味顺着耳根化开，比雾还甜。你把听膜还给他，回家路上一直咽口水。后来你妈给你剥橘子，你嫌她剥得不对。很多年里你都记得那只黄狗，记得它叫来福，你从来没养过狗。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"喜":2,"欲":3},"flag":"tasted_cultivated_child","thread":"你记得一只没养过的黄狗"}}]},{"id":"sui2_s09","act":"side","age":[9,9],"mode":"narration","title":"入伏的柿子树","opening":"入伏头一天，忆井广场的雾最薄，日头一晒，甜味就从地缝里往上冒，黏在嘴唇上。母亲给东头的裁缝送线，让你在台阶上等。台阶上坐着一个老太太，蓝布衫，手背上生着褐斑，膝头一只布袋，袋口露出一角手绢。她拉住你的袖子，让你替她看瓶上的字。摊主老柯从柜里取出一只瓶，瓶身一道白痕，编号 D-2071，标签写着：七岁，院子，柿子树，全段十二分钟。她说：就这个，我每年听一回。","ask":"她把一把铜子放在你手心，你怎么办","days":20,"npc":"","memory":"十二分钟的院子","choices":[{"title":"陪她坐到日头落","desc":"你把听膜替她扣好，坐在旁边扶着瓶，一直扶到天黑。","hint":"回家时母亲找了你半条街","tone":"escort","outcome":"她听到第九分钟手就抖了，抓着你的手腕，抓出四道红印。听完她把瓶还回去，说：这院子我认得。日头落了，广场的灯一盏一盏亮，母亲从街那头跑过来，第一次打了你一巴掌，打完又把你抱起来。第二年入伏她又来，隔着两排摊子朝你抬了抬下巴。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"母亲第一次打了你"}},{"title":"说这院子不是她的","desc":"你指着标签说，这上头没她的名字，院子是别人的。","hint":"第二年那张小板凳空着","tone":"honest","outcome":"她把手绢叠好塞回袋里，说：我知道。她把铜子一枚一枚数给老柯，数完站起来，走得比来时慢。老柯等她走远，低声说你多嘴。第二年入伏，那张小板凳空着。过了几年你听说，养老层有个姓吴的老太太，把每月配给的遗忘都攒着没领。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":1},"flag":"told_wu_truth","thread":"她攒着遗忘没领"}},{"title":"拿余钱买两根冰","desc":"你替她数完，把多出的几枚铜子揣进兜，跑去买冰。","hint":"那几个铜子你一直没还","tone":"greed","outcome":"冰是桂花味的，甜和广场上的甜混在一起，分不清哪个是哪个。你回来时她已经走了，小板凳上留着一小片撕下来的手绢角。你把冰棍纸塞进台阶缝，回家没提。往后每年入伏你都在台阶上坐一会儿，等一个穿蓝布衫的。铜子你留着，一直没花。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"欲":2},"flag":"","thread":"你留着几枚不属于你的铜子"}}]},{"id":"sui2_s02","act":"side","age":[11,11],"mode":"narration","title":"小学全段","opening":"开学第三个星期，同桌陈果没来。第四天他来了，人瘦了一圈，坐下就问：咱们现在是一年级还是三年级。他妈妈站在校门口，跟一个穿灰衣服的人签一张纸，纸角露出四个字：小学全段。老师进来，让大家别跟他提从前上过的课，说提了对他不好。陈果从书包里摸出一只空瓶，瓶底一层白，瓶身有一串编号，磨得看不清，凑近闻还有点甜。他小声问你：去年冬天，我是不是借过你一块橡皮。","ask":"他把空瓶推过来，你先做什么","days":30,"npc":"","memory":"瓶底的一层白","choices":[{"title":"一件一件讲给他","desc":"每天中午你给他讲一件从前的事：橡皮、下雪、老师那把尺。","hint":"你的算术掉到及格线下","tone":"warm","outcome":"你讲一件，他记一件，记在空瓶的标签背面。讲到第三个月，他家里又来签了一张纸，说记住的要紧，押得更贵。期末他没来考试。很多年后你在招工的队伍里看见他，他认不出你，忽然说：我小时候好像有人给我讲过下雪。你说是我。他说：哦。队伍往前挪了。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1,"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"他记得下雪，不记得你"}},{"title":"去告诉班主任","desc":"你把那张纸上的字抄下来交给班主任，说陈果被押了。","hint":"全班都知道了是谁说的","tone":"report","outcome":"第二天净忆局来了两个人，把陈果带去重定记忆龄，他妈妈的市民资格停了一年。他转学那天在校门口站了会儿，问你：老师为什么那样看我。你说不知道。秋天开学，你的书包被人扔进雾沟，捞上来时课本全软了。你做得没错，可这个班上再没人跟你同桌。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":4},"flag":"reported_chenguo","thread":"他在校门口问过你一句"}},{"title":"求老师换座位","desc":"你举手说看不清黑板，搬到最后一排靠窗，不再回头。","hint":"毕业照上他的位置空着","tone":"distance","outcome":"老师给你换了座，陈果的新同桌是个不爱说话的女生。期末你考得不错，母亲被请去学校，回来给你煮了两个蛋。毕业照洗出来，他站的那一格是空的，因为那天他已经被除名。照片你一直收着，搬了三次家都没丢，也没再打开看过。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"毕业照上空着一格"}}]},{"id":"sui2_s10","act":"side","age":[15,15],"mode":"narration","title":"育室最后一排","opening":"温室在城北，玻璃顶上一层水，一晒往下掉，落进脖子里是凉的。你穿着母亲缝的褂子，衣角翻着，替她送工装。管事让你留下改袖口，管两顿饭。育室在最末一排架子后头，推门进去，甜味更浓，浓到发苦。屋里坐着一个女人，三十来岁，戴听膜，面前一排小瓶，瓶签上写着：母亲·早、母亲·夜、母亲·手。她见你进来就站起，摸你的手，摸完说：凉的。她说话很慢，一句和一句之间要停一停。","ask":"她把手放回膝上，等你再开口","days":20,"npc":"","memory":"母亲·夜那只瓶","choices":[{"title":"坐下让她练手","desc":"你把手放回她掌心，随她一遍一遍叫你的名字。","hint":"你回头时慢了半拍","tone":"warm","outcome":"她练了四天：叫你的名字，说饭在锅里，说天凉了加件衣裳。到第四天她已经很像，像到你想应一声。屋角那排瓶一直亮着，管事在门口看了会儿，在本子上记了一笔。月底你拿到两顿饭钱，回家路上你妈在巷口叫你，你回头慢了半拍才应。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"惧":2},"flag":"practiced_as_son","thread":"你回头慢了半拍"}},{"title":"告诉她实情","desc":"你说你不是谁的妈，你是雇来的，工钱按天算。","hint":"那间育室换了人","tone":"honest","outcome":"她把手收回去，摘下听膜，问：那我儿子呢。你说那是别人的儿子。第二天她结了工钱走了，孩子在走廊里哭了三天，嗓子哑了。管事扣你半月工钱，说这间育室要重开。三个月后你在洗衣房看见她，手泡得发白，正一只一只刷瓶，见你也没认出来。","eff":{"bond":-3,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"told_surrogate_truth","thread":"那孩子在走廊里哭了三天"}},{"title":"把那只瓶带走","desc":"你趁她去打水，把母亲·夜那只瓶揣进褂子里。","hint":"那是你自己那个下午","tone":"sneak","outcome":"她少了这一段，考核那天叫不出孩子的名字，被调去洗瓶子。你回家贴上听膜，听见的却是自己那个下午：她在学你妈的口音，一句一句，学得很准，连停顿都一样。你听到第三遍，把瓶塞进床底。往后十几年你搬了几回家，那只瓶一直带着，标签朝里。","eff":{"bond":-1,"health":-1,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"欲":2},"flag":"stole_mother_night","thread":"床底那只母亲·夜"}}]},{"id":"sui2_s03","act":"side","age":[21,21],"mode":"narration","title":"霜降那晚","opening":"忆井广场的赎回窗口在负一层，冬天开暖气，甜味顺着通风口一阵阵往下掉。霜降那天，修鞋的老周准时来，蓝布围裙上沾着鞋油。他递进一张折成四折的纸，编号 C-0912，质押物写着：二十岁，初恋，全段。他每年赎一晚，第二天一早再押回去，像租一件衣裳。今年窗口换了新规矩，要验记忆龄做担保，他差两年。他把手在围裙上擦了两遍，说：小同志，就差一点。","ask":"他隔着窗口看你，你怎么办","days":15,"npc":"","memory":"编号C-0912","choices":[{"title":"拿自己的年限担保","desc":"你在担保栏签下自己的名字，抵两年记忆龄，让他进去。","hint":"你的档案上多了一道记录","tone":"protect","outcome":"他进去前把围裙解下来叠好，放在窗口台上。第二天天没亮他出来，眼睛肿着，把瓶子重新押了，押金刚好够他老婆一年的药。你那份担保跟着档案走，招考时被人事翻出来问过两回。他后来每年霜降还是来，见你就点一下头，从不多话。你不知道他还认不认得你的脸。","eff":{"bond":4,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":4},"flag":"guaranteed_zhou","thread":"你的档案上留了一道记录"}},{"title":"照新规关窗","desc":"你说差一年也不能赎，到点把铁帘拉下来，没抬头。","hint":"他在台阶上坐到天亮","tone":"rule","outcome":"铁帘落到底，外头没动静。第二天清早你开门，台阶上有一小堆瓜子壳，摆得整整齐齐。他老婆拎着饭盒来接他，两个人一前一后走了。年底清库，C-0912 到期无人续押，划进公共库，名字刮掉，编号留着。你后来在清单上看见它，手指在那行字上按了一下。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":2},"flag":"closed_on_zhou","thread":"C-0912 进了公共库"}},{"title":"跟他进听室","desc":"你说要登记，跟着进去，在隔间扣上第二副听膜。","hint":"你记住了别人初恋里的名字","tone":"greed","outcome":"里面是一个夏天的傍晚，一个姑娘骑车过来，车铃响了两下，喊了一个名字。西瓜切开的味道，蝉在叫。你摘了听膜，手心是湿的。他什么都不知道，第二天照旧把瓶子押回去。往后几年你听见有人叫那个名字，会回头。你从来没跟他提过那一晚，也没跟自己提过。","eff":{"bond":0,"health":0,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"欲":4,"哀":2},"flag":"listened_zhou_bottle","thread":"你记住了别人初恋里的名字"}}]},{"id":"sui2_s11","act":"side","age":[23,23],"mode":"narration","title":"给拿走夏天的人","opening":"二十三岁那年你在封存塔做临时工，活儿是给旧瓶换标签：揭下脆纸，写上新号，再蒙一层膜。五层没有窗，通风口一直响，甜味一阵一阵往下沉，落在舌根上发苦。老师傅说这一层都是死档，人早走了，瓶还在。你揭到第七排第十九格，封套里掉出一张纸，折成四折。信封上写：给拿走这个夏天的人。字歪，横画尾巴翘起来，是你自己的字。","ask":"信在你手里，你拿它怎么办","days":30,"npc":"","memory":"给拿走夏天的人","choices":[{"title":"照信上说的做","desc":"每年立秋买一支桂花冰，放在母亲窗台上。","hint":"转正推到了第三年","tone":"family","outcome":"信里只写了两件事：每年立秋给她买一支桂花冰；别让她知道你卖了什么。你照做。她坐在窗边吃，吃到木棍上只剩一点甜，问你哪来的，你说路上买的。为了每年那一天，你请假，转正推到第三年。她从没问过第二遍，也从没剩过一口。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{},"emotion":{"爱":4,"哀":3},"flag":"followed_old_letter","thread":"每年立秋那一支冰"}},{"title":"去查经手的人","desc":"你按瓶号查到当年的采集师，姓聂，写了报告。","hint":"他家里有个做透析的女儿","tone":"report","outcome":"查下来他压了三成价，也没提合同背面那行小字。报告交上去，他被吊销资格，走的那天在塔下等你，说：你做得对。他说家里有个女儿在做透析，说到这儿就不说了。你说了句对不起。往后每年冬天，他女儿都在塔下站一会儿，不见你，站到雾起来就走。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"reported_collector_nie","thread":"塔下每年冬天站着一个人"}},{"title":"原样封回去","desc":"你把信折回封套，塞进架子最里头，登记时写无。","hint":"你那年就转了正","tone":"keep","outcome":"登记本上那一格你写：附属物无。第二年你转了正，有了工号，进了三层那间没有窗的审计室。往后每到立秋，你嘴里就发苦，想不起为什么。有一年你跑遍全城的冷饮摊，问有没有桂花味的，摊主都摇头。你站在街口，觉得少了点什么，站了一会儿就回去了。","eff":{"bond":0,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"refiled_letter","thread":"每年立秋嘴里发苦"}}]},{"id":"sui2_s04","act":"side","age":[25,25],"mode":"dialogue","title":"漏雨的下午","opening":"阿棠的店在旧码头，屋顶漏，雨一大就往柜台上滴。她踩在凳子上补瓦，让你在底下扶。她穿一件洗白的褂子，袖口磨破了，抬手时露出一截腕子。她说：再往上一点。你扶着凳腿，手心出汗。她下来时踩空半格，你伸手，她抓住了，两个人都没说话。柜子底下压着一只瓶，标签朝里，只露出半截编号。外头雨停了，雾从门缝钻进来，有点甜。她拍拍手说：饿了，下面。","ask":"她背对着你烧水，你做什么","days":10,"npc":"friend","memory":"两碗面的早上","choices":[{"title":"替她守这一夜","desc":"你说锁坏了，抱一床旧毯睡在门内，让她上楼去。","hint":"第二天的考试你没去成","tone":"protect","outcome":"水泥地凉，夜里落了潮，你睡到一半听见她在楼上翻身。天亮她端两碗面下来，一碗多搁了葱，说：你打呼。你腰疼了半年，那年的资格考没去成，名额顺到第二年。她后来提过一次，说那晚要没你，柜子底下那只瓶就保不住了。你没问那瓶是谁的。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"惧":1},"flag":"guarded_atang_shop","thread":"柜子底下那只瓶是谁的"}},{"title":"把话说明白","desc":"你叫住她说阿棠我想跟你过，话没说完她抬手打断。","hint":"她从此不让你留到打烊","tone":"confess","outcome":"她笑了一下，笑到一半收住，说：我这行当，早晚得卖自己一段，你别把自己搭进来。她蹲下去把柜底的瓶搬出来给你看，标签上是个女孩的名字，两年前死的，她一直没上交。她说：我留着它，是怕我哪天也卖。那天你们把面吃完，各自回去。往后她关门早了一刻钟。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":4,"哀":3},"flag":"told_atang","thread":"她关店早了一刻钟"}},{"title":"夜里来修屋顶","desc":"你半夜拎着沥青和瓦片上房，把漏处补好，锁也换了。","hint":"她一直以为是房东修的","tone":"repair","outcome":"你补到后半夜，沥青滴在衣角上，正好盖住那三个字。她第二天照常开门，抬头看了看屋顶，说：怪了，不漏了。一月后她给你一只搪瓷缸，说房东倒是有良心。你说嗯。那件褂子上的沥青洗不掉，你穿了很多年，衣角那三个字只剩两个还看得清。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"她以为是房东修的"}}]},{"id":"sui2_s05","act":"side","age":[29,29],"mode":"narration","title":"忘礼","opening":"忘礼在净忆局二楼办。屋子小，两把椅子对着放，中间一张长桌，桌上排着一列瓶，一年一瓶，瓶身用白笔写着年份，瓶底都刻着编号，一个挨一个。墙上贴着规程：逐段剥离，不得跳段，末瓶封存。何女士先坐下，手袋放在膝上。方先生站着，等你说开始。第一瓶是他们结婚那年，瓶口漏出一点甜味，像放过糖的水。最末一只没写年份，只写一个囡字。","ask":"两个人都看着你，你先做什么","days":20,"npc":"","memory":"末瓶上写一个囡","choices":[{"title":"照着单子剥","desc":"你按年份一瓶一瓶念，念完一瓶剥一瓶，中间不停。","hint":"她让你替她记着顺序","tone":"rule","outcome":"剥到第七瓶，何女士说停一下，方先生说继续。你看了看规程，继续。最后一只封进铅盒，登记，盖章。两个人一前一后出门，谁也没等谁。她在门口回头，说：同志，顺序你替我记着。你点头。那张单子你收在抽屉里，很多年没扔，也没再打开。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"conducted_wangli","thread":"她让你替她记着顺序"}},{"title":"先放一遍再剥","desc":"你说规程没禁听，把每只瓶放一遍，让他们自己喊停。","hint":"你的记录上写了程序不当","tone":"peace","outcome":"放到第三瓶，两个人一起笑了，笑完都不说话。放到第七瓶，何女士伸手过去，方先生把手放在她手背上。他们说今天就到这儿。上司扣了你半月配给，记录上写着程序不当。两年后他们又来，把剩下的剥完，坐得比上回近。他们没点名要你，你也没过去。","eff":{"bond":1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"delayed_wangli","thread":"他们两年后又来了一趟"}},{"title":"换下最后那只","desc":"你把囡字那瓶揣进外套，换上一只空瓶，登记封存。","hint":"她后来回来问过一句","tone":"keep","outcome":"前一晚方先生在楼梯间塞给你一张纸条，四个字：留着，别剥。瓶子贴着肋骨，走路时一下一下撞。三个月后何女士一个人回来，站在窗口问：那天有没有剩下什么。你说没有。她站了一会儿，说：那就好。她走进雾里。那只瓶一直在你柜子最里头，你没听过。","eff":{"bond":0,"health":0,"reputation":-2,"coins":0,"stats":{"机缘":1},"emotion":{"哀":4,"爱":2},"flag":"kept_nv_bottle","thread":"柜子最里头那只囡字瓶"}}]},{"id":"sui2_s12","act":"side","age":[30,30],"mode":"dialogue","title":"摘牌那天","opening":"阿棠的店在旧码头，门口那块木牌挂了六年，漆掉了一半，还认得清五个字：不收记忆。关店那天落雨，屋顶是新补的，一滴不漏。她站在凳子上把牌子摘下来，让你在底下接。架子上的瓶一只一只取下来擦，标签朝外，编号都用白笔描过一遍。擦到最底下一格，她的手停了停，说：柜底那只，我上个月卖了。她说得很轻，像说别人的事。屋里甜味重，雨在外头，她把抹布绞了两遍。","ask":"她说卖都卖了，你怎么接话","days":15,"npc":"friend","memory":"摘下来的木牌","choices":[{"title":"去把那瓶赎回来","desc":"你按她说的买家找过去，把攒了七年的钱全推上桌。","hint":"你的号又远了一截","tone":"protect","outcome":"买家是个开私人柜的，验过你的记忆龄才让你进门。瓶拿回来，编号还在，玻璃上多了一道新划痕。你不敢给阿棠，把它塞进缝纫机的抽屉，跟母亲的针盒挨着。她问过一回赎回来没有，你说没有。你攒的年限空了，B-1147 的价那年又涨了一轮。","eff":{"bond":3,"health":-1,"reputation":0,"coins":-200,"stats":{"机缘":1},"emotion":{"爱":3,"哀":3},"flag":"redeemed_atang_bottle","thread":"抽屉里那只瓶不是你的"}},{"title":"陪她去登记","desc":"你说服她去净忆局把这一单如实登记，罚轻些。","hint":"木牌被摘了，店还在","tone":"rule","outcome":"罚了三年配给，资格降一级，那块木牌被摘走，说是不合规程。她站在门口看他们摘，没拦。回去的路上她说：你不该这样。可每年冬天她还是给你留一碗面，面里多搁半勺猪油。她再没提过柜底那只瓶，也没再上过二楼。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"registered_atang_sale","thread":"她每年冬天留一碗面"}},{"title":"接过钥匙开门","desc":"你什么也不问，接过钥匙，第二天照常把门打开。","hint":"三个月后她回来买瓶","tone":"keep","outcome":"你把货架擦了一遍，把牌子的漆补上，字照旧。她三个月后回来，站在门口看那块牌，问：这店卖什么。你说卖瓶。她说：那给我一段开店的下午。你在架上找了一只别人的下午卖给她，她听完说：这店不错。她走的时候没回头，你听见雨点落在新补的瓦上。","eff":{"bond":-1,"health":0,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"哀":5,"惧":2},"flag":"sold_atang_a_fake","thread":"她听过一个假的下午"}}]},{"id":"sui2_s06","act":"side","age":[38,38],"mode":"narration","title":"出质人一栏","opening":"走廊那头的库房在销毁旧瓶，甜味从门缝渗进来。审计室在封存塔三层，没有窗。新到一批旧合同要录进系统，纸都发脆，翻页得用竹片。你翻到第七份，手停住。出质人一栏写着：柳素云。质押物一栏是：儿子第一天上小学，全段，含晨光与气味层。日期是你七岁那年九月。背面有一行小字：用于学杂费与一只蓝布书包。你把纸举到灯下，签名旁边有一点褪色的红，是手印。","ask":"这张纸在你手里，你先做什么","days":60,"npc":"","memory":"出质人柳素云","choices":[{"title":"把这一份抽出来","desc":"你把那份合同折成四折，塞进外套内袋，没进系统。","hint":"老陈替你去守了地下室","tone":"hide","outcome":"那批合同少了七页，对不上号。老陈被叫去问了三回，后来调去地下室理旧档，走那天把搪瓷缸留给你。合同在你内袋里放了一个月，又挪进缝纫机的抽屉，跟针盒挨着。你每次开抽屉都听见纸响。老陈后来在楼下遇见你，还点头，你也点头，两个人都没停。","eff":{"bond":0,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"恶":2},"flag":"hid_mother_contract","thread":"老陈替你去了地下室"}},{"title":"拿着它去问她","desc":"你把复印件摊在饭桌上，指着出质人那三个字。","hint":"她不再让你替她梳头","tone":"honest","outcome":"她看了很久，说这不是我写的。你把纸翻过去，让她看那个手印。她把手缩回袖子里，问：阿砚是谁。你说是我。她说：我儿子才八岁，他一会儿放学。她把纸叠得整整齐齐，推回你面前，说：你走吧，门带上。第二天她隔着门说头发自己梳过了。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"怒":2},"flag":"showed_mother_contract","thread":"她开始自己梳头"}},{"title":"把整批都调出来","desc":"你按她的名字检索，一共十一份，一段一段往下看。","hint":"你只赎得起两段","tone":"seek","outcome":"十一份，从你七岁到你十六岁：第一天上学、第一次换牙、学骑车、肺炎那年。你攒的钱只够赎两段。你挑了第一天上学，回家放给她听。她听完说：书包是蓝的，上头有只鸭子。你一直以为是灰的。剩下九份还压在库里，年年涨。你从此不敢算总数。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":3,"哀":5},"flag":"found_eleven_contracts","thread":"还有九段压在库里"}}]},{"id":"sui2_s13","act":"side","age":[40,40],"mode":"narration","title":"走廊上的硬币","opening":"四十岁那年秋天，审计室来了个姓霍的女人，灰呢外套，手袋的铜扣开了又扣，扣了十七八回。她要办的是童年全段清除，对象是她十岁的儿子。她说：他记得不该记的事。材料袋里一只瓶，编号 G-3088，标签上写着：童年，十岁，含父层。按规程，十二岁以下要当面做意愿确认。孩子被带来，坐在走廊长凳上，两只鞋来回蹭地，手里转一枚旧硬币，转一下，接住，再转。","ask":"孩子抬起头看你，你先问什么","days":20,"npc":"","memory":"G-3088 那只瓶","choices":[{"title":"改成封存待成年","desc":"你在系统里改了这一格，责任栏签上自己的名字。","hint":"你被停职半年","tone":"protect","outcome":"她被叫去谈了三回，最后签字同意。孩子在走廊上把那枚硬币放在你桌上，说：这个给你。你被停职半年，复职后调去地下室理旧档，工号后面加了一个字母。八年后那孩子满十八，来窗口办过一次手续，没认出你，只问：这儿以前是不是有个姓沈的。你说有。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":3},"flag":"sealed_boyhood","thread":"桌上那枚不是你的硬币"}},{"title":"把他的话说进去","desc":"你把孩子那句我不想忘写进确认书，按了手印。","hint":"他被送去了寄养层","tone":"report","outcome":"未成年人保护科当天来了人。他母亲在楼下骂了半个钟头，最后被两个穿灰衣服的带走问话。孩子上车前回头问你：是不是我做错了。你说不是。他点头，硬币攥得很紧。后来你查过他的档案，转学三次，十八岁那年自己申请改了姓。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":3},"flag":"reported_huo_child","thread":"他问过是不是自己做错了"}},{"title":"签字收下那笔钱","desc":"你在清除单上签了字，把那一段标成自然衰减。","hint":"母亲三年延缓的钱有了","tone":"greed","outcome":"钱到账那天你去交了母亲三年的延缓费，收据折好放进铁盒。孩子没有再来过。第二年春天你在街上看见他们母子，孩子牵着她的手，叫得很顺口。你站在卖冰的摊子前，站得有点久，摊主问你要什么，你说不上来。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":150,"stats":{"机缘":1},"emotion":{"喜":2,"恶":3},"flag":"deleted_huo_childhood","thread":"街口那个卖冰的摊子"}}]},{"id":"sui2_s07","act":"side","age":[49,49],"mode":"dialogue","title":"讲不通的下午","opening":"母亲七十一岁那年，耳朵还很好，先听出你上楼的脚步。缝纫机边上立着一只旧瓶，里头插着针。你带了一只铁盒，里头是那件外套的衣角、三张照片、一枚旧硬币，还有一张合同复印件。她给你倒糖水，自己那碗不放糖。你说：妈，你十七岁那年病过一场，后来忘了一些事。她点点头，说人老了都这样。你往下说，说你叫什么，说她给你缝过什么。她听得很有礼貌，像听一个上门修水管的人讲他自己的家。","ask":"她把糖罐盖上，你接着说什么","days":15,"npc":"mother","memory":"她那碗没放糖","choices":[{"title":"顺着她的话演","desc":"你说自己是阿砚的同事，他忙，让我来看看您。","hint":"每次去你都换个身份","tone":"obey","outcome":"她松了口气，从柜里翻出一件毛衣，说织小了，让我儿子穿，你带给他。你抱着毛衣回去，袖子只到你手腕。你穿了三天，第四天脱下来叠好放进柜子。下回去，她又问：你是哪个单位的。你说街道的。她说：街道的好。她伸手摸了摸你的手，说：怎么这么凉。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":4},"flag":"played_colleague","thread":"柜子里那件小毛衣"}},{"title":"把照片摊开","desc":"你把照片一张张摆上桌，指着上头的脸，一张一张认。","hint":"她开始把硬币藏起来","tone":"honest","outcome":"她一张一张看，看到第三张站起来，碰翻了碗，糖水流到桌沿往下滴。她说：你把我儿子怎么了。她走到门口喊邻居，声音很响。你退到楼道里，听见门在里面插上了。晚上社区打来电话问情况，你解释了半个钟头。第二天她把那枚硬币藏进米缸，你看见她藏，没说话。","eff":{"bond":-5,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":6,"惧":4},"flag":"frightened_mother","thread":"她把硬币藏进了米缸"}},{"title":"收好盒子明天来","desc":"你不说了，把桌上的糖水擦干净，说明天再来看您。","hint":"本子越记越厚","tone":"wait","outcome":"她问这盒子是谁的。你说是朋友的，先放这儿。她说放窗台上，别挡道。第二天你又来，从十七岁讲起，她还是听到八岁就停下。你开始记本子：今天讲到哪儿，她问了几遍。本子写到第四十页，她还在八岁。你翻回去看，发现自己也记不清十七岁那年的夏天了。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"爱":3},"flag":"keeps_visiting_log","thread":"本子写到第四十页"}}]},{"id":"sui2_s14","act":"side","age":[55,55],"mode":"dialogue","title":"同志，你找谁","opening":"她这些年认人有个次序：先摸手，再摸衣角，最后才抬眼。这天早上你提着菜上楼，敲门，她来开，手先伸过来，把你的手翻过来看了看，又捏了捏你的衣角，捏到那三个字磨剩的两个。她抬眼，看了很久，说：同志，你找谁。楼道里的灯闪了一下。她身后的小桌上立着一只瓶，里头插着针；甜味从厨房飘出来，是糖水滚了的味道。","ask":"她的手还搭在门上，你怎么办","days":30,"npc":"mother","memory":"她问同志你找谁","choices":[{"title":"带她回老屋","desc":"你请了长假，把她带回城最底下那层的老房子。","hint":"岗位让人顶了","tone":"family","outcome":"老屋还在，窗台上有她磨出来的一个凹。你把她按在缝纫机前坐下，她的手自己去找踏板，踩了两下。傍晚她忽然叫了一声阿砚，就一声，接着问你晚饭吃什么。回城以后她又忘了。你的岗位让人顶了，回去做临时工。那一声你记了很多年，越记越不敢确定。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":5,"哀":4},"flag":"took_mother_home","thread":"那一声越记越不敢确定"}},{"title":"办记忆龄重定","desc":"你带她去窗口重定记忆龄，从此她归你监护。","hint":"她的市民证被收走了","tone":"practical","outcome":"排了一上午，签字，按印，她的市民证被收走，档案上盖了一个蓝印。配给、吃药、挂号都顺了，你也不用再跟人解释你是谁。她坐在大厅长椅上，把那张表格折成一只小船，折得很整齐，放在膝盖上，一直坐到叫号。回家路上她问你：船什么时候开。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"爱":2},"flag":"guardianship_mother","thread":"她膝盖上那只纸船"}},{"title":"在表上写无亲属","desc":"你在养老层的登记表上写下无亲属，把地址留了。","hint":"你从侧门进去看她","tone":"distance","outcome":"写完那一栏，笔尖在纸上顿住，留下一个墨点。她住进去第三个月就不再问门口是谁。你每月去看一次，从侧门进，坐在她对面削一个苹果，皮不断。她吃得很慢，吃完说：谢谢你啊，小伙子。护工说她记性其实不错，就是不肯说自己姓什么。","eff":{"bond":-4,"health":1,"reputation":-1,"coins":0,"stats":{},"emotion":{"哀":6,"惧":2},"flag":"no_kin_form","thread":"她不肯说自己姓什么"}}]},{"id":"sui2_s15","act":"side","age":[70,70],"mode":"narration","title":"写在纸上的事","opening":"七十岁这年，你在柜台后头放了一沓裁好的纸。早起第一件事是写：今天几号，店门怎么开，锁往哪边拧。写完抬头，柜台上已经贴着一张，字是你的，墨还没干，你不记得写过。架子上的瓶一只只排着，标签朝外，编号描过三遍，伸手去拿最上头那只，指尖碰到玻璃，凉的。门开了，一个年轻人进来，把一张合同复印件推过来，说他找 B-1147。","ask":"他把复印件推过来，等着你说话","days":30,"npc":"","memory":"柜台上的那张纸","choices":[{"title":"让他听一遍","desc":"你把抽屉拉开，取出瓶，把听膜递给他。","hint":"瓶里又薄了一层","tone":"warm","outcome":"他贴上听膜，听得很直，手放在柜台上不动。听完他说：不是我妈。他把瓶还给你，说了声对不起，走时顺走了柜台上的一张纸。你把瓶举到灯下看，底下的白又厚了一点。那天晚上你在纸上写：今天有人来听过，不是他的。写完又添一句：也不是我的了。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"瓶底那层白又厚了"}},{"title":"叫鉴证师来","desc":"你按住复印件，让学徒去港口叫鉴证师。","hint":"他妹妹在门口跪了一夜","tone":"report","outcome":"合同是照着旧格伪造的，编号抄错了一位。他被带走那天没挣，只问了一句：那我妈的瓶在哪儿。他妹妹在店门口跪了一夜，第二天清早走了，地上留着一只空布袋。你后来在假合同背面看见一行铅笔字，很小：妈，我找不到你的号了。你把那张纸收进抽屉，没交上去。","eff":{"bond":-2,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"恶":1},"flag":"reported_forged_claim","thread":"假合同背面那行铅笔字"}},{"title":"翻册子翻到天亮","desc":"你搬出十几本册子，一格一格找那个编号。","hint":"第二天你不记得他来过","tone":"grind","outcome":"你查到后半夜，字在眼前浮，一行看成两行。天亮时你在柜台上醒来，册子摊着，不记得是谁翻的。门开着，街上有人推车过去。你把册子合上，起身烧水，水开了才想起没放茶叶。那天没有人来，你也不记得有过一个年轻人站在柜台前，说过一个编号。","eff":{"bond":0,"health":-2,"reputation":0,"coins":0,"stats":{"智识":-1},"emotion":{"惧":4,"哀":3},"flag":"forgot_the_claimant","thread":"你不记得他来过"}}]},{"id":"sui2_s08","act":"side","age":[72,72],"mode":"narration","title":"别人的一生","opening":"漂忆港搬到新堤以后，摊子都挤在铁棚下，雾从棚顶的缝往下沉，落在肩上是一层白，闻着发甜。阿棠的店归了你，门口那块木牌还挂着：不收记忆。你把领子竖起来，衣角被风掀着走。一个十七八岁的后生支着折叠桌，桌上只摆一只大瓶，标签是他自己的字：别人的一生。他放样品：一个女人的笑，一个男人数楼梯，数到第七级停了。再往后是蝉。蝉声里冒出半句：你别老摸我手了，热。","ask":"后生问你要不要听，你怎么做","days":30,"npc":"","memory":"蝉声里的半句","choices":[{"title":"买一瓶回去听","desc":"你数出钱放在桌上，把那只大瓶抱回家，听了三夜。","hint":"左耳后来听不清了","tone":"seek","outcome":"三天三夜，别人家的婚丧、搬家、吵架、一碗面。第二夜过半，蝉声来了，那个十六岁的声音在里头说：你别老摸我手了，热。就三秒。你把这三秒放了一遍又一遍，瓶子一天比一天薄。医生让你别再用听膜，你换了右耳，写标签的时候手有点抖：非卖。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"欲":3,"哀":5},"flag":"bought_a_life","thread":"那三秒越放越薄"}},{"title":"叫鉴证师来","desc":"你退到棚外，借摊上的电话叫了港口的鉴证师。","hint":"他走时问你听出来了吧","tone":"report","outcome":"来了三个人，把瓶子一只只登记，说这是从公共库扫出来的碎段，拼起来卖，坏了规矩。后生被带走时回过头问你：你听出来了吧。你没答。三个月后店里收到一只小瓶，没有寄件人，标签上一个赠字。你把它放进缝纫机的抽屉，跟硬币、合同挨着，一直没打开。","eff":{"bond":-2,"health":0,"reputation":3,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"恶":2},"flag":"reported_life_seller","thread":"抽屉里那只赠字瓶"}},{"title":"教他写清来路","desc":"你让他把每段编号抄在瓶上，标签写明：拼的，不是一个人的。","hint":"你的店也被查了一回","tone":"teach","outcome":"他照写了，字歪，写了半宿。客人一看是拼的，掉头就走，一天卖不出一只。你让他把摊子挪到店门口，替你扫地从冬天扫到开春。净忆局来查执照，问这后生是谁，你说是学徒。他走那天从你架子上拿了一只瓶，你没拦。后来架子上空着的那一格，你一直没补。","eff":{"bond":3,"health":-1,"reputation":-1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":3},"flag":"taught_life_seller","thread":"架子上空着一格"}}]}]},"星耒野":{"no":6,"name":"星耒野","subtitle":"在陨尘里种下一点光","through":"父亲一辈子在等一场好星雨。你小时候觉得他傻，长大后才懂他种的不是粮食。","cast":[{"id":"father","name":"耒三","role":"夜灌农","tag":"父"},{"id":"mother","name":"穗娘","role":"种子库管理员","tag":"母"},{"id":"sibling","name":"小满","role":"陨铁城学徒","tag":"妹"}],"main":[{"id":"xing_m01","act":"main","age":[0,3],"mode":"montage","title":"夜灌灯","opening":"你生在陨季的第三夜。接生婆不敢点灯，说星雨前见火要招星，父亲就把夜灌灯提到门外，用背挡着。母亲的手很凉，翻你、拍你、剪脐带，一样一样做得很快。屋里有湿土和铁锈的味，窗纸上一闪一闪，是星尘在落。父亲进来时肩上落了一层白，他没拍，先蹲下去，把门槛下的一把土攥在手里捻。母亲把灯罩推上，说：推上，星就看不见咱们。你满月那天，父亲又这么蹲着。","ask":"父亲蹲在门槛边伸出手，你怎么办？","days":300,"npc":"","memory":"门槛下那撮土","choices":[{"title":"抓他手里的土","desc":"你把手指插进他掌心那撮土里，攥得指缝发黑。","hint":"土里有碎星，扎手。","tone":"learn","outcome":"父亲没松手，让你抓。碎星扎进你的指腹，你哭了一声，他才把土抖掉，说：这土认人。那晚他给你洗了三遍手，指甲缝里还是黑的。后来你三岁，能自己蹲在垄边抓土，抓起来先闻一闻。母亲说像个小老头。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":1},"flag":"","thread":""}},{"title":"跟她进冷房","desc":"母亲要去换班，你抱住她的腿，她只好把你抱进种子库。","hint":"你在冷房里烧了一夜。","tone":"family","outcome":"冷房的门一开，白气扑到脸上，你打了个抖。母亲一手抱你，一手点数，点到第三格时你开始发热。她把你裹在棉袄里跑回家，那一盘新芽没人翻，第二天冻坏了一半。她没跟父亲说，只把坏掉的芽埋进后院。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":""}},{"title":"指门让他走","desc":"你在他怀里扭，手指着门外，让他去看水。","hint":"他走时回头看了两次。","tone":"practical","outcome":"父亲愣了一下，把你放到母亲怀里，提灯出门。那夜的水放得比谁都匀，他回来时天已经亮了，蹲在门槛上看你，没伸手抱。母亲说他在渠边站了很久才走。你后来学会的第一件事，是听门外的脚步，辨他有没有回来。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":"他蹲在门槛上没伸手抱你"}}]},{"id":"xing_m02","act":"main","age":[5,5],"mode":"dialogue","title":"举起来","opening":"望星台的钟敲了三下，是星雨。全村的人往地棚里钻，母亲拽你，父亲却把你抱起来，往田埂上走。他说：看一眼，就一眼。天上一层一层地亮，像有人在上头撒谷。风里有烧石头的味。他把你举过头顶，你的影子落在垄上，亮了很久。星尘落在他头发上，白了一层。他抬头看了看台子，说：钟慢了一刻。","ask":"第一颗星落下来，你要做什么？","days":20,"npc":"father","memory":"亮了很久的影子","choices":[{"title":"拽他回地棚","desc":"你想起母亲的交代，攥住他的袖子，把他往地棚那边拖。","hint":"村里笑他白等一场。","tone":"obey","outcome":"他被你拖了两步，站住，弯腰把你抱进棚里。棚里的人都笑，说耒三的星雨让儿子搅了。他没笑，蹲在棚口看天，一直看到雨停，背上落满白。那年他的星历上少记了一场。母亲给你擦脸，什么也没说。","eff":{"bond":-2,"health":2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":2},"flag":"","thread":"他的星历上少记了一场"}},{"title":"睁着眼看完","desc":"你不躲，仰着头，把整场星雨一颗一颗看到尾。","hint":"你连着三夜梦见天在烧。","tone":"brave","outcome":"父亲的手一直托着你的肋。星落到第三阵，天忽然白了一下，你的眼睛疼了两天，闭着也看见亮斑。母亲用凉布给你敷，说：跟你爹一个样。你五岁那年记住的不是星，是他举着你时胳膊在抖，一直没放下。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":"你的眼睛疼了两天"}},{"title":"伸手去接","desc":"你从他肩上探出去，摊开手掌接落下来的星尘。","hint":"掌心留下一小点白。","tone":"risk","outcome":"一粒星尘落在你手心，烫出针尖大的一个白点，你没哭。父亲把你的手翻过来看了看，说：接住了？你说接住了。他笑了，说：傻。那点白跟了你一辈子，洗手洗不掉，冬天发亮。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":3,"惧":1},"flag":"palm_star_mark","thread":"掌心那点白跟你一辈子"}}]},{"id":"xing_m03","act":"main","age":[9,9],"mode":"narration","title":"发光的穗","opening":"九岁那年，你在西垄最边上一株麦子跟前蹲住了。天已经黑透，那穗子是亮的，不刺眼，像有人在穗心里点了一盏很小的灯。你伸手碰，穗子上的光就顺着你的手指爬到手腕。四周的麦都是黑的。你回头看，田埂上没有人，只有夜灌灯在远处一晃一晃。你听见自己的心跳，也听见穗子里有很细的响声，像米在锅里。","ask":"那株麦子在夜里亮着，你要做什么？","days":15,"npc":"","memory":"夜里发光的穗","choices":[{"title":"守它到天亮","desc":"你怕巡田的看见，蹲在垄边用身子挡着，守到天亮。","hint":"你误了早上的水。","tone":"wait","outcome":"天快亮时，穗子暗下去，像灯油烧尽。你伸手一摸，穗粒是空的，一捻就碎，掌心留下三粒黑的。你把它们藏进墙洞。母亲问你去哪了，你说看水。那天的水没放完，下游一垄旱了。三粒黑种你留到十四岁，没敢种。","eff":{"bond":2,"health":-2,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"kept_three_black_seeds","thread":"三粒黑种藏到十四岁"}},{"title":"报给巡田的","desc":"你跑去田头，把巡田的农盟人叫来看这株麦。","hint":"烧的是整垄，不只一株。","tone":"report","outcome":"巡田的人看了一眼，脸就沉了，说变异株要烧。他们抱来干草，把西垄边整整一垄都点了。火里噼啪响，那穗子亮到最后一下才灭。父亲赶到时只剩灰。他没骂你，蹲下去抓了一把灰，说：烧得对。那晚他没回家吃饭。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":3},"flag":"burned_variant_row","thread":"父亲那晚没回家吃饭"}},{"title":"移进米缸底下","desc":"你连根挖起，用衣襟包着，塞进灶边米缸底下。","hint":"母亲的手比缸底还凉。","tone":"sneak","outcome":"母亲当晚就发现了。她把那株麦拿出来，看了很久，没问哪来的，只说：以后别碰。她掀开米缸，底下已经压着一包纸包的种子。两包并排放着，她的手指在上面按了按。冷气从缸底漫上来，你打了个抖。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"惧":2,"爱":2},"flag":"saw_mother_packet","thread":""}}]},{"id":"xing_m04","act":"main","age":[14,14],"mode":"dialogue","title":"收糠的车","opening":"陨铁城的收糠车是午后进坑的。车轱辘上裹着布，压过田埂不出声。收购的人在晒场上摆开秤，秤砣是陨铁打的，黑得发亮。父亲把一袋星糠解开，让他看。那人抓了一把，用牙咬，说：潮。父亲说：这季雨多。那人报了个价，比去年低三成。小满穿着城里发的褂子，袖子长出一截，站在那人身后捧册子，说城里的仓房比咱家三间屋还大。父亲没看价牌，先问：明年的种粮，还能不能赊。","ask":"父亲伸手要按手印，你打算怎么办？","days":10,"npc":"father","memory":"帽檐里的契纸","choices":[{"title":"挡住那杆秤","desc":"你一脚踩上秤盘，说这个价不卖，让他把车赶走。","hint":"小满回城挨了罚。","tone":"defy","outcome":"收购的人把秤一收，说要走。父亲把你拉到身后，还是按了手印，价又低了一成。回家的路上他说：你一闹，明年的赊账就难了。他没骂你，只把那页契纸折得很小，塞进帽檐里。小满回城时没跟你道别。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"惧":2},"flag":"","thread":"小满手背上的竹条印"}},{"title":"替他捧墨盒","desc":"你双手捧住墨盒，看他把拇指按进墨里，再按在纸上。","hint":"你的指印也在下面。","tone":"carry","outcome":"他按完，把墨盒递给你，说：你也按一个。你说我又不是当家。他说：记着这个价。你就按了，拇指上沾了黑，回家洗了三遍才掉。那张契纸在城里存了二十年，上头两个指印，一个深，一个浅。后来城里来催，找的是下面那个浅的。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":2},"flag":"thumbprint_on_receipt","thread":"城里来催找的是你"}},{"title":"夜里藏两袋","desc":"半夜你和小满把两袋星糠藏进渠边的草垛里。","hint":"父亲让你当着人背回去。","tone":"greed","outcome":"第二天收购的人点数，差两袋。父亲看了你一眼，没说话，自己去草垛里把袋子拖出来，当着人扛回车上，回头还是按了手印。收购的人扣了半秤。回家父亲把那半袋糠倒进你的碗里，说：吃。你吃了三口就吃不下。","eff":{"bond":-3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":2},"flag":"","thread":""}}]},{"id":"xing_m05","act":"main","age":[18,18],"mode":"dialogue","title":"星尘进了眼","opening":"星雨提前了半宿。望星台的钟只响了一下就哑了，父亲还在西沟关闸。他回来时两只手捂着脸，指缝里往外淌水，睫毛上挂着一层白，像霜。他说：别点灯。母亲把夜灌灯的灯罩推上，屋里黑了。他坐在灶边，慢慢把手放下来，眼睛睁不开，眼白上有一片细碎的亮点，像撒进去的星糠。他一个字一个字地说：还好，还能看见土。","ask":"父亲的眼睛睁不开，你先做什么？","days":30,"npc":"father","memory":"眼白里的亮点","choices":[{"title":"跑去望星台","desc":"你光脚往台上跑，跑得上气不接下气，去叫守台的人。","hint":"来回八里，天亮了。","tone":"seek","outcome":"守台的人提着药箱跟你下来，天已经发白。他掰开父亲的眼皮看了看，说：洗晚了。他留下一个小瓷瓶，收了两升星糠。父亲的眼睛后来能看见路，看不清人脸。守台的人临走说：你们那块地，本来就不在台上眼里。父亲说：我知道。","eff":{"bond":1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"哀":4},"flag":"father_eyes_dim","thread":"父亲再没夜里下田"}},{"title":"含水给他冲","desc":"你含一口温水，凑过去，一点一点冲他眼里的白。","hint":"你咳了三年。","tone":"heal","outcome":"星尘顺着水进了你的喉咙，辣得像吞了碎瓷。父亲的眼睛冲出来一些，能睁开一条缝。你咳了半个月，后来每到星雨就咳，咳了三年。母亲说你是把星吃进去了。父亲听见了，蹲下去抓了把土，没说话。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"father_eyes_dim","thread":"你落下了星雨咳"}},{"title":"先熄那盏灯","desc":"你先把灯罩推死，才去扶他，因为灯会招星。","hint":"他自己上的药，没让你碰。","tone":"rule","outcome":"灯一灭，院里黑得看不见手。父亲往前迈了一步，踩空，整个人摔进排水沟，膝盖磕在石头上。你摸过去拉他，他先摸到你的手，说：灯灭了没有。你说灭了。他说：那就好。他自己上的药，没让你碰。","eff":{"bond":-2,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"哀":3},"flag":"father_eyes_dim","thread":"他膝盖上的伤养了一月"}}]},{"id":"xing_m06","act":"main","age":[23,23],"mode":"narration","title":"土里的声音","opening":"第一次独自守夜灌，是二十三岁那年。母亲把灯递给你，灯罩擦得很亮，教过你的那句话还在：推上，星就看不见咱们。父亲没出来，只在他屋门口说了一句：水走慢些。银穗坑的夜里有雾，麦子只到膝盖。你把水引进垄沟，蹲下去看水头。就在这时候，你听见土里有声音。不是虫，也不是水，是很低的一下一下，像有人在很深的地方敲一只空碗。你把耳朵贴到地上，土是温的。","ask":"土里的声音一直没停，你要怎么办？","days":10,"npc":"","memory":"土里的敲碗声","choices":[{"title":"挖开看","desc":"你用锹把声音那处的土挖开，挖到小臂深。","hint":"那东西整夜发烫。","tone":"seek","outcome":"挖出一块拳头大的陨铁，黑里透红，握在手里像握着一只刚熄的灶。声音停了。你把它包在衣襟里带回家，塞进墙洞。那夜以后，那块土一直比别处暖，麦子早熟了三天。你没跟任何人说。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"喜":3,"惧":2},"flag":"found_warm_iron","thread":"墙洞里那块陨铁整夜发烫"}},{"title":"把水让开","desc":"你把进水口改小，让水绕开那块地，自己那垄旱着。","hint":"那垄麦没抽穗。","tone":"protect","outcome":"水从垄边淌过去，那块地一滴没沾。你蹲在干土上听，声音慢慢平了，像有人睡过去了。那一季你那垄麦没抽穗，交糠时短了一截，你说是水没放匀。父亲看了一眼那块地，什么也没问。第二年，那块地的麦长得最好。","eff":{"bond":2,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"spared_the_ground","thread":"你那垄麦没抽穗"}},{"title":"叫醒父亲","desc":"你提着灯跑回家，把父亲从炕上叫起来。","hint":"第一夜就算没过。","tone":"elder","outcome":"父亲披衣出来，蹲在那块地上，把手掌平放下去，听了很久。他说：是土在记路，别挖。他陪你坐到天亮，回去就咳，咳了半个月。母亲说你不该叫他。你的第一夜守夜，按规矩不算过。你自己没再提。","eff":{"bond":4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"惧":2},"flag":"","thread":"父亲为这一夜咳了半月"}}]},{"id":"xing_m07","act":"main","age":[31,31],"mode":"dialogue","title":"他笑了","opening":"大星雨落了半夜。第二天的银穗坑像一只摔碎的碗。半个坑的土烧成黑玻璃，踩上去咯吱响，麦子只剩焦秆，玻璃上落着一层白，是星尘。农盟的人在坑边点数，谁家的地毁了。有人问父亲还种不种，他蹲着，隔了很久才慢慢说：种。父亲一处一处走，走到玻璃最厚的地方，蹲下去，把手掌贴在还烫的地上。他听了听，忽然笑了，笑得像咳嗽。他说：七十三垄，毁了四十一垄。他说：你听。","ask":"父亲蹲在玻璃地上笑，你怎么办？","days":20,"npc":"father","memory":"玻璃地上的笑","choices":[{"title":"跟着他听","desc":"你也蹲下去，把耳朵贴在烫土上，听底下的响。","hint":"村里说这家疯了。","tone":"warm","outcome":"底下有水在走，滴答滴答，像有人在玻璃下面敲碗。父亲说：我知道救不回来。可人得先信明年，不然这个冬过不去。他说：这半边，明年种什么都活。旁边的人摇头走了。第二年那半边果然出苗最齐。父亲没跟人争过一句。","eff":{"bond":5,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"喜":3,"爱":3},"flag":"understood_father","thread":""}},{"title":"把他拉走","desc":"你架住他的胳膊，把他从人群眼里拖回家。","hint":"他以后再没在你面前笑过。","tone":"protect","outcome":"他没挣，跟着你走，走到院门口才说：你不信。你说我信。他点点头，进屋去了。那天之后他还是下田，还是不紧不慢，只是再没跟你说过地里的事。毁掉的那半边，后来是他一个人收拾的。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"怒":2},"flag":"","thread":"他再没跟你说过地里的事"}},{"title":"下地捡穗","desc":"你不笑也不拉他，拿镰刀进焦地，去割那些没烧透的穗。","hint":"你的手割了七道口子。","tone":"carry","outcome":"焦秆脆，镰刀一碰就断，断口比刀子还利。你割到天黑，捡回三筐半焦的穗。父亲后半夜也来了，蹲在你旁边割。你们谁也没说话。那三筐穗打出两斗糠，掺着吃过了冬。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"手上的七道口子"}}]},{"id":"xing_m08","act":"main","age":[38,38],"mode":"dialogue","title":"清库","opening":"农盟来清库那天，种子库的冷房开着门，白气从门槛下往外爬，像水。母亲穿着棉袄，手冻得发红，把一格格种子搬出来点数。清库的人拿着册子，念到第三格时停住了：耒三，私种一袋，未上交。父亲站在门外，没进来。冷气扑到他脸上，他的眼睛眯起来。你看见母亲的手在围裙上擦了一下，又去搬下一格。","ask":"清库的人伸手去拉第三格，你拦不拦？","days":20,"npc":"mother","memory":"冷房的第三格","choices":[{"title":"抱走那袋种","desc":"你抢先把袋子抱在怀里，说这是我的，记在我名下。","hint":"罚的是明年一季的水。","tone":"protect","outcome":"清库的人看了你一眼，在册子上写下你的名字，罚了明年一季的水。父亲在门外听见了，转身就走。你抱着袋子在门口坐了一夜，第二天胳膊抬不起来。那袋种保住了，可那一季你家的田最后才放上水，秧苗比别家矮半截。","eff":{"bond":3,"health":-1,"reputation":-2,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"惧":3},"flag":"took_blame_for_seed","thread":"罚了明年一季的水"}},{"title":"指给清库的","desc":"你伸手一指第三格，说那袋在这里，按规定办。","hint":"父亲再没进过冷房。","tone":"report","outcome":"清库的人把袋子拖出来，倒进焚烧桶，冷房里全是烧纸的味。父亲在门外看着，没进来，也没说话。从那天起他再没进过种子库，连门口都不站。母亲照旧每天去冷房，回来时手更凉。","eff":{"bond":-5,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"burned_father_seed","thread":"父亲再没进过冷房"}},{"title":"换一个口袋","desc":"你趁人转身，把两袋种换了口袋，真的一袋塞进米缸。","hint":"母亲看了你很久。","tone":"sneak","outcome":"清库的人提走了半袋陈种，在册子上画了勾。母亲回家掀开米缸，看见那袋种，手停在缸沿上。她把缸盖轻轻放回去，说：你爹的种，你爹的命。她没让你交出去。那年冬天冷房封了一间，米缸底下挤着两包种子。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":3,"爱":2},"flag":"hid_two_packets","thread":"米缸底下挤着两包种"}}]},{"id":"xing_m09","act":"main","age":[47,47],"mode":"dialogue","title":"坡上","opening":"父亲是在田里走的。清早去看水，天黑没回来。你提灯去找，他靠在垄头木桩上，一只手还插在土里，夜灌灯的油烧干了，灯罩上结了一层星尘。他脸朝着望星台。葬在能看见台子的坡上，坟前立的是台上换下来的旧碑，正面刻了三个字：耒三。下葬那天小满跪着，话比谁都多，说她十二岁那年替城里记过父亲的名字，说城里仓房的钥匙她配过。父亲早就知道。","ask":"小满还跪在碑前不肯起，你怎么做？","days":30,"npc":"sibling","memory":"坡上那块旧碑","choices":[{"title":"把她拉起来","desc":"你伸手把她从土里拉起来，替她拍掉膝上的泥。","hint":"这事你们瞒了母亲一辈子。","tone":"warm","outcome":"她站起来还在说，说了很多，从城里的仓房说到册子的边角。你听着，没应。你在泥里跪久了，膝盖疼了半个月。母亲在坡下等，你们谁也没提。那以后小满每年回来，都在米缸里放一包城里的糖。母亲到走都不知道这件事。","eff":{"bond":3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":5},"flag":"","thread":"你们瞒了母亲一辈子"}},{"title":"让她去说","desc":"你说：你自己下去，跟母亲说。然后你走开。","hint":"母亲听完，把手炉放在了地上。","tone":"honest","outcome":"小满在坡下跪了很久，母亲听完，没打也没骂，只把手里的手炉放在地上，说：我早知道。她转身回屋，门没关。那晚小满在灶边坐了一夜。第二天母亲照常去冷房，回来时手更凉，谁也没再提。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":4},"flag":"","thread":"母亲把手炉放在了地上"}},{"title":"问她记的哪三个字","desc":"你问她，册子上写的是哪三个字，一笔一划怎么写的。","hint":"他的名字只留在别人册上。","tone":"ask","outcome":"小满用手指在碑前的土上写：耒、三。她说城里人不会写耒字，是她替他们写的。你看着那两个字，想起父亲蹲在地上抓土的样子。他的名字，除了这块碑，就只有城里那本册子还记着。","eff":{"bond":2,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":5,"爱":3},"flag":"knows_city_ledger","thread":"他的名字只在别人册上"}}]},{"id":"xing_m10","act":"main","age":[65,65],"mode":"narration","title":"爷爷种过星星吗","opening":"六十五岁这年，星雨来得晚。你带着小禾上坡，她六岁，走一半就要抱。你说自己走，走到台子底下给你买糖。她就自己走。坡上那块旧碑还在，字磨得只剩一个三。天黑下来，第一层星尘落在她头发上，她伸手去接，接了个空。她忽然问：爷爷真的种过星星吗。母亲走了八年，米缸还在灶边，缸底压着两包种子。","ask":"小禾仰着头等你回答，你怎么说？","days":30,"npc":"","memory":"爷爷种过星星吗","choices":[{"title":"领她进冷房","desc":"你带她下到种子库，开最后一间冷房，指那袋种。","hint":"冷气进了她的肺。","tone":"teach","outcome":"白气从门里涌出来，她咳了两声，还是往里走。你从袋里抓了一小把黑种，放进她手心，说：这是你太爷爷藏的。她攥着跑了。那年冬天你咳了一整季。第二年开春，墙根下冒出一株麦，瘦，夜里有一点微弱的光。她把那株麦当成宝，天天去看。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":4,"哀":3},"flag":"gave_last_seeds","thread":"墙根下的麦，她天天去看"}},{"title":"说她爷爷傻","desc":"你说他傻，等了一辈子雨，最后死在田里。","hint":"女儿在坡下听见了。","tone":"honest","outcome":"小禾问：那你还种？你说：不种吃什么。她想了想，说：那你也傻。女儿在坡下喊她，声音很硬。回家的路上谁也没说话。那年冬天小禾画了一张画，画里一个蹲着的人，头发上全是白点。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":"女儿听见你说他傻"}},{"title":"把她举起来","desc":"你学父亲的样子，把她举过头顶，让她看地上的影子。","hint":"你的胳膊疼了三天。","tone":"warm","outcome":"你举到一半，腰响了一声，还是举直了。她的影子落在坡上，被星照得很长。她说：爷爷也这样举过你吗。你说举过。她就不问了，伸手去够天。回去的路上她趴在你背上睡着了，你胳膊抖得扶不住栏杆。","eff":{"bond":5,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":5,"哀":2},"flag":"","thread":""}}]},{"id":"xing_m11","act":"main","age":[76,76],"mode":"narration","title":"最后一颗","opening":"七十六岁，望星台拆得只剩半截。农盟说坑田要退，种子库的冷房开到月底。夜里你带小禾上去，她十七了，在台上做记星雨的学徒。旧碑还立在坡上，字磨得只剩一个三。天上很干净，只有一颗星在往下走，走得很慢，像谁提着一盏灯找路。风里有烧石头的味。小禾把手里的灯罩推上又推开，等你说话。","ask":"那颗星正往坑心里落，你怎么做？","days":60,"npc":"","memory":"最后一颗星落下","choices":[{"title":"伸手去接","desc":"你把铜盆举过头顶，迎着那颗星，往前走了三步。","hint":"你的手从此端不住碗。","tone":"brave","outcome":"星落在盆里，盆底当场化了。你用手去捧，掌心烫出一片白，跟五岁那年那个点连在一起。你把那团东西埋进坑心，把缸底最后一把种按进去。天亮时土面顶出一根绿芽，不发光。你蹲下去看它，想起他说想种一茬不用看天色的庄稼。手包了三个月，后来端碗要用两只手。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"机缘":2},"emotion":{"爱":3,"哀":3,"喜":2},"flag":"caught_last_star","thread":"你的手端不住碗"}},{"title":"熄灯，不看它落","desc":"你把灯罩推死，背过身，听它自己走完最后一段。","hint":"在你的记忆里它还在天上。","tone":"wait","outcome":"灯一灭，天显得更大。你背对着坑心，听那颗星走，走过第三道渠，走到坡那边，才有一声很闷的响。小禾问你为什么不看。你说看了一辈子，这回让它自己走。第二年荒滩上绿了一片，农盟去划了新坑，叫野星坑，归了拾尘会。你始终没去看过。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"爱":3},"flag":"let_last_star_go","thread":"野星坑归了拾尘会"}},{"title":"把灯递给她","desc":"你把灯放进小禾手里，教她哪边关，哪边开，说：你来。","hint":"你没看见它落在哪。","tone":"teach","outcome":"她握着灯绳，手很稳，先看你一眼，然后把灯罩推死。你说：明年还会来。她说：那明年我还来。星落下去的时候你闭着眼，听见她轻轻数数。你们坐在坡上，谁也没再说话。天亮你醒了，她靠在你胳膊上睡着，天上什么也没有。","eff":{"bond":5,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":5,"哀":2,"喜":2},"flag":"passed_the_lamp","thread":""}}]}],"side":[{"id":"xing_s01","act":"side","age":[7,7],"mode":"narration","title":"收粮的独轮车","opening":"收粮的人是晌午到的，从陨铁城来，一个人，一辆独轮车，车把上挂着一杆铜盘小秤。父亲去望星台换星历，母亲在冷房当班，走时带出一股冷气。院里只有你，夜灌灯还挂在枣树上，灯罩推着。他把车停住，蹲下来跟你一般高，问：你家的糠在哪只缸里。他身上有煤烟和干鱼的味，袖口磨得发亮。秤盘边有一道旧焊痕，焊得发乌。晒场上的糠皮和星尘一起被风卷起来，落在他的睫毛上，他不掸。","ask":"他问糠在哪只缸里，你怎么答？","days":12,"npc":"","memory":"秤盘上的焊痕","choices":[{"title":"舀一升给他","desc":"你搬开缸盖，舀满一升倒进他的袋，没要他手里的盐。","hint":"母亲回来数过缸沿。","tone":"warm","outcome":"他愣了一下，把一小包盐放在门槛上，推车走了。母亲回来，手指在缸沿上抹了一圈，没问，晚饭的碗盛得比往常浅。那包盐她一直没拆，搁在灶神像后头，受潮结成了块。后来你才知道，那年城里也缺粮，收粮的人自己车上装的是麸。","eff":{"bond":0,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":1},"flag":"","thread":""}},{"title":"去冷房叫娘","desc":"你把院门闩上，跑去种子库，把母亲从冷房里叫回来。","hint":"冷房门开着，冻坏一盘芽。","tone":"tell","outcome":"母亲跑回来时围裙上还挂着白霜，收粮的人已经走了。冷房的门她没来得及关严，一盘新芽冻坏了半边，清点的人记了她一笔。她没骂你，只把冻坏的芽一粒粒捡进手心，说：叫得对。那晚她把手炉让给你，自己的手一直没暖过来。","eff":{"bond":2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"爱":2},"flag":"","thread":"冷房冻坏的那盘芽"}},{"title":"指去二娘家","desc":"你说家里的糠早卖了，抬手把他指到隔壁二娘的院门口。","hint":"二娘从此关着门。","tone":"dodge","outcome":"他推车去了二娘家。二娘卖了半袋，价钱比往年低，称完在门口站了很久。第二天她隔着篱笆问你：是你指来的？你说不是。她没再问，往后见了你就把门带上。那年冬天她家借糠，绕过了你家。你记得她的门闩声，比话还响。","eff":{"bond":-2,"health":0,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"xing_s09","act":"side","age":[10,10],"mode":"narration","title":"斗底的锡疤","opening":"十岁那年秋后，下坳村来了一个人，姓韩，站在院门外不进来。他手里提着一只斗，斗底裂过，用锡补了一道。他身后跟着个男孩，跟你差不多高，低头看自己的鞋。他说他们坑今年只收了三成，种子库进了水，想借半斗种，秋后还一斗。父亲在渠上，母亲在冷房。院角的种缸盖着草帘，缸口往外冒冷气。地里发光的麦穗在夜里亮成一片。夜灌灯挂在枣树上，灯罩推着。","ask":"他把斗递过来，你接不接？","days":30,"npc":"","memory":"斗底那道锡疤","choices":[{"title":"舀半斗给他","desc":"你搬开种袋，舀半斗好种倒进他的斗，没要他许的糠。","hint":"母亲回来点了三遍种袋。","tone":"help","outcome":"他连声道谢，把斗抱在怀里，走几步回一次头。母亲回来点了三遍种袋，没问，只把袋口重新扎紧。开春你家少种两垄，秋后短了半袋。第二年秋后他真的来了，背来一斗糠，糠里掺着沙。母亲收下，倒进猪食缸。那男孩站在门外，长高了一头，还是不看人。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":"他背来的一斗糠掺着沙"}},{"title":"领他去农盟","desc":"你锁上院门，把他领到农盟棚下，让巡田的照规矩登记。","hint":"他家的名字上了册。","tone":"rule","outcome":"巡田的人翻开册子，问坑名、户名、人口，一笔一笔记下，说私借种要两家连坐。他站在棚下，斗一直提在手里，走时没跟你说话。那年他家没借到种，春天地里荒着。秋后农盟发救济，按册子发，他家排在最后。他儿子后来在晒场上见你，绕着走。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":"他家排在救济册最后"}},{"title":"让他把斗留下","desc":"你说种要等父亲回来点，让他先把斗搁在门槛上。","hint":"那只斗搁了一秋。","tone":"dodge","outcome":"他把斗搁在门槛上，说下回再来，领着孩子走了。斗在门槛上放了一秋，落满星尘，你每天跨过去，渐渐看不见它。入冬他家孩子来讨斗，站在门外，你才想起。你把斗擦干净递过去，他接了，没再提借种的事。那道锡疤，你记了很多年。","eff":{"bond":-2,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"门槛上搁了一秋的斗"}}]},{"id":"xing_s02","act":"side","age":[11,11],"mode":"narration","title":"不肯发光的麦","opening":"十一岁那年，西垄的麦穗在夜里都亮，只有一株不亮。它比旁边的矮半尺，穗子却饱，麦芒发黄，摸上去是干的。你蹲在它跟前，风从坑心那边过来，带着冷气，别的麦穗沙沙响，它不响。巡田的人说，不发光的是病株，要拔。父亲蹲在另一头，用指甲掐开一粒，放进嘴里嚼，说：是甜的。夜灌灯挂在柳枝上，灯罩里积了一层星尘，风一吹，白灰往下掉。","ask":"天快亮了，这株麦你拔不拔？","days":20,"npc":"","memory":"一株不亮的麦","choices":[{"title":"把水让给它","desc":"你在垄头挖一道细沟，把夜里的水全引到它根下。","hint":"你那垄旱到抽不出穗。","tone":"protect","outcome":"水淌进它根下的土，土色深了一块。那株麦又活了七天，最后自己倒了，穗子散在垄上。你那垄麦旱得没抽穗，交糠时短了半袋。父亲没问水去了哪，只把散落的穗捡起来，搓出十几粒，装进一个小布袋。第二年他悄悄种在墙根，长出来的麦，夜里也不怎么亮。","eff":{"bond":2,"health":-2,"reputation":-1,"coins":0,"stats":{"体魄":1},"emotion":{"哀":2,"爱":2},"flag":"kept_dark_wheat","thread":"你那垄麦没抽穗"}},{"title":"叫巡田的来","desc":"你跑到田头，把巡田的人领到西垄，指那株麦。","hint":"父亲那天没吃晚饭。","tone":"report","outcome":"巡田的人蹲下看了一眼，说拔。他连根拔起，扔进草堆，火点得很小，像烧一把湿草。父亲站在旁边看，手插在袖子里，说：留着也活不成。那天晚饭他没上桌，母亲把碗端进屋，又原样端出来。西垄空出一个坑，后来的麦都往那边倒。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"惧":2,"哀":3},"flag":"","thread":""}},{"title":"移到棚后去","desc":"你连根挖起那株麦，栽到地棚后头的湿土里。","hint":"它的粒是甜的。","tone":"sneak","outcome":"它在地棚后活了半个月，没发光，也没死。秋后你收了小半把，搓开，粒是褐的，磨成粉掺进面里。父亲吃了两口，说今天的面怎么是甜的。你说不知道。那半把种你没舍得吃完，包起来塞进墙洞，跟往年攒下的几粒种放在一处。","eff":{"bond":1,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"喜":2,"惧":1},"flag":"","thread":""}}]},{"id":"xing_s10","act":"side","age":[16,16],"mode":"narration","title":"坑口冒冷气","opening":"十六岁那年，后半夜一声闷响，窗纸白了一下。你提灯跑出去，西头那块地中间多了一个坑，坑口两臂宽，往下看是黑的。坑壁像烧过的碗，摸上去还烫，坑口往外冒的却是冷气，扑在脸上像地窖里出来的风。夜灌灯倒在垄上，油洒了一片，灯芯还冒烟。父亲比你早到，蹲在坑边，一只手伸下去，停在半空。坑底一层白，是星尘。发光的麦穗倒在垄上，最后一点光从坑口透上来，照着他的下巴。","ask":"天快亮了，这个坑你打算怎么办？","days":20,"npc":"","memory":"坑口冒出的冷气","choices":[{"title":"指给拾尘会","desc":"你天不亮就去棚里，把坑指给无田的几户，说我家种不过来。","hint":"你家的地界缩进三尺。","tone":"warm","outcome":"他们扛着锹来，先围着坑磕三个头，才动手清坑壁。农盟按实种划界，你家地往里缩了三尺。父亲在界桩边蹲半晌，把桩扶正，没说话。你替他们挑了三天土，掌心磨出四个泡。那年坑里种出一片麦，夜里亮得很整齐。收糠时他们送来一小袋，父亲没动，你自己煮了吃。","eff":{"bond":1,"health":-1,"reputation":1,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"地界缩进的那三尺"}},{"title":"报到望星台","desc":"你跑上台，把落点报给守台的，让他们来插牌封坑。","hint":"父亲夜里去拔了一次牌。","tone":"rule","outcome":"守台的人午后下来，量了坑口，插一块黑木牌，写上落点号。你被记了一功，免了半季的巡田差。当天夜里父亲去拔牌，被巡田的撞见，罚了两斗糠。第二天他把牌子重新插好，插得比原来深。回来他洗了手才吃饭，一顿饭没抬头。","eff":{"bond":-3,"health":0,"reputation":2,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":"父亲拔过一次的木牌"}},{"title":"把种全倒进去","desc":"趁父亲回屋，你把家里留的种全倒进坑心，用脚踩实。","hint":"第二颗星跟着来了。","tone":"gamble","outcome":"出苗只用了七天，长得齐腰高，夜里一片亮，亮得能照见人脸。第九天夜里第二颗星来了，正落在坑里，把新苗连土掀到半空。地棚顶被掀掉一半，你额上留了一道疤。父亲清早去看，回来只说一句：坑吃种。那年你家没留种，开春跟人换了三升。","eff":{"bond":-4,"health":-2,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":2},"flag":"","thread":"额上那道疤"}}]},{"id":"xing_s03","act":"side","age":[17,17],"mode":"dialogue","title":"十二里路的沉默","opening":"十七岁秋后，你跟父亲去修渠首的闸。十二里路，来回一天。他一路上只说了三句话：走这边；水别踩；天要变。晌午坐在渠边啃冷馍，他把馍掰成两半，大的给你。他蹲着抓土，抓了很久，指缝里漏下去，又抓一把。两边的麦在夜里亮着，光落在渠水上，一晃一晃。你想说去城里的事，话到嘴边，他先站起来，说：走了。回来的路上你们没再说一个字。夜灌灯挂在车把上，星尘落在馍上，也没人掸。","ask":"到院门口了，这沉默你破不破？","days":10,"npc":"father","memory":"十二里的沉默","choices":[{"title":"蹲下抓把土","desc":"你在院门口蹲下，也抓一把土，摊在手心给他看。","hint":"那句话说回去，咽了很多年。","tone":"learn","outcome":"他停下来，看了你手心里的土，伸出两根手指，把里头一块碎星挑掉。他说：这土认人。这是他那天最后一句话。你去城里的话没出口，后来也没再找到那样的机会。第二年开春，他往你那双旧鞋里塞了半袋干粮，什么也没说。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":2,"哀":2},"flag":"left_words_unsaid","thread":"那句去城里的话没出口"}},{"title":"把话说完","desc":"你说冬天过后就跟小满进城，不再下田了。","hint":"他先进屋，门没关。","tone":"honest","outcome":"他听完，把夜灌灯从车把上解下来，塞进你怀里，说：城里也用得着。他先进了屋，门没关严，灯光从门缝里漏出来，照在门槛上。母亲在你门外站了很久，脚步声来回。你走的那天，他没送到坑口，只在你包里塞了一双新纳的鞋。","eff":{"bond":-4,"health":0,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":""}},{"title":"说个城里的笑话","desc":"你笑着说城里人管星糠叫土，把话岔过去。","hint":"他笑得不是地方。","tone":"dodge","outcome":"他笑了一声，笑得不是地方，笑完低头把灯芯剪短。那晚他多喝了一碗粥，母亲看了你一眼。后来你们还有过很多次沉默，可这一次不一样：这一次两个人都等着对方先开口，谁也没有。你后来想起渠上的风，总记得他掰馍时手上那层土。","eff":{"bond":-1,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":""}}]},{"id":"xing_s11","act":"side","age":[21,21],"mode":"dialogue","title":"灯下的怕死","opening":"二十一岁那年秋后，望星台来招记星的学徒，考三天，考上就住在台上。报名要一块竹牌，牌子搁在灶台上，还没写名字。那晚父亲让你替他穿针，针眼对着灯，怎么也对不上。他的眼睛是那年星尘灼坏的，看人只剩一个轮廓。线穿过去，他捏住，忽然说：我怕死。他说得很慢，像在说别人家的事。夜灌灯在桌上，灯罩落了一层星尘，冷气从门缝底下进来，贴着脚背走。窗外发光的麦穗一直亮到天亮。","ask":"他捏着线不动，你怎么接这句话？","days":15,"npc":"father","memory":"灯下那句怕死","choices":[{"title":"把竹牌烧了","desc":"你把那块没写名字的竹牌塞进灶膛，说：我不去了。","hint":"他没问为什么。","tone":"stay","outcome":"竹牌烧出一股焦味。他把针线放下，看了灶膛一眼，没问。第二天他照常天不亮下田，回来时给你带了一双新草鞋。台上的人第三天就走了，招满了。你留下替他放了三年水，学会看云、看风、看坑口的白气。三年后你想去考，招人的说，年纪过了。","eff":{"bond":4,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"爱":3,"哀":2},"flag":"","thread":"三年后再去，年纪过了"}},{"title":"说他的肺","desc":"你说星尘早进了他的肺，咳成这样，撑不过下个陨季。","hint":"他把种袋放下了。","tone":"honest","outcome":"他捏着针的手停在半空，过了很久，把种袋放下，说：我知道。那夜他咳得比往常久，母亲起来给他烧水。第二天他开始把地里的活一件件交给你，交得很急，像在赶什么。他不再下田，坐在门槛上看你走，看了三年。他到底又过了六个陨季。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"哀":4,"惧":2},"flag":"","thread":"他提前交出来的地"}},{"title":"让他教怕的事","desc":"你问他：你怕的事有几件，一件件教我，我记着。","hint":"他教得像在交代后事。","tone":"learn","outcome":"他愣了一下，笑了一声，说：你这孩子。第二天起他教你认星、听水、辨土，一样一样，讲到第三样时不讲了，说：够了。你后来才知道，他讲的都是他一个人会的，母亲一样也不会。那些话你记在本子上，本子后来受了潮，字糊了一半。","eff":{"bond":3,"health":0,"reputation":0,"coins":0,"stats":{"智识":2},"emotion":{"爱":2,"哀":3},"flag":"","thread":"受潮的本子"}}]},{"id":"xing_s04","act":"side","age":[26,26],"mode":"narration","title":"地棚底下的敲声","opening":"二十六岁那年陨季，你在地棚里守夜。星雨在外头，夜灌灯的灯罩推死了，棚里只闻得见草席和湿土。后半夜，土里有声音：三下，停一停，又三下。不重，像有人用指节敲一只扣着的碗。你把耳朵贴到地上，土是温的，比棚里的空气暖。你想起望星台的钟这些年一直缺一声，守台的人说钟舌早年丢了。棚外一阵风，星尘从缝里漏进来，落在手背上，像细盐。","ask":"那声音又响了三下，你怎么办？","days":15,"npc":"","memory":"土里三下敲碗声","choices":[{"title":"挖出来埋回去","desc":"你挖开棚底的土，把挖出的东西裹好，送到坡上无名坟前。","hint":"半袋种受了潮。","tone":"escort","outcome":"挖出来是一截铜舌，裹在烂布里，布上还系着一根褪色的绳。你冒雨把它送到坡上那座没有名字的坟前，挖了个浅坑埋了。回棚时灯被风吹灭，半袋种受了潮，出芽少了三成。那夜你咳到天亮，后来每到星雨就咳几声。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"buried_bell_clapper","thread":"半袋种受了潮"}},{"title":"报给望星台","desc":"天一亮你就上台，把地棚底下有东西的事说了。","hint":"阿婆再没跟你说过话。","tone":"report","outcome":"守台的人带着锹下来，挖走了那截铜舌，说要化了铸新钟。隔壁独眼的阿婆在棚外站了一夜，第二天问你：底下还有声音没有。你说没有了。她看了你很久，转身回屋，门关得很轻。从那以后她再没跟你说过话，晒场碰见也只点一下头。","eff":{"bond":-2,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":2},"flag":"","thread":""}},{"title":"把土拍平","desc":"你把土填回去，压上两块砖，吹灯睡了。","hint":"大星雨的夜里它还响。","tone":"keep","outcome":"土拍平了，砖也压上了。后来每到大星雨，那底下还是会响三下，不多不少。你没再挖，也没跟人说。住过这棚的人换了几茬，都说这棚子夜里不干净，睡到半夜总听见有人敲碗。你照旧每年住进去，照旧不解释。","eff":{"bond":0,"health":-1,"reputation":-1,"coins":0,"stats":{"机缘":1},"emotion":{"惧":3,"喜":1},"flag":"","thread":""}}]},{"id":"xing_s12","act":"side","age":[29,29],"mode":"narration","title":"图上那个矿字","opening":"二十九岁那年开春，陨铁城来了七个人、两辆车。他们在坑口立杆，红布被风吹得啪啪响。领头的人摊开图，银穗坑被画成一个方，方里一个字：矿。他说底下有陨铁脉，要整片收，签契的搬到坡上去，补三年糠。农盟的人手插在袖子里，不说话。地里发光的麦穗亮着，风里有冷气，把星尘刮到图上，那七个人也不掸。小满穿城里的褂子，站在后头，不看你。父亲把图倒着拿很久，递给你，说：你念。","ask":"图在你手里，你先念哪一段？","days":40,"npc":"","memory":"图上那个矿字","choices":[{"title":"把契念给全村","desc":"你站到碾盘上，把契从头到尾念一遍，念给围过来的人听。","hint":"你家的水先断了。","tone":"protect","outcome":"念到永不复耕那一句，人群里有人骂了一声，接着都骂起来。七个人收了图走了，说回去请示。第三天渠水小了，你家的田在渠尾，一滴没进。父亲扛着锹去渠首守了三夜，回来时鞋上全是泥。那年秋后，全村有一半人家偷偷签了。","eff":{"bond":2,"health":-2,"reputation":2,"coins":0,"stats":{"魅力":1},"emotion":{"怒":3,"哀":3},"flag":"","thread":"渠尾断水的那三夜"}},{"title":"劝父亲按手印","desc":"你把契上的条款一条条讲给他听，说这地种不下去了，签吧。","hint":"他按完手印去地里坐着。","tone":"practical","outcome":"他听完，把手在裤子上擦了擦，按了。按完他没回家，往银穗坑走，在界桩边坐到天黑。第二天他又去，坐了一整天。母亲送饭过去，碗原样端回来。头一年的糠发下来了，他一粒没动。搬上坡那天，他把夜灌灯挂在界桩上，没带走。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":2},"flag":"","thread":"界桩上挂着的灯"}},{"title":"让小满捎个名","desc":"你连夜找小满，让她把你的名字从户册上挪进城里去。","hint":"父亲的名字留在契上。","tone":"deal","outcome":"小满在册子上添了一笔，说下不为例。三天后你进了城，在仓房里点数星糠，手上不再有土。父亲一个人按了手印，一个人搬上坡。你走时他没送，只把你的旧鞋摆在门槛上，鞋里塞了一双新纳的。第二年你托人捎糠回去，糠退回来了，口袋是空的。","eff":{"bond":-4,"health":0,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":"退回来的空口袋"}}]},{"id":"xing_s13","act":"side","age":[39,39],"mode":"narration","title":"说星的人","opening":"三十九岁那年大星雨，村里人都进了地棚，只有坡口的瞎子全不肯进，坐在门槛上，脸朝天。他八岁瞎的，没见过星雨，耳朵却灵，能听出星落在第几道渠。风起来了，第一层星尘落在他的白发上，白上加白。坡下发光的麦穗看不出来，只听叶响。渠水泛上来一股冷气，贴着他的裤脚。夜灌灯在他脚边，灯罩推死了。他伸手在空气里摸，摸到你的袖子，说：你在这儿吧。你给我说说，它们长什么样。","ask":"他的手抓着你的袖子，你怎么说？","days":12,"npc":"","memory":"瞎子全的白头发","choices":[{"title":"坐下来慢慢说","desc":"你在门槛上坐下，一颗一颗说给他听，说到天亮。","hint":"你的麦烂在地里。","tone":"warm","outcome":"你说星是白的，落下来先亮一下，再暗一下，像有人在上头撒谷。他跟着点头，嘴里数着，数到七十三就乱了。天亮时他的眉毛上全是白。你那两夜该抢收的麦烂在垄上，穗子发了黑，一捻就碎。第二年春天他走了，走前跟人说，他看过一场星雨。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":3},"flag":"","thread":"烂在地里的两夜麦"}},{"title":"背他进地棚","desc":"你弯腰把他背上，任他捶你的背，塞进地棚里闩上门。","hint":"他再没跟人说过星。","tone":"protect","outcome":"他在棚里捶门，捶了很久，骂你不孝，骂到嗓子哑了才停。星雨过后他出来，谁问都不说话，坐在门槛上抽了半天旱烟。他冬天走的，收拾东西时，他儿子在拐杖上数出七十多道刻痕，一道一道，深浅不一。你不知道那是哪一年的星。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"怒":3,"哀":4},"flag":"","thread":"拐杖上的七十道刻痕"}},{"title":"转身去抢收","desc":"你说星雨没什么好看的，提灯下地，去割你自己的麦。","hint":"他在门槛上坐到天亮。","tone":"practical","outcome":"你割了两夜，麦子全进了仓，一粒没烂。回来时他还坐在门槛上，衣襟落满星尘，眉毛白了一层。他问你星落完了没有，你说落完了。他哦了一声，说：我听见了。那年冬天他走了。后来每次听见星落，你都想起那句我听见了，可你始终没告诉他，星是什么颜色。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":1},"flag":"","thread":"没告诉他的颜色"}}]},{"id":"xing_s05","act":"side","age":[41,41],"mode":"narration","title":"挂在梁上的种袋","opening":"四十一岁那年冬，米缸见了底，留种的布袋挂在灶房梁上。后半夜你听见灶房有响，提灯过去，看见邻家的石头踩在凳子上，一只手伸进种袋里，指甲缝里全是麦。他十二岁，瘦得脖子上的筋一根根看得清。见了你，手没抽出来，只说：我娘三天没吃东西了。窗外地里的麦还亮着，光贴在窗纸上。灯罩上落了一层白，是星尘，冷气从缸底往上冒，扑在脚背上。","ask":"他的手还在种袋里，你怎么做？","days":20,"npc":"","memory":"梁上的种布袋","choices":[{"title":"倒给他半袋种","desc":"你把他抱下凳子，倒半袋种给他，又抓两把糠掺进去。","hint":"开春你家少种两垄。","tone":"warm","outcome":"他抱着袋子跑了，跑到门口又回头，把掉在地上的几粒捡干净。开春你家少种两垄，秋后短了半袋。他娘清明那天来还空袋，袋里装着七个鸡蛋，蛋上沾着糠，放在门槛上就走了。那两垄荒了一年草，你没锄。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":1},"flag":"fed_stone","thread":"那两垄荒了一年草"}},{"title":"收袋报给农盟","desc":"你夺下种袋挂回梁上，天亮去农盟叫了巡田的人。","hint":"石头以后绕着你走。","tone":"report","outcome":"巡田的人来了，把石头带回家，在他家门上画了一道黑。他娘在门口跪了半宿，第二天照常去拾谷，没跟人说话。春天他家那块地荒着，草长到腰。你按规矩办了，那年冬天你家一粒没少。石头后来见你就绕着走，绕得很远。","eff":{"bond":-3,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"怒":2,"哀":3},"flag":"","thread":""}},{"title":"只留他吃一顿","desc":"你把种袋挂回梁上，用最后一点糠煮了粥，看他吃完。","hint":"他空着手回家了。","tone":"practical","outcome":"粥很稀，他喝得很快，碗底都舔干净了。你送他到门口，他站住，等你转身去拿种袋，你没转。他懂了，低着头走进黑里。第二天他娘来借簸箕，站在门外没进来。你后来常想起那只碗，碗沿上有一道缺口，是他咬的。","eff":{"bond":-1,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":1},"flag":"","thread":"碗沿上那道缺口"}}]},{"id":"xing_s14","act":"side","age":[52,52],"mode":"narration","title":"碎在石阶上的灯","opening":"五十二岁那年，孩子八岁，在院里追一只萤火虫。夜灌灯挂在枣树上，他跳起来够，手指勾住了灯绳。灯掉在石阶上，玻璃罩碎成三块，灯芯断在里面，油顺着阶缝淌到你鞋边。石阶缝里往上冒冷气，油淌过去，凝成一层薄壳。他站着一动不动，手背在身后，眼睛看地。那是父亲留下的灯，灯罩换过四次，铜底座磨得发亮。星尘落在碎玻璃上，白了一层。天快黑了，地里发光的麦穗还亮着，水没放。","ask":"他背着手站在那儿，你先做什么？","days":15,"npc":"","memory":"碎在石阶上的灯","choices":[{"title":"先看他的手","desc":"你蹲下去，把他的手从背后拉出来，一片一片看有没有割破。","hint":"你的手先出了血。","tone":"heal","outcome":"他手指肚上有一道白印，没出血。你去捡碎片，玻璃在掌心划开一道口子，血滴在灯座上。那晚你用一只粗陶碗盛油，搓了根棉线当灯芯，光只有原来一半。水放得慢，渠尾那一垄麦旱了一夜，穗子瘪了些。孩子睡在你旁边，一只手抓着你的衣角，抓了一夜。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":1},"flag":"","thread":"渠尾瘪下去的那垄麦"}},{"title":"领他到碑前","desc":"你收好碎片，牵着他上坡，让他跪在父亲碑前。","hint":"他半夜发起热来。","tone":"rule","outcome":"你让他跪着，说打碎祖物要跪到月亮偏西。他跪了，膝盖压在碎石上，一声没哭。后半夜他发起热来，说胡话，喊的不是你。你把他抱回屋，用凉布敷了一夜。第二天他把碎玻璃一片片捡进簸箕，手很稳。从那以后，他夜里走路总要先看一眼脚下。","eff":{"bond":-3,"health":-1,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"惧":4,"怒":1},"flag":"","thread":"他夜里总先看脚下"}},{"title":"进城配灯罩","desc":"你把碎片包进布，第二天进城，让锡匠比着配一个。","hint":"孩子以为这事过去了。","tone":"practical","outcome":"锡匠配了个新罩，白玻璃，点起来亮得刺眼。你回来时孩子已经睡了，你没叫醒他，也没提灯的事。新灯照在田里，影子比从前硬。第二年冬天，他把母亲留下的手炉从柜上碰下来，摔掉一只耳。他站在那儿看你，等你说话。你还是没说。","eff":{"bond":-2,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"惧":1},"flag":"","thread":"摔掉一只耳的手炉"}}]},{"id":"xing_s06","act":"side","age":[53,53],"mode":"dialogue","title":"最后一间冷房","opening":"入冬前，农盟贴了告示：老种子库最后一间冷房要在封冻前腾空，种并到新库去，冰脉归城里。母亲在库里干了三十年。那天她把告示从墙上揭下来，折成四折，塞进围裙口袋。白气从门槛底下往外爬，落在她裤脚上，结了一层薄霜。她把手伸进第三格，摸了很久，说：这格是你爹的。冷气把她的话托起来，又放下去。库里一排排木格黑着，只有她手边那盏夜灌灯亮着。","ask":"她站在冷房门口不动，你怎么办？","days":30,"npc":"mother","memory":"锁眼里的棉花","choices":[{"title":"陪她背完","desc":"你找出一条麻袋，把几百格种一袋一袋背去新库。","hint":"你的肩膀磨破了。","tone":"carry","outcome":"你们从天黑背到天亮，最后几趟她的腿在抖，还是不肯坐。你的肩膀磨破一层皮，抬了半个月。最后一格她没交，用围裙裹着塞进你怀里，说：拿回去，压米缸底下。冷房空了，门上了锁，她在锁眼里塞了一团棉花，说风从那儿进来。","eff":{"bond":5,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":4,"哀":3},"flag":"saved_last_room_seed","thread":"锁眼里的那团棉花"}},{"title":"按告示清点","desc":"你拿过册子，照格点数，把第三格的袋口扎紧上交。","hint":"她把手泡在凉水里。","tone":"rule","outcome":"清点的人把第三格的袋子倒进大麻袋，母亲伸手扶了一下袋口，没拦。她跟在后头把空格一格格擦干净，擦到第三格时停了一会儿。那天回家她把手泡在热水里，水凉了也没添。后来她再没提过种子库，围裙口袋里的告示也没拿出来。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"惧":2},"flag":"","thread":""}},{"title":"进城找小满","desc":"你连夜进城，让小满在农盟的册子上想办法。","hint":"她的名字被划掉了。","tone":"deal","outcome":"小满托了人，冷房多留一个月，代价是母亲的名字从册子上划掉，算提前退了。她在家坐了一个冬天，手一直凉，闲下来就擦那盏灯。房最后还是关了，只是晚了一个月。小满回来时带了一包城里的糖，母亲没吃，放在灯边化了一层。","eff":{"bond":1,"health":-1,"reputation":-1,"coins":0,"stats":{"智识":1},"emotion":{"哀":3,"爱":2},"flag":"","thread":""}}]},{"id":"xing_s07","act":"side","age":[58,58],"mode":"narration","title":"缸底的油纸包","opening":"母亲走后第二年，你才敢动那只米缸。缸里剩半缸陈糠，缸底垫着一块青砖。你搬开砖，底下是一个油纸包，包了三层，最里头用她的旧头巾裹着，角上打了个死结。纸上没有字。你打开，里面是黑亮的种，比麦粒大一圈，握在手里有点温。灶间很静，冷气从缸口往上冒，窗纸上落着星尘。夜灌灯在案上没点，灯罩擦得很干净。","ask":"这包种在你手里，你怎么处置？","days":30,"npc":"","memory":"母亲的头巾角","choices":[{"title":"分一半上坡","desc":"你留下一半，把另一半包好，连夜送到父亲坟前埋了。","hint":"回来的路上崴了脚。","tone":"escort","outcome":"你在坟前挖了个浅坑，把纸包放进去，土没埋严，留了一角油纸在外面。回来时你崴了脚，肿了半个月。另一半你用原来的油纸包好，塞回缸底。第二年春天，坟边的草里冒出几株黑麦，长得瘦，夜里没有一点光。你每年去割，割了捆好放在碑前，不吃。","eff":{"bond":3,"health":-2,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":3,"哀":4},"flag":"found_mother_packet","thread":"坟边那几株黑麦"}},{"title":"交到农盟去","desc":"你把油纸包原样提到农盟，报上母亲的名字。","hint":"小满在灶边坐了一夜。","tone":"report","outcome":"他们当着你的面把种倒进焚烧桶，火苗是绿的，没有烟。登记的人问名字，你说了穗娘，册子上多一行：私藏变异种一包，已销。小满从城里赶回来，在灶边坐了一夜，说：那是娘的。你说：我知道。她第二天一早就走了，走前把缸底那块青砖掀起来看了看，又放回去。","eff":{"bond":-4,"health":0,"reputation":1,"coins":0,"stats":{"智识":1},"emotion":{"哀":5,"惧":2},"flag":"","thread":""}},{"title":"夜里种三粒","desc":"你趁夜在墙根下挖了三个坑，埋进三粒黑种。","hint":"它的穗是黑的。","tone":"sneak","outcome":"出苗很快，长得比人高，穗子是黑的，不发光。秋后你收了一小袋，磨面吃了，味道发苦，吃完嘴里一整天都是铁的味。剩下的你用油纸包好，放回缸底，压上青砖。那包种一直在那儿，你每次舀糠都听见纸响，像有人在底下翻身。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"机缘":1},"emotion":{"惧":2,"喜":2},"flag":"","thread":""}}]},{"id":"xing_s15","act":"side","age":[70,70],"mode":"narration","title":"一个人的田","opening":"七十岁那年陨季最后一夜，村里只剩几户，都上了坡。你一个人留在银穗坑守水。望星台的钟没响，守台的年轻人上月走了，台上没人值夜。渠水走得很慢，田里发光的麦穗一片很淡的光。你把夜灌灯放在埂上，灯罩开着，火苗只有指甲盖大。后半夜风向变了，冷气从渠底翻上来，星尘开始落，落在灯罩上，沙沙地响。渠埂内侧渗出一个洞，水从洞里往外冒，把土泡软了，一点一点往下塌。","ask":"洞越冲越大，你一个人怎么办？","days":30,"npc":"","memory":"一个人守到天亮","choices":[{"title":"躺进渠沟堵洞","desc":"你把灯塞进怀里推死，躺进渠沟，用背抵住那个洞。","hint":"天亮时你站不起来。","tone":"carry","outcome":"水从你背底下渗过去，冷得像刀。星尘落在你脸上，落一层化一层。你数着数，数到八百多，天边才白。那垄麦保住了，只倒了三株。小禾早上下来找你，看见你躺在沟里，吓得把灯都摔了。她拖不动你，跑去叫人。你的腰在床上躺了一个月。","eff":{"bond":3,"health":-3,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"惧":3,"爱":2},"flag":"","thread":"腰躺了一个月"}},{"title":"关死上游的闸","desc":"你摸黑走到渠首，把闸门一格格压死，断了这一夜的水。","hint":"下游三家的田旱了。","tone":"rule","outcome":"闸门压到底，水声一下子没了，渠里只剩泥响。你回来时洞不再冒水，埂保住了。天亮下游三家的人站在渠口骂，说自家的田旱了一夜。你没解释，把闸重新提起来，让水先往他们田里走。那一季你家的水排在最后，麦比人家矮半尺。","eff":{"bond":-2,"health":-1,"reputation":-2,"coins":0,"stats":{"智识":1},"emotion":{"怒":3,"哀":2},"flag":"","thread":"下游三家的骂声"}},{"title":"提灯去坡上叫人","desc":"你提着灯往坡上走，挨家敲门，把能叫的人都叫起来。","hint":"你回去时埂已经塌了。","tone":"seek","outcome":"你敲开三家门，只起来两个老人，一个瘸，一个咳。等你们回到田里，埂已经塌了半丈，水冲过一垄，麦倒在泥里。大家站在埂上看了很久，谁也没下去。天亮你一个人把倒的麦一株株扶起来，扶不直。小禾蹲在田头，问你：明年还种吗。你说种。","eff":{"bond":1,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"哀":4,"爱":2},"flag":"","thread":"扶不直的那一垄麦"}}]},{"id":"xing_s08","act":"side","age":[74,74],"mode":"narration","title":"只落了三颗星","opening":"七十四岁这年，陨季只落了三颗星。望星台的钟没响，守台的年轻人说，三颗不算雨，值不得开钟。村里人还是都出来了，站在田埂上仰头，像等一句没等来的话。第一颗落在坑心，第二颗落在渠那边，第三颗很小，落在坡上父亲那块旧碑旁边。坡下的麦穗不亮。夜灌灯在脚边，灯罩推着。拾尘会的丫头攥住你的衣角，问：就这么多了吗。你说：还有，剩下的堵在云后头。话出口才知道自己撒了谎。","ask":"话已经出口，她还仰着脸等，你怎么做？","days":40,"npc":"","memory":"只落三颗的夜","choices":[{"title":"把谎圆下去","desc":"你说再等两天，星从云后头来，还给她数了三回。","hint":"她会在坑口等很多天。","tone":"warm","outcome":"她信了，掰着手指头数，每天傍晚跑到坑口看天。过了两天没有星，她又来问，你又说了一遍。你把棉袄脱下来裹住她，自己咳了一冬。那年冬天没有第二场星雨，她把那三颗画在棚子的土墙上，画了满满一面，最后一颗画在坡那边。","eff":{"bond":4,"health":-2,"reputation":0,"coins":0,"stats":{"魅力":1},"emotion":{"爱":3,"哀":2},"flag":"lied_to_child_about_stars","thread":"她会在坑口等很多天"}},{"title":"把话收回","desc":"你蹲下来，说刚才那是哄她的，今年不会再有星了。","hint":"她的手从你衣角上松开。","tone":"honest","outcome":"她没哭，手从你衣角上松开，走回棚里，路上没回头。第二天拾尘会的人来借种，你把种拿出来，他们看了看天，又放下了，说：没雨，种了也白种。那年冬天棚里走了四户。她走前问你那三颗叫什么，你说了三个名字，她记不住，还是跟着车走了。","eff":{"bond":-3,"health":0,"reputation":0,"coins":0,"stats":{"智识":1},"emotion":{"哀":4,"怒":1},"flag":"","thread":""}},{"title":"抱她上坡","desc":"你不再说星，把她抱起来，走到碑边看那点亮灭下去。","hint":"她以后见你只点头。","tone":"carry","outcome":"她趴在你肩上看，看到那点亮灭下去，说：像灯。你说：像灯。她把脸埋在你颈窝里，没再问星的事，你也没再提云后头的话。回去的路上她睡着了，你抱着走了一里，胳膊抖得厉害。后来她长大，在晒场见了你总要点一下头，不亲，也不远。","eff":{"bond":2,"health":-1,"reputation":0,"coins":0,"stats":{"体魄":1},"emotion":{"爱":2,"哀":2},"flag":"","thread":""}}]}]}};
const STORY_ORDER=["穗骨原", "无昼京", "借寿渡", "钟葬群岛", "髓云都市", "星耒野"];
